// Content for Firewall (node g40, ages 12–15, Chapter 4) — NEW v2 build to GDD 40 (mechanic-embodying), the
// teen ONLINE-SAFETY node (Thread B · Safety, Consent & Boundaries) — high-stakes safeguarding handled CALM,
// never fear-mongering. "Stay alert and in control, not frightened." 84 researched, India-grounded,
// non-explicit scenarios across the spot-grooming → think-before-share → sextortion-plan → myths-busted →
// lock-it-down → find-help-no-blame arc, each encoded as one of the shared v2 play actions (branch /
// strike-rewrite / spot / sort / role-play / reflect / match) — no binary "tap the right card". Lead
// mechanics: branch (the safe-move chooser ×22), spot (catch grooming red flags ×12), role-play (the words
// ×9). Teaches: spotting grooming & fakes, thinking before you share (footprint), and the signature
// SEXTORTION PLAN — DON'T PANIC, DON'T PAY, DON'T SEND MORE, it's NOT YOUR FAULT, save the evidence (block
// but don't delete), tell a trusted adult, report. NON-EXPLICIT, NEVER VICTIM-BLAMING, NEVER how-to-harm.
// POCSO / IT-Act aware: a minor is a PROTECTED VICTIM, never in trouble. Real routes — a trusted adult,
// cybercrime.gov.in / 1930, Childline 1098. Builds on g15 (Boundary Bot); prereq g27. Rendered by the shared
// engine (components/games/v2-engine.tsx). gameId "firewall". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — Who's really there: spot grooming & fakes —
  {"id":"fw-001","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the grooming red flags in this chat.","scene":[{"id":"a","text":"A new 'friend' showers you with flattery and gifts","trick":true},{"id":"b","text":"They ask about your favourite game","trick":false},{"id":"c","text":"They want to move to a private, disappearing-message app","trick":true},{"id":"d","text":"They reply to a few of your stories","trick":false},{"id":"e","text":"They mention a game update you both saw","trick":false}],"why":"Flattery-plus-gifts and pushing to a private app are classic grooming flags.","relearn":"Flattery, gifts and 'let's go private' are grooming flags."},
  {"id":"fw-002","cat":"spot-grooming","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags here.","scene":[{"id":"a","text":"They insist you keep the chat a secret","trick":true},{"id":"b","text":"They like the same music as you","trick":false},{"id":"c","text":"They say you have a 'special connection' after a day","trick":true},{"id":"d","text":"They ask which artist you saw live","trick":false},{"id":"e","text":"They share a public playlist","trick":false}],"why":"Secrecy and fast 'special closeness' are how groomers build a trap.","relearn":"Secrecy and instant 'special bond' are warning signs."},
  {"id":"fw-003","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags here.","scene":[{"id":"a","text":"'I'm your age too, promise' with no proof","trick":true},{"id":"b","text":"They have one new account, no real friends on it","trick":true},{"id":"c","text":"Their profile photo is just a meme","trick":false},{"id":"d","text":"They post about a school holiday","trick":false},{"id":"e","text":"They reply during normal daytime hours","trick":false}],"why":"The 'I'm your age too' line and a brand-new, friendless account are red flags.","relearn":"'I'm your age too' with a brand-new, empty account is a grooming lie."},
  {"id":"fw-004","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags here.","scene":[{"id":"a","text":"Messaging you intensely at 1-3 a.m.","trick":true},{"id":"b","text":"They ask which school you go to and where you live","trick":true},{"id":"c","text":"They send a funny video","trick":false},{"id":"d","text":"They ask about your favourite subject","trick":false},{"id":"e","text":"They share a meme everyone's posting","trick":false}],"why":"Odd-hours intensity and fishing for your school/location are red flags.","relearn":"Late-night intensity and 'where do you live?' are warning signs."},
  {"id":"fw-005","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags that matter most here.","scene":[{"id":"a","text":"After flattery, they ask for a private photo","trick":true},{"id":"b","text":"They chat about homework","trick":false},{"id":"c","text":"They say 'don't tell anyone about us'","trick":true},{"id":"d","text":"They ask if you watched a popular show","trick":false},{"id":"e","text":"They wish you luck for a test","trick":false}],"why":"Asking for photos plus 'don't tell anyone' is grooming, full stop.","relearn":"A photo request plus 'keep it secret' is a serious red flag."},
  {"id":"fw-006","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags (the rest are harmless).","scene":[{"id":"a","text":"A classmate you know messaging about a project","trick":false},{"id":"b","text":"A stranger 'casting' you for fake modelling","trick":true},{"id":"c","text":"A 'send a pic' dare from a new contact","trick":true},{"id":"d","text":"A friend tagging you in a group photo","trick":false},{"id":"e","text":"A teammate asking about practice time","trick":false}],"why":"A known classmate about real work is fine; fake casting and a 'send a pic' dare are the flags.","relearn":"Fake casting and a 'send a pic' dare are the red flags."},
  {"id":"fw-007","cat":"spot-grooming","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the grooming, even from someone you 'know' online.","scene":[{"id":"a","text":"An older 'gamer friend' slowly isolates you from others","trick":true},{"id":"b","text":"You've chatted for weeks","trick":false},{"id":"c","text":"They test you with 'would you ever send a pic?'","trick":true},{"id":"d","text":"They congratulate you on a win","trick":false},{"id":"e","text":"They share a clip from a match","trick":false}],"why":"Isolation and boundary-testing are grooming, even from a familiar contact.","relearn":"Grooming can come from a familiar online 'friend', watch for isolation and testing."},
  {"id":"fw-008","cat":"spot-grooming","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two catfish tells.","scene":[{"id":"a","text":"Photos that look like a stock model","trick":true},{"id":"b","text":"They refuse any live video call, ever","trick":true},{"id":"c","text":"They type in full sentences","trick":false},{"id":"d","text":"They post an everyday, blurry pic","trick":false},{"id":"e","text":"They mention a real, checkable school fest","trick":false}],"why":"Stock-style photos and never doing a live call are classic catfish tells.","relearn":"Model-perfect photos plus 'never video call' often mean a fake profile."},
  {"id":"fw-009","cat":"spot-grooming","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a grooming red flag, or something normal?","items":[{"id":"a","text":"Pushing you to a secret, private chat"},{"id":"b","text":"A friend tagging you in a meme"},{"id":"c","text":"Gifts and flattery from a stranger"},{"id":"d","text":"A group chat for your class"},{"id":"e","text":"'Don't tell your family about me'"},{"id":"f","text":"A classmate sharing notes"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"normal","label":"Normal","valence":"pos"}],"key":{"a":"flag","b":"normal","c":"flag","d":"normal","e":"flag","f":"normal"},"relearn":"Secret chats, stranger gifts and 'don't tell family' are flags; ordinary friend stuff isn't."},
  {"id":"fw-010","cat":"spot-grooming","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a grooming red flag, or normal?","items":[{"id":"a","text":"\"Don't tell your parents about me\""},{"id":"b","text":"\"Want to play this weekend?\" from a real friend"},{"id":"c","text":"Asking for your home address early"},{"id":"d","text":"A study reminder from a classmate"},{"id":"e","text":"'Send a pic to prove you trust me'"},{"id":"f","text":"A friend wishing you luck for exams"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"normal","label":"Normal","valence":"pos"}],"key":{"a":"flag","b":"normal","c":"flag","d":"normal","e":"flag","f":"normal"},"relearn":"Secrecy, early 'where do you live?' and 'prove it with a pic' are flags; real friends aren't."},
  {"id":"fw-011","cat":"spot-grooming","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: builds a trap, or builds real friendship?","items":[{"id":"a","text":"Rushing you to feel 'special' fast"},{"id":"b","text":"Getting to know you slowly, in the open"},{"id":"c","text":"Isolating you from other friends"},{"id":"d","text":"Respecting when you log off"},{"id":"e","text":"'Nobody understands you like I do'"},{"id":"f","text":"Being fine with your parents knowing them"}],"bins":[{"id":"trap","label":"A trap","valence":"neg"},{"id":"real","label":"Real friendship","valence":"pos"}],"key":{"a":"trap","b":"real","c":"trap","d":"real","e":"trap","f":"real"},"relearn":"Rushing, isolating and 'only I get you' is a trap; slow, open, respectful is real."},
  {"id":"fw-012","cat":"spot-grooming","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a safe move with a new online contact, or risky?","items":[{"id":"a","text":"Keeping your school and address private"},{"id":"b","text":"Sending a photo to 'prove' you trust them"},{"id":"c","text":"Telling a trusted adult about an odd request"},{"id":"d","text":"Moving to a secret app at their push"},{"id":"e","text":"Saying no to a live-location share"},{"id":"f","text":"Doing a 'private verification' video"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Guard your info and tell an adult; don't 'prove trust' with pics or apps."},
  {"id":"fw-013","cat":"spot-grooming","type":"strike-rewrite","hook":"\"People online are always who they say they are.\"","myth":{"un":"People online are always who they say they are.","re":"Some are; some aren't, profiles and ages can be faked, so verify and stay private.","why":"Catfishing and fake ages are common grooming tools."},"relearn":"Online, people aren't always who they claim; verify and guard your info.","persona":"any","source":"catfishing"},
  {"id":"fw-014","cat":"spot-grooming","type":"strike-rewrite","hook":"\"If they're nice to me, they must be safe.\"","myth":{"un":"If someone's really nice to me online, they must be safe.","re":"Groomers often start with flattery and gifts; kindness isn't proof of safety.","why":"'Love-bombing' is a deliberate grooming tactic."},"relearn":"Flattery isn't proof of safety; groomers often start kind.","persona":"Riya","source":"grooming tactic"},
  {"id":"fw-015","cat":"spot-grooming","type":"strike-rewrite","hook":"\"Grooming only happens to little kids, not teens.\"","myth":{"un":"Grooming only happens to younger kids.","re":"Teens are very much targeted; knowing the pattern keeps you safe.","why":"The teen years are among the highest-risk for online exploitation."},"relearn":"Teens are targeted too; knowing the grooming pattern protects you.","persona":"any","source":"risk awareness"},
  // — Think before you share —
  {"id":"fw-016","cat":"think-before-share","type":"branch","hook":"Your crush asks you to send a private photo to 'prove you like them'.","options":[{"text":"Say no; a real crush won't pressure you like that","consequence":"You hold your boundary and see what their reaction reveals.","outcome":"boundary","best":true},{"text":"Send it so they don't lose interest","consequence":"'No' is always valid; the pressure is the red flag."}],"debrief":"Pressuring you for photos is a red flag, not love.","relearn":"'No' to a photo is always valid; pressure is the red flag.","persona":"Riya","source":"resisting pressure"},
  {"id":"fw-017","cat":"think-before-share","type":"branch","hook":"A photo sent 'just to one person' could go anywhere. You think...","options":[{"text":"Anything sent can be copied and spread, I'll keep it private","consequence":"You protect yourself before there's anything to regret.","outcome":"footprint","best":true},{"text":"It's fine, they'd never share it","consequence":"Anything sent can be screenshotted and spread."}],"debrief":"Once sent, you lose control of it, so think before you share.","relearn":"What you send can be copied and spread; you can't take it back.","persona":"any","source":"permanence / footprint"},
  {"id":"fw-018","cat":"think-before-share","type":"branch","hook":"A partner keeps pushing after you said you don't want to send pictures.","options":[{"text":"Hold your no; reconsider a partner who won't respect it","consequence":"You keep your boundary and see them clearly.","outcome":"respect","best":true},{"text":"Give in to keep the peace","consequence":"A partner who won't take 'no' on this is the problem, not you."}],"debrief":"Respecting 'no' is the bar; someone who won't isn't treating you right.","relearn":"A partner who won't respect your 'no' on photos is a red flag.","persona":"any","source":"consent / pressure"},
  {"id":"fw-019","cat":"think-before-share","type":"branch","hook":"You're about to post something revealing your school, routine and location.","options":[{"text":"Keep location and routine off public posts","consequence":"You shrink your exposure to strangers.","outcome":"private","best":true},{"text":"Post it, everyone does","consequence":"Public location and routine can reach the wrong people; keep them off."}],"debrief":"Your footprint includes where you are, guard it.","relearn":"Keep your school, routine and location out of public posts.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-020","cat":"think-before-share","type":"branch","hook":"Friends are daring each other to send risky pics in a group.","options":[{"text":"Opt out, and don't screenshot or pass any on","consequence":"You stay safe and don't spread anyone's images.","outcome":"safe","best":true},{"text":"Join in so you're not 'boring'","consequence":"Opt out; passing images on can harm others and is not worth a dare."}],"debrief":"You can sit out a dare, and never forwarding protects everyone.","relearn":"You can opt out of risky dares and never forward others' images.","persona":"Veer","source":"peer pressure"},
  {"id":"fw-021","cat":"think-before-share","type":"branch","hook":"An old post of yours could resurface years later. What's the smart habit?","options":[{"text":"Post as if a future you, and others, might see it","consequence":"Your footprint stays something you're glad of.","outcome":"wise","best":true},{"text":"Post anything; the internet forgets","consequence":"Posts can resurface; post with future-you in mind."}],"debrief":"A digital footprint lasts; a moment's post can outlive the moment.","relearn":"Post with future-you in mind; your footprint can last and resurface.","persona":"any","source":"footprint"},
  {"id":"fw-022","cat":"think-before-share","type":"strike-rewrite","hook":"\"Everyone sexts, it's no big deal.\"","myth":{"un":"Everyone sexts; it's no big deal.","re":"Not everyone does, and the risks are real; 'no' is always okay.","why":"'Everyone's doing it' is pressure, not a fact."},"relearn":"Not everyone sexts; the risks are real and 'no' is always okay.","persona":"any","source":"myth / pressure"},
  {"id":"fw-023","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I send it, it'll stay private.\"","myth":{"un":"If I send it to just one person, it'll stay private.","re":"Nothing sent is ever guaranteed private; it can be saved and shared.","why":"A screenshot is all it takes."},"relearn":"Nothing you send is guaranteed private; it can be saved and shared.","persona":"any","source":"permanence"},
  {"id":"fw-024","cat":"think-before-share","type":"strike-rewrite","hook":"\"Deleting it makes it gone for good.\"","myth":{"un":"Deleting a photo or post makes it gone for good.","re":"Copies and screenshots can survive after you delete; assume it can persist.","why":"You can't delete what others have already saved."},"relearn":"Deleting doesn't guarantee it's gone; copies can persist.","persona":"any","source":"footprint"},
  {"id":"fw-025","cat":"think-before-share","type":"sort","hook":"Sort: keeps your footprint safe, or grows your risk?","items":[{"id":"a","text":"Private account, friends you know"},{"id":"b","text":"Public posts of your daily route"},{"id":"c","text":"Thinking before you share"},{"id":"d","text":"Sending images to prove trust"},{"id":"e","text":"Turning off live location"},{"id":"f","text":"Your school in your public bio"}],"bins":[{"id":"safe","label":"Keeps you safe","valence":"pos"},{"id":"risk","label":"Grows your risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Private accounts and thinking first keep you safe; over-sharing grows risk.","persona":"any","source":"footprint"},
  {"id":"fw-026","cat":"think-before-share","type":"sort","hook":"Sort: a valid reason to send, or pressure to resist?","items":[{"id":"a","text":"\"If you loved me you'd send it\""},{"id":"b","text":"You simply don't want to"},{"id":"c","text":"\"Everyone's sent one\""},{"id":"d","text":"\"Send it or we're over\""},{"id":"e","text":"You want to and feel safe (your call)"},{"id":"f","text":"\"Don't be boring, just do it\""}],"bins":[{"id":"resist","label":"Pressure to resist","valence":"neg"},{"id":"valid","label":"Your valid choice","valence":"pos"}],"key":{"a":"resist","b":"valid","c":"resist","d":"resist","e":"valid","f":"resist"},"relearn":"'Not wanting to' is reason enough; guilt-trips and threats are pressure.","persona":"Riya","source":"consent / pressure"},
  {"id":"fw-027","cat":"think-before-share","type":"sort","hook":"Sort: respects your boundary, or crosses it?","items":[{"id":"a","text":"A partner who hears 'no' and stops"},{"id":"b","text":"A partner asking again after 'no'"},{"id":"c","text":"Someone who never pressures you"},{"id":"d","text":"Someone guilt-tripping you to send"},{"id":"e","text":"A crush who says 'no problem'"},{"id":"f","text":"Threatening to leave unless you send"}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"cross","label":"Crosses the line","valence":"neg"}],"key":{"a":"respect","b":"cross","c":"respect","d":"cross","e":"respect","f":"cross"},"relearn":"Respect means hearing 'no'; repeated asking and guilt are red flags.","persona":"any","source":"respect"},
  {"id":"fw-028","cat":"think-before-share","type":"role-play","hook":"A partner is pressuring you to send a photo.","setup":"Hold your boundary. Say:","yourLine":[{"text":"\"No. I'm not comfortable with that, and that's final.\"","best":true},{"text":"\"...okay, fine.\""}],"relearn":"A clear, final 'no' is a complete answer to photo pressure.","persona":"Riya","source":"boundary voice"},
  {"id":"fw-029","cat":"think-before-share","type":"role-play","hook":"A friend asks you to forward a private pic of someone else.","setup":"Refuse and protect them. Say:","yourLine":[{"text":"\"No, I'm not passing that on, it's not ours to share.\"","best":true},{"text":"Forward it"}],"relearn":"Refusing to forward a private image protects the person in it.","persona":"any","source":"never forward"},
  // — Sextortion: don't panic (the plan) —
  {"id":"fw-030","cat":"sextortion-plan","type":"branch","hook":"Someone threatens to share a private image unless you pay.","options":[{"text":"Don't pay, don't send more, save the evidence and tell a trusted adult","consequence":"You take away their power and get help.","outcome":"plan","best":true},{"text":"Pay them so it goes away","consequence":"Paying often makes it worse; don't pay, get help."}],"debrief":"Paying rarely stops sextortion; don't pay, save, tell, report.","relearn":"If threatened: don't pay, don't send more, save evidence, tell an adult.","persona":"Veer","source":"sextortion response (NCMEC/FBI, verified)"},
  {"id":"fw-031","cat":"sextortion-plan","type":"branch","hook":"You're being blackmailed and your instinct is to delete everything.","options":[{"text":"Block them, but keep the messages, they're evidence","consequence":"You stay blocked and keep what stops them.","outcome":"evidence","best":true},{"text":"Delete the whole chat and your account","consequence":"Block, but don't delete; the messages are evidence."}],"debrief":"Block to stop contact, but save the evidence; deleting loses proof.","relearn":"Block the blackmailer but don't delete the messages, they're proof.","persona":"any","source":"sextortion response (verified)"},
  {"id":"fw-032","cat":"sextortion-plan","type":"branch","hook":"A sextortion threat says 'send one more and I'll leave you alone'.","options":[{"text":"Don't send more; it never ends it, get help instead","consequence":"You refuse the trap and reach for help.","outcome":"safe","best":true},{"text":"Send one more to make it stop","consequence":"Sending more never ends it; stop, save, tell and report."}],"debrief":"More images only fuel the blackmail; the way out is help, not compliance.","relearn":"Sending more never ends sextortion; stop and get help.","persona":"any","source":"sextortion response"},
  {"id":"fw-033","cat":"sextortion-plan","type":"branch","hook":"Afraid your family will be ashamed, you think about staying silent.","options":[{"text":"Tell a trusted adult anyway, you're the victim and they can help","consequence":"You're no longer alone, and it starts to end.","outcome":"tell","best":true},{"text":"Keep it secret and handle it alone","consequence":"Silence is what the blackmailer counts on; telling ends it."}],"debrief":"Shame and secrecy trap you; telling a trusted adult ends it.","relearn":"Don't stay silent; telling a trusted adult ends sextortion.","persona":"any","source":"sextortion / India shame factor"},
  {"id":"fw-034","cat":"sextortion-plan","type":"branch","hook":"You don't know who counts as a 'trusted adult' to tell.","options":[{"text":"A parent, teacher, counsellor, or call Childline 1098","consequence":"You find a real person to help carry it.","outcome":"help","best":true},{"text":"No one, just deal with it yourself","consequence":"A parent, teacher, counsellor or 1098 can help; you're not alone."}],"debrief":"There's always someone, a trusted adult or a helpline, who can help.","relearn":"A parent, teacher, counsellor or Childline 1098 can all help.","persona":"Counsellor","source":"finding help (verified)"},
  {"id":"fw-035","cat":"sextortion-plan","type":"branch","hook":"A friend confides they're being sextorted and begs you to keep it secret.","options":[{"text":"Support them and gently help them tell a trusted adult","consequence":"They get protection instead of carrying it alone.","outcome":"caring","best":true},{"text":"Keep the secret as asked","consequence":"This is too serious for secrecy; help them reach an adult."}],"debrief":"A friend in this danger needs an adult's help; help them tell.","relearn":"Help a sextorted friend tell a trusted adult.","persona":"any","source":"safeguarding"},
  {"id":"fw-036","cat":"sextortion-plan","type":"branch","hook":"After the threat, you feel it must somehow be your fault.","options":[{"text":"Remind yourself: the person threatening you committed the crime","consequence":"You drop the blame that isn't yours and get help.","outcome":"no-blame","best":true},{"text":"Blame yourself and hide","consequence":"It is not your fault; the blackmailer is the criminal."}],"debrief":"Being tricked or threatened is never your fault.","relearn":"Sextortion is never your fault; the blackmailer commits the crime.","persona":"any","source":"no blame"},
  {"id":"fw-037","cat":"sextortion-plan","type":"branch","hook":"You want to report it but worry you'll be 'in trouble' for being under 18.","options":[{"text":"Report anyway, the law treats you as a protected victim","consequence":"You get help safely; you're not in trouble.","outcome":"protected","best":true},{"text":"Don't report, in case you get blamed","consequence":"Under POCSO you're a protected victim, not in trouble."}],"debrief":"A minor in a sextortion case is a victim, never the wrongdoer.","relearn":"As a minor you're a protected victim; reporting is safe.","persona":"Counsellor","source":"POCSO (verified)"},
  {"id":"fw-038","cat":"sextortion-plan","type":"role-play","hook":"You need to tell a parent you're being sextorted, and you're scared.","setup":"Open with the truth. Say:","yourLine":[{"text":"\"I'm in trouble online and I need your help. I'm scared, but I trust you.\"","best":true},{"text":"Say nothing and keep paying"}],"relearn":"Telling a parent 'I need your help' is the bravest, safest first step.","persona":"any","source":"finding help voice"},
  {"id":"fw-039","cat":"sextortion-plan","type":"role-play","hook":"Reassure a friend who's being sextorted and blaming themselves.","setup":"Take the blame off them. Say:","yourLine":[{"text":"\"This is not your fault. They're the criminal. Let's get help together.\"","best":true},{"text":"\"Why did you send it though?\""}],"relearn":"Tell a victim: not your fault, they're the criminal, let's get help.","persona":"any","source":"no blame / support"},
  {"id":"fw-040","cat":"sextortion-plan","type":"role-play","hook":"Coach a friend through the first move under a threat.","setup":"Give the calm plan. Say:","yourLine":[{"text":"\"Don't pay and don't send more. Block them, keep the messages, and tell an adult.\"","best":true},{"text":"\"Just pay and hope it stops.\""}],"relearn":"The calm plan: don't pay, don't send more, block, save, tell.","persona":"Veer","source":"sextortion plan"},
  {"id":"fw-041","cat":"sextortion-plan","type":"role-play","hook":"You're helping a friend actually make the report.","setup":"Make it doable. Say:","yourLine":[{"text":"\"We can report at cybercrime.gov.in or call 1098, I'll sit with you while we do it.\"","best":true},{"text":"\"You should probably do something about it sometime.\""}],"relearn":"Offer to report together via cybercrime.gov.in or 1098, right now.","persona":"Counsellor","source":"reporting (verified)"},
  {"id":"fw-042","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"If you pay them once, they'll stop.\"","myth":{"un":"If you just pay the blackmailer once, they'll stop.","re":"Paying rarely stops it and often invites more; don't pay, get help.","why":"They have what they want; payment proves you'll comply."},"relearn":"Paying a sextortionist rarely stops it; don't pay, get help.","persona":"any","source":"sextortion (verified)"},
  {"id":"fw-043","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"If you got tricked into sending something, it's your fault.\"","myth":{"un":"If you were tricked into sending something, it's your fault.","re":"Being deceived or threatened is never your fault; the abuser is responsible.","why":"Manipulation is the criminal's doing, not yours."},"relearn":"Being tricked is never your fault; the blame is the abuser's.","persona":"any","source":"no blame"},
  {"id":"fw-044","cat":"sextortion-plan","type":"match","hook":"Match each step of the plan to why it works.","pairs":[{"left":"Don't pay","right":"Paying rarely stops it"},{"left":"Block but don't delete","right":"Messages are evidence"},{"left":"Tell a trusted adult","right":"You're no longer alone"},{"left":"Don't send more","right":"More images never end it"},{"left":"Report it","right":"It's how the crime gets stopped"}],"relearn":"Each step, don't pay, save evidence, tell, has a clear protective reason.","persona":"any","source":"sextortion plan"},
  {"id":"fw-045","cat":"sextortion-plan","type":"reflect","hook":"Lensy: if the worst happened, you'd now know the plan, and that it's never your fault. Reassuring?","prompt":"What do you think?","options":["Yes","I'd know what to do","Less scared"],"affirm":"Having a calm plan, and knowing you're not to blame, is real protection.","relearn":"Knowing the plan and that it's not your fault makes you safer.","persona":"any","source":"reassurance"},
  {"id":"fw-046","cat":"sextortion-plan","type":"reflect","hook":"Lensy: the most important thing to remember if you're ever targeted?","prompt":"Pick one.","options":["It's not my fault","Tell a trusted adult","Don't pay, get help"],"affirm":"All three are true at once, and any one of them is the start of the way out.","relearn":"Not your fault, tell someone, don't pay, the heart of the plan.","persona":"any","source":"consolidation"},
  // — Online myths busted —
  {"id":"fw-047","cat":"myths-busted","type":"strike-rewrite","hook":"\"They said they're my age, so it's safe.\"","myth":{"un":"They told me they're my age, so it's safe.","re":"People lie about their age online; 'they said so' isn't proof.","why":"Claiming to be a peer is a common grooming lie."},"relearn":"People lie about their age online; a claim isn't proof.","persona":"any","source":"grooming lie"},
  {"id":"fw-048","cat":"myths-busted","type":"strike-rewrite","hook":"\"Reporting does nothing, so why bother.\"","myth":{"un":"Reporting online abuse does nothing.","re":"Reporting genuinely helps; portals must act and it's how these crimes are stopped.","why":"India's portal forwards complaints to police within a day."},"relearn":"Reporting works and is how these crimes get stopped.","persona":"Counsellor","source":"reporting (verified)"},
  {"id":"fw-049","cat":"myths-busted","type":"strike-rewrite","hook":"\"Only careless people get groomed or extorted.\"","myth":{"un":"Only careless or 'stupid' people get groomed or extorted.","re":"Manipulators are skilled; this happens to careful people too, it's never a failing.","why":"Blaming the victim only helps the abuser."},"relearn":"Smart, careful people are targeted too; it's never a personal failing.","persona":"any","source":"no blame"},
  {"id":"fw-050","cat":"myths-busted","type":"strike-rewrite","hook":"\"Boys don't get sextorted.\"","myth":{"un":"Sextortion only happens to girls; boys are safe.","re":"Most financial-sextortion targets are teen boys; everyone should know the plan.","why":"Assuming you're safe is exactly what's exploited."},"relearn":"Boys are heavily targeted by sextortion; everyone needs the plan.","persona":"Veer","source":"sextortion data (verified)"},
  {"id":"fw-051","cat":"myths-busted","type":"strike-rewrite","hook":"\"Telling an adult will just make it worse.\"","myth":{"un":"Telling an adult will only make it worse.","re":"A trusted adult is your way out; you won't be in trouble, you'll be helped.","why":"Secrecy is the trap; support is the exit."},"relearn":"Telling a trusted adult helps; you'll be supported, not in trouble.","persona":"any","source":"finding help"},
  {"id":"fw-052","cat":"myths-busted","type":"sort","hook":"Sort: an online myth, or a safe truth?","items":[{"id":"a","text":"\"Everything sent stays private\""},{"id":"b","text":"\"Pressure to send is a red flag\""},{"id":"c","text":"\"Paying makes sextortion stop\""},{"id":"d","text":"\"Being tricked isn't your fault\""},{"id":"e","text":"\"A blue tick means they're safe\""},{"id":"f","text":"\"A trusted adult is your way out\""}],"bins":[{"id":"myth","label":"Myth","valence":"neg"},{"id":"truth","label":"Safe truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"Spot the myths (private, paying works, blue tick) from the truths (pressure is a flag, no blame).","persona":"any","source":"myths"},
  {"id":"fw-053","cat":"myths-busted","type":"sort","hook":"Sort: keeps you unsafe (myth), or keeps you safe (truth)?","items":[{"id":"a","text":"\"Groomers always seem creepy\""},{"id":"b","text":"\"Groomers often seem kind and normal\""},{"id":"c","text":"\"Deleting makes it gone\""},{"id":"d","text":"\"Copies can survive deletion\""},{"id":"e","text":"\"I'd always spot a fake\""},{"id":"f","text":"\"Skilled fakes fool careful people\""}],"bins":[{"id":"myth","label":"Unsafe myth","valence":"neg"},{"id":"truth","label":"Safe truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"Groomers can seem kind, deletion isn't a guarantee, and anyone can be fooled.","persona":"any","source":"myths"},
  {"id":"fw-054","cat":"myths-busted","type":"sort","hook":"Sort: a comforting lie a blackmailer wants you to believe, or the truth?","items":[{"id":"a","text":"\"No one can help you\""},{"id":"b","text":"\"Help exists and it works\""},{"id":"c","text":"\"It's your fault\""},{"id":"d","text":"\"You're the victim, not the criminal\""},{"id":"e","text":"\"Pay and I'll delete it\""},{"id":"f","text":"\"Don't pay; save the proof\""}],"bins":[{"id":"lie","label":"The abuser's lie","valence":"neg"},{"id":"truth","label":"The truth","valence":"pos"}],"key":{"a":"lie","b":"truth","c":"lie","d":"truth","e":"lie","f":"truth"},"relearn":"'No help / your fault / pay and I'll delete' are the abuser's lies; help exists and it's not your fault.","persona":"any","source":"no blame"},
  {"id":"fw-055","cat":"myths-busted","type":"sort","hook":"Sort: a red flag, or a green flag, in an online contact?","items":[{"id":"a","text":"Wants everything kept secret"},{"id":"b","text":"Happy for you to tell your parents"},{"id":"c","text":"Pushes you to send photos"},{"id":"d","text":"Respects your boundaries"},{"id":"e","text":"Rushes a 'special bond' fast"},{"id":"f","text":"Lets the friendship grow slowly"}],"bins":[{"id":"red","label":"Red flag","valence":"neg"},{"id":"green","label":"Green flag","valence":"pos"}],"key":{"a":"red","b":"green","c":"red","d":"green","e":"red","f":"green"},"relearn":"Secrecy, photo-pushing and rushed bonds are red; openness, respect and slow are green.","persona":"any","source":"red vs green"},
  {"id":"fw-056","cat":"myths-busted","type":"reflect","hook":"Lensy: which busted myth do you most want other teens to know?","prompt":"Pick one.","options":["Being tricked isn't your fault","Paying doesn't make it stop","Pressure to send is a red flag"],"affirm":"Passing on a truth like that could genuinely protect a friend.","relearn":"Sharing these truths helps protect the people around you.","persona":"any","source":"agency"},
  {"id":"fw-057","cat":"myths-busted","type":"reflect","hook":"Lensy: the self-blame myth is the one that keeps people silent. Ready to drop it?","prompt":"What do you think?","options":["Yes","It's never the victim's fault","Dropped"],"affirm":"Letting go of self-blame is what gives someone the courage to get help.","relearn":"Dropping self-blame is what frees a victim to reach for help.","persona":"any","source":"no blame"},
  {"id":"fw-058","cat":"myths-busted","type":"reflect","hook":"Lensy: knowing the myths now, do you feel harder to trick or trap?","prompt":"What do you think?","options":["Yes","Much harder","I see the tricks"],"affirm":"Knowing the playbook is exactly what makes you hard to trap.","relearn":"Knowing the myths and tactics makes you much harder to trick.","persona":"any","source":"empowerment"},
  // — Lock it down: privacy, block & report —
  {"id":"fw-059","cat":"lock-it-down","type":"spot","hook":"Spot the two privacy settings that leave you exposed.","scene":[{"id":"a","text":"Account set to private","trick":false},{"id":"b","text":"Live location shared with everyone","trick":true},{"id":"c","text":"Anyone on the app can DM you","trick":true},{"id":"d","text":"Only friends can see your posts","trick":false},{"id":"e","text":"Tag requests need your approval","trick":false}],"why":"Public live-location and open DMs are the exposed settings to fix; the rest already lock you down.","relearn":"Turn off public location and close open DMs; keep your account private.","persona":"any","source":"privacy settings"},
  {"id":"fw-060","cat":"lock-it-down","type":"spot","hook":"A contact turned creepy. Spot the two moves that keep you exposed.","scene":[{"id":"a","text":"Tap block on them","trick":false},{"id":"b","text":"Tap report on them","trick":false},{"id":"c","text":"Keep replying to 'sort it out'","trick":true},{"id":"d","text":"Screenshot their messages first","trick":false},{"id":"e","text":"Send your number so they 'calm down'","trick":true}],"why":"Arguing to 'sort it out' and handing over your number keep you exposed; block, report and screenshot are the moves.","relearn":"Block and report a creepy contact; don't keep engaging or hand over more.","persona":"any","source":"block & report"},
  {"id":"fw-061","cat":"lock-it-down","type":"spot","hook":"Spot the two account habits that weaken your security.","scene":[{"id":"a","text":"A strong, unique passcode","trick":false},{"id":"b","text":"Sharing your password with a 'bae'","trick":true},{"id":"c","text":"Two-factor login turned on","trick":false},{"id":"d","text":"Using 'name123' as your password","trick":true},{"id":"e","text":"A different password per app","trick":false}],"why":"Sharing your password and using a guessable one weaken you; strong, unique passwords and two-factor protect you.","relearn":"Strong, unique passwords and two-factor help; never share your password.","persona":"any","source":"account security"},
  {"id":"fw-062","cat":"lock-it-down","type":"spot","hook":"Spot the two posts that leak your footprint.","scene":[{"id":"a","text":"Reviewing what's public on your profile","trick":false},{"id":"b","text":"Posting your live location in real time","trick":true},{"id":"c","text":"Keeping old risky posts up forever","trick":true},{"id":"d","text":"Setting old albums to private","trick":false},{"id":"e","text":"Removing your school from your bio","trick":false}],"why":"Live-location and old risky posts are the leaks; reviewing and tidying your footprint closes them.","relearn":"Review your footprint; drop live-location and clean up risky old posts.","persona":"any","source":"footprint"},
  {"id":"fw-063","cat":"lock-it-down","type":"branch","hook":"You realise you've never set your accounts to private.","options":[{"text":"Set them private and review who can contact you","consequence":"Strangers can't freely reach or track you.","outcome":"locked","best":true},{"text":"Leave them open, it's easier","consequence":"Open accounts let strangers reach and track you; lock them down."}],"debrief":"A private account is the simplest, strongest first layer of safety.","relearn":"Set accounts private and control who can contact you.","persona":"any","source":"privacy"},
  {"id":"fw-064","cat":"lock-it-down","type":"branch","hook":"A stranger's account keeps messaging after you ignore it.","options":[{"text":"Block and report it","consequence":"They lose access and the platform is alerted.","outcome":"blocked","best":true},{"text":"Just keep ignoring it","consequence":"Ignoring leaves the door open; block and report instead."}],"debrief":"Blocking shuts the door; reporting helps protect others too.","relearn":"Block and report a persistent stranger, don't just ignore.","persona":"any","source":"block & report"},
  {"id":"fw-065","cat":"lock-it-down","type":"branch","hook":"You want to be ready before anything ever goes wrong.","options":[{"text":"Decide now who your trusted adults are","consequence":"If something happens, you already know who to turn to.","outcome":"ready","best":true},{"text":"Worry about it only if it happens","consequence":"Knowing your trusted adults in advance makes help faster when it counts."}],"debrief":"Naming your trusted adults before a crisis is real preparation.","relearn":"Decide who your trusted adults are before you ever need them.","persona":"any","source":"preparation"},
  {"id":"fw-066","cat":"lock-it-down","type":"branch","hook":"An app you use has disappearing messages and lots of strangers.","options":[{"text":"Be extra cautious; disappearing chats hide grooming","consequence":"You stay alert where risk is higher.","outcome":"cautious","best":true},{"text":"Assume it's safer because messages vanish","consequence":"Disappearing messages can hide grooming; be more careful, not less."}],"debrief":"'Vanishing' chats can lower your guard, exactly what some abusers want.","relearn":"Disappearing-message apps need more caution, not less.","persona":"any","source":"app risk"},
  {"id":"fw-067","cat":"lock-it-down","type":"sort","hook":"Sort: locks it down, or leaves you exposed?","items":[{"id":"a","text":"Private account"},{"id":"b","text":"Public location 24/7"},{"id":"c","text":"Two-factor login"},{"id":"d","text":"Open DMs from anyone"},{"id":"e","text":"School name in your public bio"},{"id":"f","text":"Approving who can tag you"}],"bins":[{"id":"lock","label":"Locks it down","valence":"pos"},{"id":"expose","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"lock","b":"expose","c":"lock","d":"expose","e":"expose","f":"lock"},"relearn":"Private accounts, two-factor and tag control lock down; public location, open DMs and a public school leak.","persona":"any","source":"privacy"},
  {"id":"fw-068","cat":"lock-it-down","type":"match","hook":"Match each safety tool to what it does.","pairs":[{"left":"Block","right":"Cuts off the contact"},{"left":"Report","right":"Alerts the platform"},{"left":"Private account","right":"Keeps strangers out"},{"left":"Two-factor login","right":"Stops account takeover"},{"left":"Screenshot first","right":"Saves the evidence"}],"relearn":"Block, report, private accounts, two-factor and screenshots are your everyday safety tools.","persona":"any","source":"tools"},
  {"id":"fw-069","cat":"lock-it-down","type":"match","hook":"Match the habit to the risk it shuts down.","pairs":[{"left":"Two-factor login","right":"Account takeover"},{"left":"Hiding your location","right":"Being tracked"},{"left":"Reviewing your footprint","right":"Old posts resurfacing"},{"left":"Closing open DMs","right":"Strangers messaging you"},{"left":"A unique password","right":"One leak unlocking all"}],"relearn":"Each good habit shuts down one specific risk.","persona":"any","source":"security"},
  {"id":"fw-070","cat":"lock-it-down","type":"match","hook":"Match each worry to the right India route.","pairs":[{"left":"Image abuse / sextortion","right":"cybercrime.gov.in / 1930"},{"left":"Anyone under 18 at risk","right":"Childline 1098"},{"left":"Right now, in person","right":"A trusted adult"},{"left":"A creepy stranger account","right":"In-app block & report"},{"left":"Proof you want to keep","right":"Saved screenshots"}],"relearn":"Match the worry to the route: 1930 for image abuse, 1098 under-18, a trusted adult, in-app tools.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"fw-071","cat":"lock-it-down","type":"role-play","hook":"A younger sibling is getting weird DMs. Coach them.","setup":"Keep it simple and calm. Say:","yourLine":[{"text":"\"Don't reply, screenshot it, block them, and come tell me or mum.\"","best":true},{"text":"\"Just ignore it and don't tell anyone.\""}],"relearn":"Teach: don't reply, screenshot, block, and tell a trusted adult.","persona":"any","source":"mentoring"},
  // — Find help, no blame —
  {"id":"fw-072","cat":"find-help-no-blame","type":"branch","hook":"Something online has gone wrong and you feel frozen with shame.","options":[{"text":"Tell one trusted adult, shame shrinks the moment you share it","consequence":"You're no longer alone, and help begins.","outcome":"told","best":true},{"text":"Keep it inside and hope it passes","consequence":"Shame grows in secret; telling one trusted person helps."}],"debrief":"Sharing with someone safe is the first step out of the fear.","relearn":"Telling one trusted adult shrinks the shame and starts the help.","persona":"any","source":"finding help / wellbeing"},
  {"id":"fw-073","cat":"find-help-no-blame","type":"branch","hook":"You're worried a friend is being groomed but they don't see it.","options":[{"text":"Gently name the red flags and tell a trusted adult together","consequence":"Your friend gets a chance to be safe.","outcome":"ally","best":true},{"text":"Stay out of it, it's their business","consequence":"Naming the flags and telling an adult could protect them."}],"debrief":"A caring friend who speaks up can interrupt grooming early.","relearn":"If a friend's being groomed, name the flags and bring in a trusted adult.","persona":"any","source":"allyship"},
  {"id":"fw-074","cat":"find-help-no-blame","type":"branch","hook":"You're unsure if what happened is 'serious enough' to tell anyone.","options":[{"text":"Tell a trusted adult anyway and let them help judge","consequence":"You're guided, not left guessing.","outcome":"safe","best":true},{"text":"Stay quiet unless it gets worse","consequence":"When unsure, tell a trusted adult; you don't have to judge it alone."}],"debrief":"You never have to decide alone whether something counts.","relearn":"If unsure it's 'serious enough', tell a trusted adult anyway.","persona":"any","source":"finding help"},
  {"id":"fw-075","cat":"find-help-no-blame","type":"branch","hook":"A friend who was tricked online keeps saying 'I'm so stupid'.","options":[{"text":"Tell them it's not their fault, and help them get support","consequence":"They feel less alone and more able to act.","outcome":"kind","best":true},{"text":"Agree they should've known better","consequence":"Blame keeps them stuck; remind them it's not their fault and help."}],"debrief":"Lifting the self-blame is what helps a friend move toward help.","relearn":"Tell a tricked friend it's not their fault, and help them get support.","persona":"any","source":"no blame / wellbeing"},
  {"id":"fw-076","cat":"find-help-no-blame","type":"role-play","hook":"You're checking in on a friend who's gone quiet after something online.","setup":"Open the door gently. Say:","yourLine":[{"text":"\"Hey, I'm here, no judgement. If something's wrong online, we can sort it together.\"","best":true},{"text":"\"You're being weird, what's your problem?\""}],"relearn":"A gentle, no-judgement check-in helps a struggling friend open up.","persona":"any","source":"support voice"},
  {"id":"fw-077","cat":"find-help-no-blame","type":"role-play","hook":"Encourage a friend who's scared to report.","setup":"Make it feel safe. Say:","yourLine":[{"text":"\"You won't be in trouble, you're the one being hurt. I'll help you report it.\"","best":true},{"text":"\"You'll probably get in trouble, so maybe don't.\""}],"relearn":"Reassure: you won't be in trouble, you're the victim, I'll help you report.","persona":"Counsellor","source":"no blame / reporting"},
  {"id":"fw-078","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: who are the trusted adults you could go to if something went wrong?","prompt":"Think of yours.","options":["A parent or guardian","A teacher or counsellor","An older relative","More than one"],"affirm":"Knowing your people in advance means you're never truly stuck.","relearn":"Knowing your trusted adults in advance means you always have somewhere to turn.","persona":"any","source":"preparation"},
  {"id":"fw-079","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: if a friend came to you scared about something online, what would you give them first?","prompt":"Pick one.","options":["Belief, no judgement","'It's not your fault'","Help to tell an adult"],"affirm":"Any of those could be exactly what they needed to hear.","relearn":"Belief, no blame, and help to tell an adult are what a scared friend needs.","persona":"any","source":"support"},
  {"id":"fw-080","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: the big takeaway from Firewall?","prompt":"Pick your motto.","options":["It's never my fault","Don't panic, there's a plan","Tell a trusted adult","Think before I share"],"affirm":"Hold onto that, it's exactly what keeps you safe and unstuck.","relearn":"Not your fault, there's a plan, tell someone, think first, the core of staying safe.","persona":"any","source":"consolidation"},
  {"id":"fw-081","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: knowing the red flags, the plan and the helplines, do you feel safer online?","prompt":"What do you think?","options":["Yes","More in control","Ready, not scared"],"affirm":"That's the goal, alert and in control, not frightened.","relearn":"Knowing the flags, the plan and the helplines puts you in control.","persona":"any","source":"empowerment"},
  {"id":"fw-082","cat":"find-help-no-blame","type":"match","hook":"Match the worry to where help is (India).","pairs":[{"left":"Being blackmailed with images","right":"cybercrime.gov.in / 1930"},{"left":"A child being groomed","right":"Childline 1098"},{"left":"Need someone now","right":"A trusted adult"},{"left":"Report without your name","right":"Anonymous online option"},{"left":"Scared at night, no one home","right":"24x7 helpline"}],"relearn":"India: cybercrime.gov.in / 1930, Childline 1098, a trusted adult, help is there.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"fw-083","cat":"find-help-no-blame","type":"match","hook":"Match the feeling to the truth that answers it.","pairs":[{"left":"\"It's my fault\"","right":"The abuser is to blame"},{"left":"\"I'm all alone\"","right":"A trusted adult can help"},{"left":"\"Nothing can be done\"","right":"It can be reported and stopped"},{"left":"\"I'll get in trouble\"","right":"You're protected, not punished"},{"left":"\"It's too embarrassing\"","right":"Telling makes it smaller"}],"relearn":"Each fear has a true answer: not your fault, not alone, it can be stopped.","persona":"any","source":"no blame"},
  {"id":"fw-084","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"If something goes wrong online, my life is over.\"","myth":{"un":"If something goes wrong online, my life is over.","re":"It feels huge, but there's a clear way through, and people whose job is to help.","why":"These situations are survivable and fixable with the right help."},"relearn":"It feels huge, but there's always a way through with the right help.","persona":"any","source":"hope / wellbeing"},
  {"id":"fw-900","cat":"find-help-no-blame","type":"branch","hook":"A stranger online got a photo you regret. Your hands are shaking.","options":[{"text":"Breathe, then tell one trusted adult tonight","consequence":"You're not alone with it, and the plan starts.","outcome":"told","best":true},{"text":"Sit with it alone, hope it passes","consequence":"Alone, fear grows; telling one adult shrinks it."}],"debrief":"The calm first step is telling one person on your side.","relearn":"When something's wrong, tell one trusted adult, you don't carry it alone.","persona":"Veer","source":"finding help / wellbeing"},
  {"id":"fw-901","cat":"find-help-no-blame","type":"branch","hook":"You want to tell your mother but fear she'll be angry at you.","options":[{"text":"Tell her anyway, you're hurt, not in trouble","consequence":"She helps; her worry is for you, not against you.","outcome":"told","best":true},{"text":"Decide she'll just blame you, say nothing","consequence":"Silence traps you; telling is how it ends."}],"debrief":"A parent's first shock passes; protecting you comes first.","relearn":"You won't be in trouble for being hurt, a trusted adult is your way out.","persona":"Riya","source":"no blame / family"},
  {"id":"fw-902","cat":"find-help-no-blame","type":"branch","hook":"You know where to report image abuse but feel too ashamed to do it.","options":[{"text":"Report it on cybercrime.gov.in, anonymously","consequence":"It's filed; shame doesn't have to be public.","outcome":"reported","best":true},{"text":"Leave it, the embarrassment isn't worth it","consequence":"The anonymous option means shame never blocks help."}],"debrief":"Reporting stops these crimes, and it can stay private.","relearn":"Image abuse can be reported anonymously at cybercrime.gov.in / 1930.","persona":"any","source":"reporting routes (verified)"},
  {"id":"fw-903","cat":"find-help-no-blame","type":"branch","hook":"Your young cousin is messaged by a creepy 'friend' and is scared to tell anyone.","options":[{"text":"Sit with them and call Childline 1098 together","consequence":"A trained helper takes over; the child isn't alone.","outcome":"helped","best":true},{"text":"Tell them to just block it and forget it","consequence":"Under-18s have 1098; don't leave a kid to manage it."}],"debrief":"For an under-18 at risk, 1098 is built for exactly this.","relearn":"For an under-18 at risk, Childline 1098 is there, you can call together.","persona":"any","source":"helplines (verified)"},
  {"id":"fw-904","cat":"find-help-no-blame","type":"branch","hook":"A counsellor offered help, but you fear telling makes it 'real' and worse.","options":[{"text":"Talk to the counsellor, naming it starts it healing","consequence":"You feel lighter and get a clear next step.","outcome":"supported","best":true},{"text":"Keep pretending it didn't happen","consequence":"Silence is the danger; a counsellor helps it shrink."}],"debrief":"Saying it to one safe person shrinks the fear, not grows it.","relearn":"Telling one trusted adult shrinks the shame and starts the help.","persona":"Counsellor","source":"no blame / wellbeing"},
  {"id":"fw-905","cat":"find-help-no-blame","type":"branch","hook":"A friend confides he's being sextorted and begs you to keep it secret.","options":[{"text":"Stay by him, but say a trusted adult must know","consequence":"He's not alone and the threat gets handled.","outcome":"ally","best":true},{"text":"Swear to tell no one, fix it just the two of you","consequence":"Two scared kids can't stop a crime; an adult can."}],"debrief":"Real loyalty is helping a friend get safe, not a dangerous secret.","relearn":"A sextorted friend needs a trusted adult too, secrecy keeps them trapped.","persona":"Veer","source":"allyship"},
  {"id":"fw-906","cat":"find-help-no-blame","type":"branch","hook":"You told one teacher and nothing happened. You feel like giving up.","options":[{"text":"Tell a second trusted adult, one 'no' isn't the end","consequence":"The next person listens and help finally moves.","outcome":"persisted","best":true},{"text":"Decide no adult will ever help, stop trying","consequence":"If one adult won't act, another will; keep going."}],"debrief":"If the first person can't help, there's always another, and 1098.","relearn":"If one adult doesn't help, tell another, there's always someone who will.","persona":"any","source":"finding help"},
  {"id":"fw-907","cat":"find-help-no-blame","type":"branch","hook":"You shared your password; now your account posts things you didn't.","options":[{"text":"Tell an adult, report it, then change passwords","consequence":"It's contained fast and you're not blamed.","outcome":"recovered","best":true},{"text":"Quietly try to fix it alone first","consequence":"Being tricked isn't your fault; an adult fixes it faster."}],"debrief":"Getting tricked is never the failure; hiding just slows the fix.","relearn":"Being tricked isn't your fault, tell an adult and report to get it fixed.","persona":"any","source":"no blame / accounts"},
  {"id":"fw-908","cat":"find-help-no-blame","type":"branch","hook":"You're unsure if a weird late-night chat 'counts' as worth reporting.","options":[{"text":"Save the chat, ask a trusted adult to help decide","consequence":"You don't judge it alone, and nothing's lost.","outcome":"safe","best":true},{"text":"Wait until you're fully certain it's serious","consequence":"When unsure, ask an adult; don't judge it alone."}],"debrief":"You don't need to be sure it's serious to ask for help.","relearn":"If unsure it's 'serious enough', save it and ask a trusted adult anyway.","persona":"any","source":"finding help"},
  {"id":"fw-909","cat":"find-help-no-blame","type":"branch","hook":"A friend was catfished and won't talk to anyone, too embarrassed.","options":[{"text":"Say it happens to careful people, help her tell an adult","consequence":"The shame lifts enough for her to accept help.","outcome":"kind","best":true},{"text":"Joke that she fell for an obvious fake","consequence":"Careful people get fooled too; lift the blame to help."}],"debrief":"Lifting the self-blame lets a friend reach for help.","relearn":"Tell a catfished friend it's not their fault, then help them tell an adult.","persona":"any","source":"no blame / allyship"},
  {"id":"fw-910","cat":"find-help-no-blame","type":"branch","hook":"Someone is threatening you and you want to delete it all and forget it.","options":[{"text":"Don't delete it, save it as evidence, bring an adult in","consequence":"The proof helps stop it; you're guided through it.","outcome":"evidence","best":true},{"text":"Delete the messages so no one sees them","consequence":"Deleting wipes the proof; save it, tell an adult."}],"debrief":"The messages are evidence; an adult helps you use them.","relearn":"Don't delete threats, they're evidence, save them and tell a trusted adult.","persona":"any","source":"finding help / evidence"},
  {"id":"fw-911","cat":"find-help-no-blame","type":"branch","hook":"In a strict joint family, no adult at home feels safe to tell.","options":[{"text":"Tell a teacher or counsellor, or call 1098","consequence":"You reach a safe adult even if home feels closed.","outcome":"routed","best":true},{"text":"Decide if home's unsafe, there's no one","consequence":"A teacher, counsellor or 1098 is a route too."}],"debrief":"A trusted adult can be outside home, and 1098 is always open.","relearn":"If home feels unsafe to tell, a teacher, counsellor or Childline 1098 is there.","persona":"Riya","source":"finding help / routes"},
  {"id":"fw-912","cat":"find-help-no-blame","type":"branch","hook":"A friend says 'reporting does nothing, so why tell anyone?'","options":[{"text":"Say reporting is how these crimes get traced and stopped","consequence":"He reports instead of staying silent and stuck.","outcome":"convinced","best":true},{"text":"Agree it's pointless and drop it","consequence":"Reporting helps; silence lets it keep happening."}],"debrief":"Reporting to cybercrime.gov.in / 1930 is how it gets stopped.","relearn":"Reporting genuinely helps, it's how these crimes get traced and stopped.","persona":"Veer","source":"reporting (verified)"},
  {"id":"fw-913","cat":"find-help-no-blame","type":"branch","hook":"You want to help a scared friend but fear saying the wrong thing.","options":[{"text":"Say 'I believe you, not your fault, I'll help you tell someone'","consequence":"That's enough; your friend feels safe to act.","outcome":"ally","best":true},{"text":"Wait for the perfect words first","consequence":"You don't need perfect words; belief is enough."}],"debrief":"Belief, no blame, and help to tell an adult is all a friend needs.","relearn":"You don't need perfect words, belief and 'not your fault' help most.","persona":"any","source":"support"},
  {"id":"fw-914","cat":"find-help-no-blame","type":"branch","hook":"You finally told an adult and they believed you. Now what?","options":[{"text":"Let them help you save evidence and report to 1930","consequence":"The plan moves forward; you feel in control.","outcome":"plan","best":true},{"text":"Feel relieved you told, leave the rest","consequence":"Telling is step one; next, save evidence and report."}],"debrief":"Telling starts the plan; the adult helps you save evidence and report.","relearn":"After you tell an adult, save evidence and report to cybercrime.gov.in / 1930.","persona":"Counsellor","source":"finding help / routes"},
  {"id":"fw-915","cat":"find-help-no-blame","type":"branch","hook":"It's late, you're alone, and you need help right now, not tomorrow.","options":[{"text":"Call Childline 1098, 24x7 for under-18s, and wake an adult","consequence":"You reach a trained helper now and aren't alone.","outcome":"now","best":true},{"text":"Lie awake panicking until morning","consequence":"1098 is open all night; you needn't wait alone."}],"debrief":"Childline 1098 is there 24x7; you never wait out the night alone.","relearn":"Need help right now? Childline 1098 is 24x7, and wake a trusted adult.","persona":"any","source":"helplines (verified)"},
  {"id":"fw-916","cat":"find-help-no-blame","type":"branch","hook":"A friend keeps paying a blackmailer and won't tell anyone. Only you know.","options":[{"text":"Tell her to stop paying and go to a trusted adult together","consequence":"The paying stops; a plan replaces the panic.","outcome":"ally","best":true},{"text":"Keep her secret, hope she handles it","consequence":"Paying invites more; she needs a trusted adult."}],"debrief":"A friend trapped by a blackmailer needs you to bring in an adult.","relearn":"Help a blackmailed friend stop paying and go to a trusted adult together.","persona":"any","source":"allyship"},
  {"id":"fw-917","cat":"find-help-no-blame","type":"role-play","hook":"Your friend just whispered that something happened online and braced for you to judge.","setup":"Take the blame off them first. Say:","yourLine":[{"text":"\"This isn't your fault at all. I'm glad you told me, let's get you help.\"","best":true},{"text":"\"How did you even let that happen?\""}],"relearn":"Lead with 'it's not your fault', that's what lets a friend reach for help.","persona":"any","source":"support voice"},
  {"id":"fw-918","cat":"find-help-no-blame","type":"role-play","hook":"A scared friend says no adult will ever understand.","setup":"Offer to go with them. Say:","yourLine":[{"text":"\"I'll come with you to tell someone, you won't have to say it alone.\"","best":true},{"text":"\"Well, good luck figuring it out by yourself.\""}],"relearn":"Offering to go with a friend makes telling a trusted adult feel possible.","persona":"any","source":"support voice"},
  {"id":"fw-919","cat":"find-help-no-blame","type":"role-play","hook":"You need to ask your father for help and you're terrified of how he'll react.","setup":"Say it plainly and ask for help, not permission. Say:","yourLine":[{"text":"\"Papa, something online went wrong and I need your help. I'm scared but I trust you.\"","best":true},{"text":"\"It's nothing, forget I said anything.\""}],"relearn":"Asking a parent for help directly is brave and it's how you get unstuck.","persona":"Riya","source":"finding help / family"},
  {"id":"fw-920","cat":"find-help-no-blame","type":"role-play","hook":"A friend is convinced he'll be arrested if he reports being sextorted.","setup":"Reassure him about the law calmly. Say:","yourLine":[{"text":"\"You're the victim here, not in trouble. Reporting protects you, it doesn't get you arrested.\"","best":true},{"text":"\"Yeah, maybe stay quiet just in case.\""}],"relearn":"A sextorted teen is a protected victim, reporting helps them, not gets them in trouble.","persona":"Veer","source":"no blame / reporting"},
  {"id":"fw-921","cat":"find-help-no-blame","type":"role-play","hook":"You're calling Childline for the first time and your voice is shaking.","setup":"Start simply, you don't need a script. Say:","yourLine":[{"text":"\"Hi, something online is scaring me and I don't know what to do. Can you help?\"","best":true},{"text":"\"Sorry, never mind, this was a mistake.\""}],"relearn":"You don't need perfect words to call for help, just say you're scared and ask.","persona":"any","source":"helpline voice"},
  {"id":"fw-922","cat":"find-help-no-blame","type":"role-play","hook":"Your friend blames herself out loud: 'I should never have trusted him.'","setup":"Move the blame to where it belongs. Say:","yourLine":[{"text":"\"He chose to lie to you. The fault is his, not yours, and we can get help.\"","best":true},{"text":"\"Yeah, you really shouldn't have.\""}],"relearn":"The person who lied is at fault, not the friend who was deceived.","persona":"any","source":"no blame / allyship"},
  {"id":"fw-923","cat":"find-help-no-blame","type":"role-play","hook":"A classmate is about to send money to make a threat 'go away'.","setup":"Stop the payment and offer the real next step. Say:","yourLine":[{"text":"\"Don't pay, it won't stop them. Let's save the messages and tell an adult right now.\"","best":true},{"text":"\"Maybe just pay it so it ends faster.\""}],"relearn":"Don't pay a threat, save the messages and tell a trusted adult instead.","persona":"any","source":"no blame / plan"},
  {"id":"fw-924","cat":"find-help-no-blame","type":"role-play","hook":"You want to thank the friend who helped you get help, so others know it's okay to.","setup":"Name what helped. Say:","yourLine":[{"text":"\"You believed me and didn't blame me. That's what made me brave enough to tell.\"","best":true},{"text":"\"Let's never talk about this again.\""}],"relearn":"Belief and no blame are what make someone brave enough to ask for help.","persona":"any","source":"support voice"},
  {"id":"fw-925","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: if something online scared you tonight, who's the first person you'd go to?","prompt":"Picture them.","options":["A parent or guardian","An older sibling or cousin","A teacher or counsellor","Childline 1098"],"affirm":"Knowing your first call in advance means you're never truly stuck.","relearn":"Knowing your first trusted person in advance means you always have somewhere to turn.","persona":"any","source":"preparation"},
  {"id":"fw-926","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what would you want a friend to say to you if you were the scared one?","prompt":"Pick what you'd need.","options":["'I believe you'","'It's not your fault'","'I'll help you tell someone'"],"affirm":"Whatever you'd want to hear, that's exactly what you can offer others.","relearn":"Belief, no blame, and help to tell an adult are what a scared friend needs.","persona":"any","source":"support"},
  {"id":"fw-927","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: which truth do you most want to remember when shame says 'it's your fault'?","prompt":"Choose your anchor.","options":["The abuser is to blame, not me","I'm protected, not in trouble","Telling makes it smaller","There's always someone to call"],"affirm":"Hold onto that one, it's the truth that gets you unstuck.","relearn":"It's never your fault, you're protected, and telling someone makes it smaller.","persona":"any","source":"no blame"},
  {"id":"fw-928","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: after going through Firewall, how do you feel about handling something gone wrong online?","prompt":"How do you feel?","options":["Ready, not scared","More in control","Like I know who to call"],"affirm":"That's the whole goal, alert and in control, never frightened.","relearn":"The goal is to feel ready and in control, not frightened.","persona":"any","source":"empowerment"},
  {"id":"fw-929","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: a friend opens up to you, scared. What's the very first thing you give them?","prompt":"Lead with one.","options":["A calm 'I'm here'","'This isn't your fault'","No judgement, just listening"],"affirm":"Any of those tells them they're safe with you, which is everything.","relearn":"A calm, no-judgement 'I'm here, it's not your fault' helps a friend open up.","persona":"any","source":"support"},
  {"id":"fw-930","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what makes it easier for you to ask an adult for help?","prompt":"Pick what helps you.","options":["Knowing I won't be blamed","Bringing a friend along","Writing down what happened first","Knowing exactly who to ask"],"affirm":"Whatever lowers the barrier for you, that's a real plan, keep it close.","relearn":"Knowing you won't be blamed makes asking a trusted adult far easier.","persona":"any","source":"preparation"},
  {"id":"fw-931","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: who in your life is good at staying calm in a crisis?","prompt":"Bring them to mind.","options":["A parent or guardian","A teacher or coach","An older cousin or sibling","A school counsellor"],"affirm":"That calm person is a brilliant first call, you're not as alone as fear says.","relearn":"A calm adult you trust is a perfect first call when something goes wrong.","persona":"any","source":"preparation"},
  {"id":"fw-932","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: if a friend swore you to secrecy about a real danger, what would you do?","prompt":"Sit with it.","options":["Stay close, but bring in a trusted adult","Tell them I can't keep this one secret alone","Help them tell someone themselves"],"affirm":"Each of those keeps your friend safe, real care, not a dangerous secret.","relearn":"Real care means bringing in a trusted adult, not keeping a dangerous secret.","persona":"any","source":"allyship"},
  {"id":"fw-933","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what's one thing you'd tell your past self before something went wrong online?","prompt":"Pick your message.","options":["'It won't be your fault'","'There's always a plan'","'Someone will help you'","'Don't face it alone'"],"affirm":"Carry that forward, it's exactly what keeps you safe and unstuck.","relearn":"Whatever happens, it's not your fault, there's a plan, and someone will help.","persona":"any","source":"consolidation"},
  {"id":"fw-934","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: when you imagine telling a trusted adult, what fear comes up first?","prompt":"Name it gently.","options":["They'll be angry","They'll be disappointed","They'll take my phone","They won't understand"],"affirm":"That fear is normal, and naming it is the first step past it; telling still helps.","relearn":"Fears about telling are normal, naming them is the first step to getting help.","persona":"any","source":"wellbeing"},
  {"id":"fw-935","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: which India route would you reach for first if you needed help online?","prompt":"Pick your go-to.","options":["A trusted adult","Childline 1098","cybercrime.gov.in / 1930"],"affirm":"Knowing your route in advance means help is never far when you need it.","relearn":"India routes: a trusted adult, Childline 1098, cybercrime.gov.in / 1930.","persona":"any","source":"helplines (verified)"},
  {"id":"fw-936","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: a friend asks why you'd even bother reporting. What do you believe?","prompt":"Pick your reason.","options":["Reporting helps stop it","I won't be in trouble","It protects others too","Staying silent helps no one"],"affirm":"Any of those is true, reporting is how these crimes actually get stopped.","relearn":"Reporting helps stop the crime and protects others, silence helps no one.","persona":"any","source":"reporting"},
  {"id":"fw-937","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what does 'no blame' mean to you when a friend is hurting?","prompt":"Choose your version.","options":["The abuser is responsible, not them","Being tricked isn't a failing","Smart people get fooled too","Anyone could be targeted"],"affirm":"Each of those takes the weight off a friend, that's what helps them heal and act.","relearn":"No blame means the abuser is responsible, being tricked is never a failing.","persona":"any","source":"no blame"},
  {"id":"fw-938","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: if you'd already told one adult and felt unheard, what would you try next?","prompt":"Pick your next move.","options":["Tell a different trusted adult","Call Childline 1098","Bring a friend to back me up"],"affirm":"There's always a next door, one 'no' is never the end of help.","relearn":"If one adult doesn't help, try another or Childline 1098, there's always a next door.","persona":"any","source":"finding help"},
  {"id":"fw-939","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what's the kindest thing a friend could do for you if you were too ashamed to speak?","prompt":"Pick what you'd want.","options":["Just sit with me","Not ask for details","Say it's not my fault","Help me find the words"],"affirm":"Whatever you'd want, that gentleness is exactly what you can give others too.","relearn":"Sitting with someone, no prying, and 'it's not your fault' helps shame ease.","persona":"any","source":"support"},
  {"id":"fw-940","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: what helps you believe 'I won't be in trouble' even when shame argues back?","prompt":"Pick your proof.","options":["I'm the one being protected","I didn't choose to be targeted","The law is on my side","Adults want to help, not punish"],"affirm":"Hold that proof close, it's true even when fear tries to drown it out.","relearn":"You're the one being protected, not punished, you won't be in trouble.","persona":"any","source":"no blame"},
  {"id":"fw-941","cat":"find-help-no-blame","type":"reflect","hook":"Lensy: picturing yourself a year from now, having gotten help, how do you want to feel?","prompt":"Imagine it.","options":["Free of the secret","Proud I spoke up","Safe again","Stronger than before"],"affirm":"That future is real and reachable, asking for help is the door to it.","relearn":"Getting help is the door to feeling free, safe and stronger again.","persona":"any","source":"hope / wellbeing"},
  {"id":"fw-942","cat":"find-help-no-blame","type":"match","hook":"Match each worry to where help is (India).","pairs":[{"left":"Blackmailed with a private image","right":"cybercrime.gov.in / 1930"},{"left":"A child under 18 at risk online","right":"Childline 1098"},{"left":"Need someone in person, right now","right":"A trusted adult"},{"left":"Want to report without your name","right":"Anonymous option online"},{"left":"Scared and alone late at night","right":"24x7 helpline call"}],"relearn":"India: cybercrime.gov.in / 1930, Childline 1098, a trusted adult, help is there.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"fw-943","cat":"find-help-no-blame","type":"match","hook":"Match each shame-thought to the truth that answers it.","pairs":[{"left":"\"It's all my fault\"","right":"The abuser is the one to blame"},{"left":"\"I'm completely alone\"","right":"A trusted adult can help"},{"left":"\"Nothing can be done now\"","right":"It can be reported and stopped"},{"left":"\"I'll be in trouble if I tell\"","right":"You're protected, not punished"},{"left":"\"My life is over\"","right":"There's a clear way through this"}],"relearn":"Each fear has a true answer: not your fault, not alone, it can be stopped.","persona":"any","source":"no blame"},
  {"id":"fw-944","cat":"find-help-no-blame","type":"match","hook":"Match what a scared friend says to the kindest reply.","pairs":[{"left":"\"I'm so stupid for trusting him\"","right":"\"He lied; it's not your fault\""},{"left":"\"No adult will understand\"","right":"\"I'll come with you to tell one\""},{"left":"\"What if I get in trouble?\"","right":"\"You're the one being protected\""},{"left":"\"I can't talk about it\"","right":"\"I'm here, no judgement\""},{"left":"\"It's too late now\"","right":"\"It can still be reported\""}],"relearn":"Belief, no blame, company and 'it can be stopped' are what a friend needs.","persona":"any","source":"support"},
  {"id":"fw-945","cat":"find-help-no-blame","type":"match","hook":"Match the situation to the calm first move.","pairs":[{"left":"A threat just landed in your DMs","right":"Save it as evidence, don't reply"},{"left":"You feel frozen with shame","right":"Tell one trusted adult tonight"},{"left":"Unsure if it's 'serious enough'","right":"Ask a trusted adult to help decide"},{"left":"A friend is being groomed","right":"Name the flags, bring in an adult"},{"left":"You need help this minute","right":"Call Childline 1098"}],"relearn":"Every hard moment has a calm first move, and you never make it alone.","persona":"any","source":"finding help / plan"},
  {"id":"fw-946","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"If I tell my parents, they'll just take my phone and blame me.\"","myth":{"un":"If I tell my parents, they'll just take my phone and blame me.","re":"Most parents' first instinct is to protect you, not punish you for being hurt.","why":"You're the one being harmed, so a caring adult focuses on your safety, not blame."},"relearn":"Telling a parent is more likely to bring protection than punishment.","persona":"Riya","source":"no blame / family"},
  {"id":"fw-947","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"It wasn't that bad, so there's no point telling anyone.\"","myth":{"un":"It wasn't that bad, so there's no point telling anyone.","re":"You don't have to judge how 'bad' it was, a trusted adult can help you decide.","why":"Telling early, even when unsure, is how small problems are kept small."},"relearn":"If unsure it's 'serious enough', tell a trusted adult anyway.","persona":"any","source":"finding help"},
  {"id":"fw-948","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"Asking for help means I couldn't handle it myself.\"","myth":{"un":"Asking for help means I couldn't handle it myself.","re":"Asking for help is the strong, smart move, not a weakness.","why":"These situations are designed to trap you, getting help is how anyone escapes them."},"relearn":"Asking for help is a strength, not a sign you failed.","persona":"Veer","source":"no blame / wellbeing"},
  {"id":"fw-949","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"Only careless people end up needing help like this.\"","myth":{"un":"Only careless people end up needing help like this.","re":"Smart, careful teens are targeted too, manipulators are skilled at it.","why":"Being deceived by a skilled manipulator says nothing about how careful you are."},"relearn":"Careful people get targeted too, needing help is never a personal failing.","persona":"any","source":"no blame"},
  {"id":"fw-950","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"If I report it, I'll be the one who gets in trouble.\"","myth":{"un":"If I report it, I'll be the one who gets in trouble.","re":"When you report being harmed online, you're treated as the victim, not the one at fault.","why":"The person threatening or deceiving you is the one breaking the law, not you."},"relearn":"Reporting being harmed makes you the protected victim, not the one in trouble.","persona":"any","source":"reporting / no blame"},
  {"id":"fw-951","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"I should just deal with this on my own and not bother anyone.\"","myth":{"un":"I should just deal with this on my own and not bother anyone.","re":"You're not a bother, helping you is exactly what trusted adults and Childline 1098 are for.","why":"Carrying it alone makes it heavier, sharing it is what starts it getting better."},"relearn":"You're never a bother, trusted adults and Childline 1098 exist to help you.","persona":"any","source":"finding help"},
  {"id":"fw-952","cat":"find-help-no-blame","type":"strike-rewrite","hook":"\"There's nothing anyone can do once it's online.\"","myth":{"un":"There's nothing anyone can do once it's online.","re":"Reports can trace and take down content and reach the person behind it.","why":"Trained people handle these cases all the time, doing nothing is the only choice that never helps."},"relearn":"Help can be done even once it's online, reporting can trace and take it down.","persona":"any","source":"reporting"},
  {"id":"fw-953","cat":"find-help-no-blame","type":"sort","hook":"Sort each move into gets you unstuck or keeps you stuck.","items":[{"id":"a","text":"Tell one trusted adult tonight"},{"id":"b","text":"Sit alone in silence and shame"},{"id":"c","text":"Save the messages as evidence"},{"id":"d","text":"Delete it all and pretend it's fine"},{"id":"e","text":"Call Childline 1098 when scared"},{"id":"f","text":"Blame yourself for being tricked"}],"bins":[{"id":"helps","label":"Gets you unstuck","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"helps","b":"stuck","c":"helps","d":"stuck","e":"helps","f":"stuck"},"relearn":"Telling, saving evidence and calling help get you unstuck; silence and self-blame don't.","persona":"any","source":"finding help / plan"},
  {"id":"fw-954","cat":"find-help-no-blame","type":"sort","hook":"Sort each line into kind to a scared friend or blames the friend.","items":[{"id":"a","text":"\"It's not your fault\""},{"id":"b","text":"\"How could you be so dumb?\""},{"id":"c","text":"\"I believe you\""},{"id":"d","text":"\"You should've known better\""},{"id":"e","text":"\"I'll help you tell someone\""},{"id":"f","text":"\"You kind of brought this on yourself\""}],"bins":[{"id":"kind","label":"Kind, no blame","valence":"pos"},{"id":"blame","label":"Blames them","valence":"neg"}],"key":{"a":"kind","b":"blame","c":"kind","d":"blame","e":"kind","f":"blame"},"relearn":"Belief and 'not your fault' help a friend, blame just keeps them stuck.","persona":"any","source":"support / no blame"},
  {"id":"fw-955","cat":"find-help-no-blame","type":"sort","hook":"Sort each helper into a real India route or not a real route.","items":[{"id":"a","text":"Childline 1098"},{"id":"b","text":"A random stranger in another chat"},{"id":"c","text":"cybercrime.gov.in / 1930"},{"id":"d","text":"Paying the person threatening you"},{"id":"e","text":"A trusted teacher or counsellor"},{"id":"f","text":"The blackmailer's 'helpful friend'"}],"bins":[{"id":"real","label":"Real route to help","valence":"pos"},{"id":"notreal","label":"Not a safe route","valence":"neg"}],"key":{"a":"real","b":"notreal","c":"real","d":"notreal","e":"real","f":"notreal"},"relearn":"Real routes: Childline 1098, cybercrime.gov.in / 1930, a trusted adult, not strangers or paying.","persona":"any","source":"helplines (verified)"},
  {"id":"fw-956","cat":"find-help-no-blame","type":"sort","hook":"Sort each thought into true and helps or shame talking.","items":[{"id":"a","text":"I'm protected, not in trouble"},{"id":"b","text":"My life is over"},{"id":"c","text":"There's always someone to call"},{"id":"d","text":"No one will ever believe me"},{"id":"e","text":"Telling makes it smaller"},{"id":"f","text":"It's all my fault"}],"bins":[{"id":"true","label":"True and helps","valence":"pos"},{"id":"shame","label":"Shame talking","valence":"neg"}],"key":{"a":"true","b":"shame","c":"true","d":"shame","e":"true","f":"shame"},"relearn":"You're protected, there's always someone, and telling makes it smaller, shame lies.","persona":"any","source":"no blame"},
  {"id":"fw-957","cat":"find-help-no-blame","type":"sort","hook":"Sort each step of the no-blame plan into do this or never this.","items":[{"id":"a","text":"Save the messages as evidence"},{"id":"b","text":"Pay to make it stop"},{"id":"c","text":"Tell a trusted adult"},{"id":"d","text":"Send another photo"},{"id":"e","text":"Report at cybercrime.gov.in / 1930"},{"id":"f","text":"Delete the proof and stay silent"}],"bins":[{"id":"do","label":"Do this","valence":"pos"},{"id":"never","label":"Never this","valence":"neg"}],"key":{"a":"do","b":"never","c":"do","d":"never","e":"do","f":"never"},"relearn":"Save evidence, tell an adult, report, never pay, send more, delete proof or stay silent.","persona":"any","source":"plan / routes"},
  {"id":"fw-958","cat":"find-help-no-blame","type":"sort","hook":"Sort each way to support a friend into opens them up or shuts them down.","items":[{"id":"a","text":"Listen without prying for details"},{"id":"b","text":"Spread it to other friends"},{"id":"c","text":"Say 'I'm here when you're ready'"},{"id":"d","text":"Make them feel judged"},{"id":"e","text":"Offer to go with them to an adult"},{"id":"f","text":"Tell them they're overreacting"}],"bins":[{"id":"open","label":"Helps them open up","valence":"pos"},{"id":"shut","label":"Shuts them down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Listening, patience and going along help a friend open up; judging shuts them down.","persona":"any","source":"support"},
  {"id":"fw-959","cat":"find-help-no-blame","type":"sort","hook":"Sort each who-to-tell into a trusted adult or not who this is for.","items":[{"id":"a","text":"A parent or guardian"},{"id":"b","text":"The stranger who threatened you"},{"id":"c","text":"A teacher or school counsellor"},{"id":"d","text":"A fake 'helper' DMing you"},{"id":"e","text":"An older relative you trust"},{"id":"f","text":"A gossip who shares everything"}],"bins":[{"id":"trusted","label":"A trusted adult","valence":"pos"},{"id":"not","label":"Not who this is for","valence":"neg"}],"key":{"a":"trusted","b":"not","c":"trusted","d":"not","e":"trusted","f":"not"},"relearn":"Trusted adults are parents, teachers, counsellors and relatives you trust, not strangers or gossips.","persona":"any","source":"preparation"},
  {"id":"fw-960","cat":"find-help-no-blame","type":"sort","hook":"Sort each reason into a real reason to tell or a fear that traps you.","items":[{"id":"a","text":"Telling starts the help"},{"id":"b","text":"They might be angry, so stay silent"},{"id":"c","text":"You don't have to face it alone"},{"id":"d","text":"It's too embarrassing to say"},{"id":"e","text":"A trusted adult can stop it"},{"id":"f","text":"What if I get in trouble?"}],"bins":[{"id":"reason","label":"Real reason to tell","valence":"pos"},{"id":"trap","label":"A fear that traps you","valence":"neg"}],"key":{"a":"reason","b":"trap","c":"reason","d":"trap","e":"reason","f":"trap"},"relearn":"Telling starts help and ends the aloneness, fear of anger or shame just keeps you trapped.","persona":"any","source":"finding help"},
  {"id":"fw-961","cat":"find-help-no-blame","type":"spot","hook":"Spot the two unsafe 'helpers' a scared teen should NOT trust.","scene":[{"id":"a","text":"A stranger DMing 'I'll fix the threat for a fee'","trick":true},{"id":"b","text":"Your school counsellor","trick":false},{"id":"c","text":"Childline 1098","trick":false},{"id":"d","text":"An account offering to 'hack it back'","trick":true},{"id":"e","text":"A trusted parent or guardian","trick":false}],"why":"The paid 'fixer' and 'hack-it-back' account are scams; real help is 1098 and trusted adults.","relearn":"Real help is a trusted adult or Childline 1098, not strangers offering paid fixes.","persona":"any","source":"finding help / scams"},
  {"id":"fw-962","cat":"find-help-no-blame","type":"spot","hook":"Spot the two blaming lines that would shut a scared friend down.","scene":[{"id":"a","text":"\"This isn't your fault\"","trick":false},{"id":"b","text":"\"How could you be so careless?\"","trick":true},{"id":"c","text":"\"I believe you\"","trick":false},{"id":"d","text":"\"You really should've known better\"","trick":true},{"id":"e","text":"\"I'll help you tell someone\"","trick":false}],"why":"'How could you be so careless?' and 'you should've known better' blame the victim and silence them.","relearn":"Blaming lines shut a friend down, belief and 'not your fault' open them up.","persona":"any","source":"support / no blame"},
  {"id":"fw-963","cat":"find-help-no-blame","type":"spot","hook":"Spot the two bits of bad advice in this 'help' a friend gives.","scene":[{"id":"a","text":"\"Save the messages as evidence\"","trick":false},{"id":"b","text":"\"Just pay them and it'll stop\"","trick":true},{"id":"c","text":"\"Tell a trusted adult\"","trick":false},{"id":"d","text":"\"Delete it all so no one finds out\"","trick":true},{"id":"e","text":"\"Report at cybercrime.gov.in / 1930\"","trick":false}],"why":"'Just pay' and 'delete it all' backfire: paying invites more and deleting destroys the evidence.","relearn":"Never pay or delete the proof, save evidence, tell an adult and report.","persona":"any","source":"plan / no blame"},
  {"id":"fw-964","cat":"find-help-no-blame","type":"spot","hook":"Spot the two myths in what this worried teen believes.","scene":[{"id":"a","text":"\"If I tell, I'll be in trouble too\"","trick":true},{"id":"b","text":"\"A trusted adult can help me\"","trick":false},{"id":"c","text":"\"Reporting is pointless anyway\"","trick":true},{"id":"d","text":"\"Childline 1098 is there if I'm scared\"","trick":false},{"id":"e","text":"\"It's not my fault I was tricked\"","trick":false}],"why":"'I'll be in trouble' and 'reporting is pointless' are myths: you're protected and reporting helps.","relearn":"You won't be in trouble and reporting genuinely helps, those fears are myths.","persona":"any","source":"no blame / reporting"},
  {"id":"fw-965","cat":"find-help-no-blame","type":"spot","hook":"Spot the two unsafe replies to a sextorted friend.","scene":[{"id":"a","text":"\"Let's tell a trusted adult together\"","trick":false},{"id":"b","text":"\"Keep it secret, handle it yourself\"","trick":true},{"id":"c","text":"\"Don't reply, save the messages\"","trick":false},{"id":"d","text":"\"Send one more pic so they stop\"","trick":true},{"id":"e","text":"\"You're the victim, not in trouble\"","trick":false}],"why":"'Keep it secret' and 'send one more pic' trap your friend; real help is an adult plus evidence.","relearn":"Don't keep sextortion secret or send more, bring in an adult and save evidence.","persona":"any","source":"allyship / plan"},
  {"id":"fw-966","cat":"find-help-no-blame","type":"spot","hook":"Spot the two replies that make a struggling friend close up.","scene":[{"id":"a","text":"\"I'm here, no judgement\"","trick":false},{"id":"b","text":"\"Why are you so dramatic?\"","trick":true},{"id":"c","text":"\"It's not your fault\"","trick":false},{"id":"d","text":"\"I'm telling everyone to weigh in\"","trick":true},{"id":"e","text":"\"Want me to come with you?\"","trick":false}],"why":"'So dramatic' and 'telling everyone' break trust; gentle, private support helps.","relearn":"Mocking or broadcasting shuts a friend down; gentle private support opens them up.","persona":"any","source":"support"},
  {"id":"fw-967","cat":"find-help-no-blame","type":"spot","hook":"Spot the two 'reasons not to tell' that are traps, not facts.","scene":[{"id":"a","text":"\"There's always an adult or 1098 to call\"","trick":false},{"id":"b","text":"\"Too embarrassing, I'll stay quiet\"","trick":true},{"id":"c","text":"\"Telling makes shame smaller\"","trick":false},{"id":"d","text":"\"If I wait, it'll sort itself out\"","trick":true},{"id":"e","text":"\"I don't have to judge it alone\"","trick":false}],"why":"'Too embarrassing' and 'it'll sort out' are traps: silence grows it, telling shrinks it.","relearn":"Embarrassment and 'it'll pass' are traps; telling shrinks the problem.","persona":"any","source":"finding help"},
  {"id":"fw-968","cat":"find-help-no-blame","type":"spot","hook":"Spot the two lines that blame the victim, not the abuser.","scene":[{"id":"a","text":"\"The person who threatened you broke the law\"","trick":false},{"id":"b","text":"\"You shouldn't have trusted them\"","trick":true},{"id":"c","text":"\"Being deceived isn't a failing\"","trick":false},{"id":"d","text":"\"Well, you did send it\"","trick":true},{"id":"e","text":"\"Manipulators target careful people too\"","trick":false}],"why":"'You shouldn't have trusted them' and 'you did send it' blame the victim; the fault is the abuser's.","relearn":"The fault is the abuser's, never the teen deceived or pressured.","persona":"any","source":"no blame"},
  {"id":"fw-969","cat":"find-help-no-blame","type":"match","hook":"Match each first move to the situation it fits.","pairs":[{"left":"Block but keep the messages","right":"Someone is threatening you"},{"left":"Call 1098 together","right":"A young child is at risk"},{"left":"Wake a parent now","right":"You need help this minute"},{"left":"Ask an adult to help judge","right":"Unsure if it's serious"},{"left":"Name the flags kindly","right":"A friend is being groomed"}],"relearn":"Every situation has a calm first move, and you never make it alone.","persona":"any","source":"plan / finding help"},
  {"id":"fw-970","cat":"find-help-no-blame","type":"match","hook":"Match each myth to the truth that frees you.","pairs":[{"left":"\"I'll be in trouble\"","right":"You're a protected victim"},{"left":"\"My life is over\"","right":"There's a clear way through"},{"left":"\"Reporting does nothing\"","right":"It's how crimes get stopped"},{"left":"\"Only careless kids get tricked\"","right":"Careful teens are targeted too"},{"left":"\"Boys don't get sextorted\"","right":"Boys are heavily targeted"}],"relearn":"Each myth has a freeing truth: you're protected, there's a way through, reporting helps.","persona":"any","source":"no blame"},
  {"id":"fw-971","cat":"find-help-no-blame","type":"match","hook":"Match each trusted person to what they're best for.","pairs":[{"left":"A parent or guardian","right":"Help right now, at home"},{"left":"A school counsellor","right":"Calm, private guidance"},{"left":"Childline 1098","right":"24x7 if no adult is near"},{"left":"cybercrime.gov.in / 1930","right":"Reporting image abuse"},{"left":"A close older cousin","right":"Going with you to tell"}],"relearn":"There's a right helper for every worry, parents, counsellors, 1098 and 1930.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"fw-972","cat":"find-help-no-blame","type":"match","hook":"Match each thing a friend needs to hear with why it helps.","pairs":[{"left":"\"I believe you\"","right":"Breaks the fear of not being trusted"},{"left":"\"It's not your fault\"","right":"Lifts the self-blame"},{"left":"\"You won't be in trouble\"","right":"Removes the fear of punishment"},{"left":"\"I'll come with you\"","right":"Makes telling feel possible"},{"left":"\"We can fix this\"","right":"Replaces panic with a plan"}],"relearn":"Belief, no blame, reassurance and company are what help a scared friend act.","persona":"any","source":"support"},
  {"id":"fw-990","cat":"lock-it-down","type":"branch","hook":"You set up a new app. The default makes your profile fully public.","options":[{"text":"Switch it to private before you post anything","consequence":"Strangers can't browse or track you from day one.","outcome":"locked","best":true},{"text":"Leave the default, you'll fix it later","consequence":"Defaults are often public; lock it down before you share, not after."}],"debrief":"Set a new app private first; the default is rarely the safe one.","relearn":"Check a new app's privacy setting and go private before you post.","persona":"any","source":"privacy defaults"},
  {"id":"fw-991","cat":"lock-it-down","type":"branch","hook":"A photo app keeps tagging your exact spot on every picture you post.","options":[{"text":"Turn off location tags so your spot isn't public","consequence":"Your posts stop broadcasting where you are.","outcome":"private","best":true},{"text":"Keep it on, the map looks cool","consequence":"Location tags broadcast where you are; switch them off."}],"debrief":"Location tags quietly map your routine; turn them off.","relearn":"Switch off location tags so posts don't broadcast where you are.","persona":"any","source":"location privacy"},
  {"id":"fw-992","cat":"lock-it-down","type":"branch","hook":"You got an alert that someone logged into your account from a new device.","options":[{"text":"Change your password and turn on two-factor now","consequence":"You lock them out and add a second barrier.","outcome":"secured","best":true},{"text":"Ignore it, probably nothing","consequence":"A strange login can be a takeover; change the password and add two-factor."}],"debrief":"A new-device alert is your cue to reset the password and add two-factor.","relearn":"On a strange login: change your password and turn on two-factor.","persona":"any","source":"account security"},
  {"id":"fw-993","cat":"lock-it-down","type":"branch","hook":"A 'friend' asks for your login so they can 'fix' your profile.","options":[{"text":"Say no, your password stays yours alone","consequence":"No one can lock you out or post as you.","outcome":"safe","best":true},{"text":"Share it, they're a friend","consequence":"Even friends shouldn't hold your password; keep it yours alone."}],"debrief":"Your password is never something to lend, even to a friend.","relearn":"Never share your password, not even with a close friend.","persona":"any","source":"password hygiene"},
  {"id":"fw-994","cat":"lock-it-down","type":"branch","hook":"You want to clean up old posts but worry it'll look weird to delete them.","options":[{"text":"Set the risky old ones to private or remove them","consequence":"Your footprint shrinks to what you're glad of.","outcome":"tidy","best":true},{"text":"Leave them up so nobody notices","consequence":"Old risky posts resurface; private or remove them."}],"debrief":"Tidying old posts is footprint hygiene, not something to feel odd about.","relearn":"Set risky old posts to private or remove them.","persona":"any","source":"footprint"},
  {"id":"fw-995","cat":"lock-it-down","type":"branch","hook":"Being blackmailed, your finger hovers over 'delete account'.","options":[{"text":"Block them, but keep the messages as evidence","consequence":"You stay blocked and keep the proof.","outcome":"evidence","best":true},{"text":"Delete everything to make it disappear","consequence":"Block, don't delete; the messages are evidence."}],"debrief":"In sextortion, block contact but keep the messages, they're proof.","relearn":"Block but don't delete in sextortion; messages are evidence.","persona":"Veer","source":"sextortion / evidence (verified)"},
  {"id":"fw-996","cat":"lock-it-down","type":"branch","hook":"A stranger keeps making new accounts to message you after each block.","options":[{"text":"Block each one and report the pattern to the app","consequence":"The platform can act on a repeat offender.","outcome":"reported","best":true},{"text":"Reply once to tell them to stop","consequence":"Replying feeds them; block each account and report the pattern."}],"debrief":"Repeated new accounts are a pattern to report, not to argue with.","relearn":"Block each new account and report the pattern; don't reply.","persona":"any","source":"block & report"},
  {"id":"fw-997","cat":"lock-it-down","type":"branch","hook":"An app asks to access your contacts, photos and location 'to work better'.","options":[{"text":"Only allow what it truly needs and deny the rest","consequence":"The app gets less of your data to leak or misuse.","outcome":"minimal","best":true},{"text":"Allow everything so it stops asking","consequence":"Grant only what's needed; every extra permission is more to leak."}],"debrief":"Fewer permissions means less of your data exposed if an app leaks.","relearn":"Grant apps only the permissions they truly need; deny the rest.","persona":"any","source":"app permissions"},
  {"id":"fw-998","cat":"lock-it-down","type":"branch","hook":"You realise friends-of-friends can still see your stories.","options":[{"text":"Tighten your stories to close friends only","consequence":"Your day-to-day stops reaching near-strangers.","outcome":"private","best":true},{"text":"Leave it, more views feels nice","consequence":"Near-strangers see your routine; tighten the audience."}],"debrief":"Story audiences creep wide over time; trim them to people you trust.","relearn":"Limit who sees your stories so your routine isn't on show.","persona":"Riya","source":"audience control"},
  {"id":"fw-999","cat":"lock-it-down","type":"branch","hook":"A quiz app wants to post on your behalf for a 'fun result'.","options":[{"text":"Skip the permission; a quiz never needs to post as you","consequence":"It can't spam your friends or hijack your feed.","outcome":"safe","best":true},{"text":"Allow it, you want the result","consequence":"Letting an app post as you risks spam and scams; skip that permission."}],"debrief":"Apps that want to 'post as you' are a common scam vector; deny it.","relearn":"Don't let quiz or game apps post on your behalf; deny that permission.","persona":"any","source":"third-party apps"},
  {"id":"fw-1000","cat":"lock-it-down","type":"branch","hook":"Your DMs are open and full of requests from accounts you don't know.","options":[{"text":"Switch DMs to friends-only and clear the rest","consequence":"Strangers can no longer slide into your inbox.","outcome":"locked","best":true},{"text":"Leave them open in case it's someone cool","consequence":"Open DMs invite strangers; set them to friends-only."}],"debrief":"Friends-only DMs shut the easiest door strangers use to reach you.","relearn":"Set DMs to friends-only and clear stranger requests.","persona":"any","source":"DM control"},
  {"id":"fw-1001","cat":"lock-it-down","type":"branch","hook":"You face a sextortion threat but don't know where to report.","options":[{"text":"Report at cybercrime.gov.in / 1930 and tell an adult","consequence":"It reaches people whose job is to stop it.","outcome":"reported","best":true},{"text":"Try to handle it alone","consequence":"Report at cybercrime.gov.in / 1930; don't carry it alone."}],"debrief":"Image threats have a real route: cybercrime.gov.in / 1930 plus an adult.","relearn":"Report image abuse at cybercrime.gov.in / 1930 and tell an adult.","persona":"Counsellor","source":"reporting (verified)"},
  {"id":"fw-1002","cat":"lock-it-down","type":"branch","hook":"A creepy account is hassling your younger cousin.","options":[{"text":"Help them screenshot, block, report and tell an adult","consequence":"Your cousin is protected and the account is flagged.","outcome":"protected","best":true},{"text":"Tell them to just log off a while","consequence":"Logging off won't stop it; screenshot, block, report, tell an adult."}],"debrief":"The block-report-tell plan works for someone you're helping too.","relearn":"Help a younger relative screenshot, block, report and tell an adult.","persona":"any","source":"mentoring"},
  {"id":"fw-1003","cat":"lock-it-down","type":"branch","hook":"You're about to reuse the same password you use everywhere on a new site.","options":[{"text":"Make a fresh, unique password for it","consequence":"One leaked site can't unlock the rest of your accounts.","outcome":"secured","best":true},{"text":"Reuse it, it's easier to remember","consequence":"Reused passwords mean one leak unlocks everything; make it unique."}],"debrief":"A unique password per site stops one breach becoming all of them.","relearn":"Use a unique password per site so one leak can't unlock the rest.","persona":"any","source":"password hygiene"},
  {"id":"fw-1004","cat":"lock-it-down","type":"branch","hook":"You moved cities and want to post your new address and school.","options":[{"text":"Keep your address and school off public posts","consequence":"Strangers can't find where you live or study.","outcome":"private","best":true},{"text":"Post it so old friends find you","consequence":"Share that privately; keep address and school off public posts."}],"debrief":"You can reach old friends privately without broadcasting where you are.","relearn":"Keep your address and school off public posts; share them privately.","persona":"any","source":"footprint"},
  {"id":"fw-1005","cat":"lock-it-down","type":"sort","hook":"Sort each move: locks it down, or leaves you exposed?","items":[{"id":"a","text":"Friends-only DMs"},{"id":"b","text":"Reusing one password everywhere"},{"id":"c","text":"Reviewing app permissions"},{"id":"d","text":"Letting a quiz post as you"},{"id":"e","text":"Turning off location tags"},{"id":"f","text":"Live location on for all"}],"bins":[{"id":"lock","label":"Locks it down","valence":"pos"},{"id":"expose","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"lock","b":"expose","c":"lock","d":"expose","e":"lock","f":"expose"},"relearn":"Friends-only DMs, permission checks and no location tags lock down; password reuse and live location expose.","persona":"any","source":"privacy"},
  {"id":"fw-1006","cat":"lock-it-down","type":"sort","hook":"Sort: a smart first move, or one that backfires, when a contact turns creepy?","items":[{"id":"a","text":"Screenshot the messages"},{"id":"b","text":"Argue back to 'win'"},{"id":"c","text":"Block the account"},{"id":"d","text":"Send a selfie to prove you're 'not scared'"},{"id":"e","text":"Report it to the app"},{"id":"f","text":"Tell a trusted adult"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"back","label":"Backfires","valence":"neg"}],"key":{"a":"smart","b":"back","c":"smart","d":"back","e":"smart","f":"smart"},"relearn":"Screenshot, block, report and tell an adult are smart; arguing or sending more backfires.","persona":"any","source":"block & report"},
  {"id":"fw-1007","cat":"lock-it-down","type":"sort","hook":"Sort each setting: protects your account, or weakens it?","items":[{"id":"a","text":"Two-factor turned on"},{"id":"b","text":"Password written in your bio"},{"id":"c","text":"A unique passcode per app"},{"id":"d","text":"'Remember me' on a shared computer"},{"id":"e","text":"Logging out of cyber-cafe sessions"},{"id":"f","text":"Saving passwords in a public note"}],"bins":[{"id":"protect","label":"Protects it","valence":"pos"},{"id":"weaken","label":"Weakens it","valence":"neg"}],"key":{"a":"protect","b":"weaken","c":"protect","d":"weaken","e":"protect","f":"weaken"},"relearn":"Two-factor, unique passcodes and logging out protect you; bios, shared logins and public notes weaken you.","persona":"any","source":"account security"},
  {"id":"fw-1008","cat":"lock-it-down","type":"sort","hook":"Sort: belongs in a public post, or keep it private?","items":[{"id":"a","text":"A meme you like"},{"id":"b","text":"Your live location right now"},{"id":"c","text":"A favourite song"},{"id":"d","text":"Your full timetable"},{"id":"e","text":"A drawing you made"},{"id":"f","text":"Your home address"}],"bins":[{"id":"public","label":"Fine to post","valence":"pos"},{"id":"private","label":"Keep private","valence":"neg"}],"key":{"a":"public","b":"private","c":"public","d":"private","e":"public","f":"private"},"relearn":"Memes, songs and art are fine public; live location, timetable and address stay private.","persona":"any","source":"footprint"},
  {"id":"fw-1009","cat":"lock-it-down","type":"sort","hook":"Sort each worry to the right India route.","items":[{"id":"a","text":"Blackmailed with an image"},{"id":"b","text":"A creepy stranger account"},{"id":"c","text":"You need help right now"},{"id":"d","text":"A friend under 18 threatened"},{"id":"e","text":"Proof you want kept safe"},{"id":"f","text":"A 'free money' scam DM"}],"bins":[{"id":"report","label":"Cyber report / 1930","valence":"tell"},{"id":"app","label":"Block & report in-app","valence":"tell"},{"id":"adult","label":"Trusted adult / 1098","valence":"tell"}],"key":{"a":"report","b":"app","c":"adult","d":"adult","e":"report","f":"app"},"relearn":"Image abuse and proof to 1930; creepy or scam accounts to in-app block & report; people to an adult or 1098.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"fw-1010","cat":"lock-it-down","type":"match","hook":"Match each privacy setting to what it controls.","pairs":[{"left":"Account privacy","right":"Who sees your posts"},{"left":"DM settings","right":"Who can message you"},{"left":"Location toggle","right":"Whether posts show your spot"},{"left":"Tag approval","right":"What gets pinned to you"},{"left":"Story audience","right":"Who watches your day"}],"relearn":"Each setting controls one thing: posts, messages, location, tags or story views.","persona":"any","source":"privacy settings"},
  {"id":"fw-1011","cat":"lock-it-down","type":"match","hook":"Match each unsafe move to its safer swap.","pairs":[{"left":"Open DMs for all","right":"Friends-only DMs"},{"left":"Reusing one password","right":"A unique one per app"},{"left":"Live location on","right":"Location tags off"},{"left":"Arguing with a creep","right":"Block and report"},{"left":"Deleting evidence","right":"Screenshot and keep it"}],"relearn":"Every risky habit has a quick safer swap that locks things down.","persona":"any","source":"safer swaps"},
  {"id":"fw-1012","cat":"lock-it-down","type":"match","hook":"Match each tool to the moment you reach for it.","pairs":[{"left":"Block","right":"Stop a creep contacting you"},{"left":"Report","right":"Flag them to the platform"},{"left":"Screenshot","right":"Keep proof before blocking"},{"left":"Two-factor","right":"Guard against a stolen password"},{"left":"Private mode","right":"Keep strangers off your profile"}],"relearn":"Block to stop, report to flag, screenshot to keep proof, two-factor to guard, private to shut out.","persona":"any","source":"tools"},
  {"id":"fw-1013","cat":"lock-it-down","type":"match","hook":"Match each setting change to the risk it lowers.","pairs":[{"left":"Closing open DMs","right":"Strangers messaging you"},{"left":"Hiding your location","right":"Being followed offline"},{"left":"Limiting app permissions","right":"Your data leaking"},{"left":"Setting stories to close friends","right":"Routine on show to all"},{"left":"Removing school from bio","right":"Being found in person"}],"relearn":"Each setting change lowers a specific real-world risk.","persona":"any","source":"security"},
  {"id":"fw-1014","cat":"lock-it-down","type":"match","hook":"Match each habit to why it matters.","pairs":[{"left":"Unique passwords","right":"One leak can't unlock all"},{"left":"Logging out on shared PCs","right":"Next user can't get in"},{"left":"Two-factor login","right":"A code blocks takeover"},{"left":"Checking login alerts","right":"You catch intruders early"},{"left":"Not saving passwords publicly","right":"No one can read them"}],"relearn":"Each security habit has a clear reason it keeps your account yours.","persona":"any","source":"account security"},
  {"id":"fw-1015","cat":"lock-it-down","type":"spot","hook":"Spot the two settings to turn off before a school trip you'll post about.","scene":[{"id":"a","text":"Posts set to friends-only","trick":false},{"id":"b","text":"Live location on every photo","trick":true},{"id":"c","text":"Real-time 'I'm at...' check-ins","trick":true},{"id":"d","text":"Posting the photos after you're home","trick":false},{"id":"e","text":"Sharing only with close friends","trick":false}],"why":"Live location and real-time check-ins broadcast where you are; posting later and to friends-only is safe.","relearn":"Turn off live location and real-time check-ins; post after you're home.","persona":"any","source":"footprint / location"},
  {"id":"fw-1016","cat":"lock-it-down","type":"spot","hook":"Spot the two app permissions a simple game does NOT need.","scene":[{"id":"a","text":"Access to your microphone","trick":true},{"id":"b","text":"Permission to save game progress","trick":false},{"id":"c","text":"Read all your contacts","trick":true},{"id":"d","text":"Show you the leaderboard","trick":false},{"id":"e","text":"Store your high score","trick":false}],"why":"A simple game has no need for your mic or contacts; those are the over-reaches to deny.","relearn":"Deny permissions an app doesn't need, like mic or contacts for a basic game.","persona":"any","source":"app permissions"},
  {"id":"fw-1017","cat":"lock-it-down","type":"spot","hook":"Spot the two things that make a 'win a phone' DM a scam.","scene":[{"id":"a","text":"It asks for your password to 'verify'","trick":true},{"id":"b","text":"It's from an account you've never seen","trick":false},{"id":"c","text":"It rushes you: 'claim in 5 minutes'","trick":true},{"id":"d","text":"It has a few spelling mistakes","trick":false},{"id":"e","text":"It uses a brand logo","trick":false}],"why":"Asking for your password and rushing you are the scam tells; report and block it.","relearn":"A DM asking for your password and rushing you is a scam; block and report it.","persona":"any","source":"scam spotting"},
  {"id":"fw-1018","cat":"lock-it-down","type":"spot","hook":"Spot the two weak links in this account setup.","scene":[{"id":"a","text":"Two-factor switched on","trick":false},{"id":"b","text":"Birthday used as the password","trick":true},{"id":"c","text":"A recovery email you control","trick":false},{"id":"d","text":"Password also used for email","trick":true},{"id":"e","text":"You log out on shared phones","trick":false}],"why":"A birthday password and reusing it on email are the weak links; the rest are solid.","relearn":"Don't use your birthday or reuse a password across email and apps.","persona":"any","source":"account security"},
  {"id":"fw-1019","cat":"lock-it-down","type":"spot","hook":"Spot the two profile details that help a stranger find you offline.","scene":[{"id":"a","text":"Your school name and class","trick":true},{"id":"b","text":"A username with no real name","trick":false},{"id":"c","text":"Your daily coaching-class timings","trick":true},{"id":"d","text":"A favourite cricket team","trick":false},{"id":"e","text":"A cartoon profile picture","trick":false}],"why":"Your school and your daily timings let a stranger find you in person; a team or avatar doesn't.","relearn":"Keep your school and routine timings off your profile; they help strangers find you.","persona":"Riya","source":"footprint"},
  {"id":"fw-1020","cat":"lock-it-down","type":"spot","hook":"Spot the two replies that keep a creepy DM going instead of ending it.","scene":[{"id":"a","text":"'Leave me alone' then more replies","trick":true},{"id":"b","text":"Screenshotting the chat","trick":false},{"id":"c","text":"'Send your number and I'll think about it'","trick":true},{"id":"d","text":"Tapping block","trick":false},{"id":"e","text":"Tapping report","trick":false}],"why":"Bargaining and handing over your number keep the creep engaged; screenshot, block and report end it.","relearn":"Don't bargain or hand over your number; screenshot, block and report to end it.","persona":"any","source":"block & report"},
  {"id":"fw-1021","cat":"lock-it-down","type":"spot","hook":"Spot the two settings that quietly leak your location.","scene":[{"id":"a","text":"Live location shared in a group","trick":true},{"id":"b","text":"Photos posted a day later","trick":false},{"id":"c","text":"Geotags left on every photo","trick":true},{"id":"d","text":"A private account","trick":false},{"id":"e","text":"Avatar instead of a face photo","trick":false}],"why":"Live group location and photo geotags leak where you are; the others don't.","relearn":"Turn off live location sharing and photo geotags to stop leaking your spot.","persona":"any","source":"location privacy"},
  {"id":"fw-1022","cat":"lock-it-down","type":"spot","hook":"Spot the two parts of this 'security check' email that mark it as phishing.","scene":[{"id":"a","text":"A link to 're-enter your password'","trick":true},{"id":"b","text":"It greets you by your username","trick":false},{"id":"c","text":"'Act now or your account is deleted'","trick":true},{"id":"d","text":"It mentions the app's name","trick":false},{"id":"e","text":"It has a footer","trick":false}],"why":"A password-link and a scare deadline are phishing tells; never log in through an emailed link.","relearn":"A link to 're-enter your password' plus a scare deadline is phishing; don't click it.","persona":"any","source":"phishing"},
  {"id":"fw-1023","cat":"lock-it-down","type":"spot","hook":"Spot the two moves that destroy evidence in a blackmail case.","scene":[{"id":"a","text":"Screenshot the threats and profile","trick":false},{"id":"b","text":"Delete the whole chat to feel safer","trick":true},{"id":"c","text":"Note the username and link","trick":false},{"id":"d","text":"Wipe your account entirely","trick":true},{"id":"e","text":"Block after saving the proof","trick":false}],"why":"Deleting the chat or wiping your account destroys the evidence; screenshot and note details first.","relearn":"In blackmail, screenshot and note details first; don't delete the chat or your account.","persona":"Veer","source":"sextortion / evidence (verified)"},
  {"id":"fw-1024","cat":"lock-it-down","type":"spot","hook":"Spot the two reasons this 'free followers' app is unsafe to log into.","scene":[{"id":"a","text":"It needs your account password","trick":true},{"id":"b","text":"It has a colourful logo","trick":false},{"id":"c","text":"It wants to post on your behalf","trick":true},{"id":"d","text":"It shows a follower counter","trick":false},{"id":"e","text":"It has many downloads","trick":false}],"why":"Wanting your password and the power to post as you are how these apps hijack accounts.","relearn":"Don't give a 'free followers' app your password or permission to post as you.","persona":"any","source":"third-party apps"},
  {"id":"fw-1025","cat":"lock-it-down","type":"spot","hook":"Spot the two oversharing posts to skip.","scene":[{"id":"a","text":"'Home alone all week, parents away!'","trick":true},{"id":"b","text":"A photo of your dog","trick":false},{"id":"c","text":"A pic of your new house number and street","trick":true},{"id":"d","text":"A meme about exams","trick":false},{"id":"e","text":"Your favourite movie","trick":false}],"why":"'Home alone' and your house number tell strangers exactly where and when; skip those.","relearn":"Don't post that you're home alone or show your house number and street.","persona":"any","source":"footprint"},
  {"id":"fw-1026","cat":"lock-it-down","type":"spot","hook":"Spot the two settings to fix on a shared family tablet.","scene":[{"id":"a","text":"Your account stays logged in for all","trick":true},{"id":"b","text":"A separate profile for each person","trick":false},{"id":"c","text":"Your passwords saved in the browser for anyone","trick":true},{"id":"d","text":"A screen lock on the tablet","trick":false},{"id":"e","text":"Apps updated regularly","trick":false}],"why":"Staying logged in and saving your passwords for anyone lets others into your accounts; fix those.","relearn":"On a shared device, log out and don't leave your passwords saved for everyone.","persona":"any","source":"shared device security"},
  {"id":"fw-1027","cat":"lock-it-down","type":"spot","hook":"Spot the two reasons not to accept this follow request.","scene":[{"id":"a","text":"Account made yesterday, zero posts","trick":true},{"id":"b","text":"You have two mutual friends","trick":false},{"id":"c","text":"It immediately DMs 'hey cutie'","trick":true},{"id":"d","text":"It follows a few public pages","trick":false},{"id":"e","text":"It has a generic name","trick":false}],"why":"A brand-new empty account that instantly DMs 'hey cutie' is a red flag; decline and block.","relearn":"A day-old empty account that instantly flirts is a red flag; decline and block.","persona":"any","source":"who to accept"},
  {"id":"fw-1028","cat":"lock-it-down","type":"role-play","hook":"A friend wants your Instagram password to 'post for you while you're away'.","setup":"Keep your login yours. Say:","yourLine":[{"text":"\"I don't share my password with anyone, even you. I'll post myself.\"","best":true},{"text":"\"Okay, here it is.\""}],"relearn":"Keep your password yours alone, even from close friends.","persona":"any","source":"password voice"},
  {"id":"fw-1029","cat":"lock-it-down","type":"role-play","hook":"Coach a friend on the first move when a stranger turns creepy in their DMs.","setup":"Give the calm steps. Say:","yourLine":[{"text":"\"Screenshot it, then block and report them. Don't reply, and tell an adult.\"","best":true},{"text":"\"Just argue back till they stop.\""}],"relearn":"The calm steps: screenshot, block, report, don't reply, tell an adult.","persona":"any","source":"block & report"},
  {"id":"fw-1030","cat":"lock-it-down","type":"role-play","hook":"A classmate brags about posting their live location everywhere.","setup":"Nudge them kindly. Say:","yourLine":[{"text":"\"Maybe turn off live location? It kind of tells strangers where you are.\"","best":true},{"text":"\"Cool, do whatever.\""}],"relearn":"It's fair to nudge a friend to turn off live location.","persona":"any","source":"peer nudge"},
  {"id":"fw-1031","cat":"lock-it-down","type":"role-play","hook":"Your cousin asks if they should reply to a scammy 'you won a prize' DM.","setup":"Steer them right. Say:","yourLine":[{"text":"\"Don't reply or tap the link. Just block and report it, it's a scam.\"","best":true},{"text":"\"Maybe reply and see what happens.\""}],"relearn":"Don't reply or click a prize-scam DM; block and report it.","persona":"any","source":"scam coaching"},
  {"id":"fw-1032","cat":"lock-it-down","type":"role-play","hook":"A friend says two-factor login is 'too much hassle'.","setup":"Make the case simply. Say:","yourLine":[{"text":"\"It's one extra tap, and it stops someone logging in even with your password.\"","best":true},{"text":"\"Yeah, skip it then.\""}],"relearn":"Two-factor is one extra tap that blocks logins even if a password leaks.","persona":"any","source":"peer nudge"},
  {"id":"fw-1033","cat":"lock-it-down","type":"role-play","hook":"Your younger sibling wants to make their new account public 'for more likes'.","setup":"Set them up safe. Say:","yourLine":[{"text":"\"Keep it private and only add people you actually know. Likes aren't worth strangers.\"","best":true},{"text":"\"Sure, go public.\""}],"relearn":"Start a new account private and add only people you actually know.","persona":"any","source":"mentoring"},
  {"id":"fw-1034","cat":"lock-it-down","type":"role-play","hook":"A friend is about to delete everything because someone is blackmailing them.","setup":"Stop them gently and guide. Say:","yourLine":[{"text":"\"Don't delete it, screenshot first, that's evidence. Then block and let's tell an adult.\"","best":true},{"text":"\"Yeah, just delete it all.\""}],"relearn":"Don't delete in blackmail; screenshot first as evidence, then block and tell an adult.","persona":"Counsellor","source":"sextortion support (verified)"},
  {"id":"fw-1035","cat":"lock-it-down","type":"strike-rewrite","hook":"\"A private account means no one can ever bother me.\"","myth":{"un":"If my account is private, no one can ever bother me.","re":"Private helps a lot, but still block, report and never share your login.","why":"Privacy is one layer; the other tools and habits still matter."},"relearn":"Private accounts help, but you still need block, report and a guarded password.","persona":"any","source":"privacy myth"},
  {"id":"fw-1036","cat":"lock-it-down","type":"strike-rewrite","hook":"\"If I block someone, the proof is gone, so why screenshot?\"","myth":{"un":"Blocking deletes the messages, so screenshots are pointless.","re":"Blocking only stops contact; screenshot first so you keep the evidence.","why":"You may need that proof to report; blocking doesn't save it for you."},"relearn":"Blocking only stops contact; screenshot first to keep the evidence.","persona":"any","source":"evidence"},
  {"id":"fw-1037","cat":"lock-it-down","type":"strike-rewrite","hook":"\"Strong passwords are a hassle; a simple one is fine.\"","myth":{"un":"A simple, easy password is fine; strong ones are just a hassle.","re":"Simple passwords are guessed fast; a longer unique one is your basic lock.","why":"Common and short passwords are the first thing attackers try."},"relearn":"A longer, unique password is your basic lock; simple ones get guessed fast.","persona":"any","source":"password hygiene"},
  {"id":"fw-1038","cat":"lock-it-down","type":"strike-rewrite","hook":"\"Reporting an account never does anything.\"","myth":{"un":"Reporting a creepy account never does anything.","re":"Reports help platforms act and build a record if it escalates; it's worth doing.","why":"Each report adds to a pattern that gets accounts removed."},"relearn":"Reporting helps platforms act and builds a record; it's worth doing.","persona":"Counsellor","source":"reporting (verified)"},
  {"id":"fw-1039","cat":"lock-it-down","type":"strike-rewrite","hook":"\"Turning on location sharing makes me safer, friends can find me.\"","myth":{"un":"Sharing my live location everywhere makes me safer.","re":"Share live location only with trusted people, not publicly; public sharing exposes you.","why":"A public location lets strangers, not just friends, track you."},"relearn":"Share live location only with trusted people; public location exposes you.","persona":"any","source":"location privacy"},
  {"id":"fw-1040","cat":"lock-it-down","type":"strike-rewrite","hook":"\"Two-factor login is only for adults' bank accounts.\"","myth":{"un":"Two-factor login is only needed for adults' bank accounts.","re":"It protects any account; turning it on on your social apps blocks takeovers.","why":"Social accounts get hijacked too; the second step stops it."},"relearn":"Two-factor protects any account, including your social apps, from takeover.","persona":"any","source":"account security"},
  {"id":"fw-1041","cat":"lock-it-down","type":"strike-rewrite","hook":"\"It's rude to ignore a follow request from a stranger.\"","myth":{"un":"It's rude to decline or ignore a stranger's follow request.","re":"You owe no stranger access; declining or ignoring is a normal safe choice.","why":"Your account is yours; curating who's in it isn't rudeness."},"relearn":"You owe no stranger access; declining a follow request is a normal safe choice.","persona":"any","source":"who to accept"},
  {"id":"fw-1042","cat":"lock-it-down","type":"strike-rewrite","hook":"\"If an app is on the official store, all its permissions are safe.\"","myth":{"un":"If an app is on the official store, every permission it asks is safe to grant.","re":"Even store apps over-ask; grant only what the app truly needs and deny the rest.","why":"Being listed doesn't mean an app needs your contacts, mic or location."},"relearn":"Even store apps over-ask; grant only the permissions an app truly needs.","persona":"any","source":"app permissions"},
  {"id":"fw-1043","cat":"lock-it-down","type":"reflect","hook":"Lensy: which lock-it-down move feels easiest for you to do today?","prompt":"Pick one to start with.","options":["Go private","Turn on two-factor","Close open DMs"],"affirm":"Any one of these is a real step; starting with the easiest one still locks things down. 💛","relearn":"Starting with one easy privacy step already makes you safer.","persona":"any","source":"reflection"},
  {"id":"fw-1044","cat":"lock-it-down","type":"reflect","hook":"Lensy: if a contact ever turned creepy, what would you reach for first?","prompt":"What feels right to you?","options":["Screenshot it","Block them","Tell an adult"],"affirm":"All three belong in the plan, and reaching for any one first is exactly right.","relearn":"Screenshot, block and tell an adult are all right first moves.","persona":"any","source":"reflection"},
  {"id":"fw-1045","cat":"lock-it-down","type":"reflect","hook":"Lensy: who would you list as your trusted adults if something online went wrong?","prompt":"Picture them.","options":["A parent","A teacher","A counsellor"],"affirm":"Knowing your people before you need them means help is close when it counts. 💛","relearn":"Naming your trusted adults in advance makes help faster when it counts.","persona":"any","source":"reflection"},
  {"id":"fw-1046","cat":"lock-it-down","type":"reflect","hook":"Lensy: how does it feel knowing block and report are always one tap away?","prompt":"What do you think?","options":["Reassuring","In control","Less worried"],"affirm":"You always have the controls; that's being ready, not scared. 💛","relearn":"Block and report are always one tap away; you're ready, not scared.","persona":"any","source":"reassurance"},
  {"id":"fw-1047","cat":"lock-it-down","type":"reflect","hook":"Lensy: which password habit will you start this week?","prompt":"Pick one.","options":["A unique password","Turn on two-factor","Stop sharing it"],"affirm":"Any of these locks your accounts a little tighter, and small steps count. 💛","relearn":"Any one password habit makes your accounts a little safer.","persona":"any","source":"reflection"},
  {"id":"fw-1048","cat":"lock-it-down","type":"reflect","hook":"Lensy: what would you check first on your profile to tidy your footprint?","prompt":"What comes to mind?","options":["Old risky posts","Location tags","School in bio"],"affirm":"Whatever you check first, you're taking charge of your footprint. 💛","relearn":"Checking any one footprint detail puts you in charge of it.","persona":"any","source":"reflection"},
  {"id":"fw-1049","cat":"lock-it-down","type":"reflect","hook":"Lensy: how does having a 'lock it down' checklist change how online feels?","prompt":"Notice the shift.","options":["Calmer","More in control","Still fun, safer"],"affirm":"A few settings sorted, and the net stays great, just safer for you. 💛","relearn":"A simple checklist keeps the net fun and a lot safer for you.","persona":"any","source":"reassurance"},
  {"id":"fw-1050","cat":"lock-it-down","type":"branch","hook":"You're at a cyber-cafe and need to check your account quickly.","options":[{"text":"Use a private window and log out fully after","consequence":"No saved login is left behind for the next user.","outcome":"clean","best":true},{"text":"Just close the tab when done","consequence":"Closing a tab can leave you logged in; use private mode and log out."}],"debrief":"On any shared computer, private mode plus a full log-out leaves nothing behind.","relearn":"On shared computers, use a private window and log out fully.","persona":"any","source":"shared device security"},
  {"id":"fw-1051","cat":"lock-it-down","type":"branch","hook":"An account messages 'I have your photos' but shows nothing.","options":[{"text":"Don't engage; screenshot, block, report, tell an adult","consequence":"The bluff gets no power and you're not alone.","outcome":"calm","best":true},{"text":"Panic and ask what they want","consequence":"Engaging feeds a bluff; block and tell an adult."}],"debrief":"Most such threats are empty bluffs; don't engage, save proof, block, tell an adult.","relearn":"No-proof 'I have your photos': don't engage; screenshot, block, tell an adult.","persona":"Veer","source":"sextortion bluff (verified)"},
  {"id":"fw-1080","cat":"myths-busted","type":"strike-rewrite","hook":"\"A verified blue tick means the account is real and safe.\"","myth":{"un":"A blue tick means the account is real and safe to trust.","re":"A tick only shows a name was checked once; it never proves someone is safe to share with.","why":"Ticks can be bought, faked or sold; safety is about behaviour, not badges."},"relearn":"A blue tick isn't proof of safety; judge people by how they act.","persona":"any","source":"verification myth"},
  {"id":"fw-1081","cat":"myths-busted","type":"strike-rewrite","hook":"\"I'd easily spot a fake profile, so I don't need to be careful.\"","myth":{"un":"I'd instantly spot any fake; careful people like me are fine.","re":"Skilled fakes fool careful people too; staying private is smarter than feeling un-foolable.","why":"Over-confidence is exactly what a good catfish counts on."},"relearn":"No one spots every fake; staying private beats feeling un-foolable.","persona":"any","source":"overconfidence myth"},
  {"id":"fw-1082","cat":"myths-busted","type":"strike-rewrite","hook":"\"If they video-called me once, they must be the real person.\"","myth":{"un":"They did a video call once, so they're definitely who they claim.","re":"One quick call proves little; pre-recorded clips and borrowed faces are used to fake it.","why":"A single call is easy to fake and doesn't make someone safe."},"relearn":"One video call isn't proof; a real person still earns trust slowly.","persona":"any","source":"catfish myth"},
  {"id":"fw-1083","cat":"myths-busted","type":"strike-rewrite","hook":"\"We have hundreds of mutual followers, so this stranger is safe.\"","myth":{"un":"We share loads of mutual followers, so they must be safe.","re":"Mutuals are easy to farm and copy; shared followers don't tell you who someone really is.","why":"A fake account can follow your friends in minutes to look legit."},"relearn":"Mutual followers don't prove safety; a stranger is still a stranger.","persona":"any","source":"social-proof myth"},
  {"id":"fw-1084","cat":"myths-busted","type":"strike-rewrite","hook":"\"Gifts and game top-ups from a new online friend are just kindness.\"","myth":{"un":"They sent me game credits and gifts, that's just them being kind.","re":"Free gifts from a new contact often come with a 'now you owe me' later; pause and tell an adult.","why":"Buying small favours first is a known grooming opener."},"relearn":"Gifts from a new online contact can be a hook, not just kindness.","persona":"Veer","source":"grooming-opener myth"},
  {"id":"fw-1085","cat":"myths-busted","type":"strike-rewrite","hook":"\"If a chat app deletes messages after a few seconds, nothing can be saved.\"","myth":{"un":"On a disappearing-message app, nothing I send can be saved.","re":"The other side can screenshot or screen-record before it vanishes; assume any send can be kept.","why":"'Vanishing' is a feeling of safety, not an actual guarantee."},"relearn":"Disappearing messages can still be screenshotted; nothing's truly gone.","persona":"any","source":"vanishing-app myth"},
  {"id":"fw-1086","cat":"myths-busted","type":"strike-rewrite","hook":"\"Cropping out my face makes a photo safe to send.\"","myth":{"un":"If I crop my face out, the photo can't ever be traced to me.","re":"Backgrounds, uniforms, room details and tags can still identify you; a 'faceless' pic isn't anonymous.","why":"People are recognised by far more than their face."},"relearn":"Cropping your face out doesn't make a photo safe or anonymous.","persona":"any","source":"footprint myth"},
  {"id":"fw-1087","cat":"myths-busted","type":"strike-rewrite","hook":"\"My account is private, so I can post my live location safely.\"","myth":{"un":"My account is private, so live location and routine are safe to post.","re":"Private isn't airtight: followers can screenshot or reshare, so keep live location off anyway.","why":"A private setting limits who sees, it doesn't stop them passing it on."},"relearn":"Even on a private account, keep live location and routine offline.","persona":"any","source":"privacy myth"},
  {"id":"fw-1088","cat":"myths-busted","type":"strike-rewrite","hook":"\"Sexting is totally normal now, so refusing is being uptight.\"","myth":{"un":"Everyone sends nudes now; saying no just makes me uptight.","re":"Plenty of teens don't, the risks are real, and 'no' is always a complete, normal answer.","why":"'Everyone does it' is peer pressure dressed up as a fact."},"relearn":"Not everyone sexts; saying no is normal and always okay.","persona":"Riya","source":"pressure myth"},
  {"id":"fw-1089","cat":"myths-busted","type":"strike-rewrite","hook":"\"If we're dating, sending a private photo is no big deal.\"","myth":{"un":"We're together, so sending a private photo is no big deal.","re":"Dating doesn't remove the risk; a break-up or screenshot can spread it, and 'no' stays valid.","why":"Relationships change; a copy of a photo doesn't disappear with them."},"relearn":"Being in a relationship doesn't make sending photos risk-free.","persona":"Riya","source":"relationship myth"},
  {"id":"fw-1090","cat":"myths-busted","type":"strike-rewrite","hook":"\"If you pay the blackmailer once, they'll finally leave you alone.\"","myth":{"un":"Pay them once and they'll be satisfied and stop.","re":"Paying shows you'll comply and usually brings more demands; don't pay, save proof, get help.","why":"A payment is proof to them that pressure works on you."},"relearn":"Paying a blackmailer once invites more; don't pay, get help.","persona":"Veer","source":"sextortion myth"},
  {"id":"fw-1091","cat":"myths-busted","type":"strike-rewrite","hook":"\"Sending one more photo will finally make the blackmail stop.\"","myth":{"un":"If I send just one more, they'll keep their promise and stop.","re":"Another image only hands them more power; sending more never ends it, getting help does.","why":"Their 'promise' is bait; compliance feeds the threat."},"relearn":"Sending more never ends blackmail; stop and reach for help.","persona":"any","source":"sextortion myth"},
  {"id":"fw-1092","cat":"myths-busted","type":"strike-rewrite","hook":"\"Blocking the blackmailer means I should delete the chat too.\"","myth":{"un":"Once I block them, I should delete the whole chat to feel clean.","re":"Block to stop contact, but keep the messages, they're the proof an adult and the police need.","why":"Deleting the evidence makes it harder to act against them."},"relearn":"Block to stop contact, but keep the messages as evidence.","persona":"any","source":"evidence myth"},
  {"id":"fw-1093","cat":"myths-busted","type":"strike-rewrite","hook":"\"Being tricked into sending something proves I was just stupid.\"","myth":{"un":"I got tricked into sending it, so I must be stupid and to blame.","re":"You were deceived by someone skilled at it; the fault is theirs, and help is still there for you.","why":"Manipulation is designed to fool smart, careful people."},"relearn":"Being tricked isn't being stupid; the blame is the manipulator's.","persona":"any","source":"no-blame myth"},
  {"id":"fw-1094","cat":"myths-busted","type":"strike-rewrite","hook":"\"Telling my parents will get my phone taken and make everything worse.\"","myth":{"un":"If I tell my parents, they'll just take my phone and it'll get worse.","re":"A trusted adult is your way out, not your punishment; you're the one being protected, not blamed.","why":"Silence is the trap the abuser relies on."},"relearn":"Telling a trusted adult is the way out, not extra punishment.","persona":"any","source":"telling myth"},
  {"id":"fw-1095","cat":"myths-busted","type":"strike-rewrite","hook":"\"If this got out, my life would be completely over.\"","myth":{"un":"If this ever got out, my whole life would be over.","re":"It can feel that huge, but these situations are survivable and fixable with the right help.","why":"The panic is part of the trap; there's always a way through."},"relearn":"It feels huge, but there's a clear way through with the right help.","persona":"any","source":"hope myth"},
  {"id":"fw-1096","cat":"myths-busted","type":"strike-rewrite","hook":"\"Reporting online crime in India just disappears into a void.\"","myth":{"un":"Reporting cybercrime here goes nowhere; nobody acts on it.","re":"Reports are taken seriously and routed for action; speaking up is how these crimes get stopped.","why":"Staying silent is the only thing that truly helps the criminal."},"relearn":"Reporting is acted on and is how these crimes get stopped.","persona":"Counsellor","source":"reporting myth"},
  {"id":"fw-1097","cat":"myths-busted","type":"strike-rewrite","hook":"\"Sextortion only targets girls; as a boy I'm not at risk.\"","myth":{"un":"Sextortion is a girls' problem; boys like me aren't targeted.","re":"Teen boys are heavily targeted, especially for money; everyone needs the same calm plan.","why":"Assuming you're immune is exactly what's exploited."},"relearn":"Boys are heavily targeted too; everyone needs the plan.","persona":"Veer","source":"who-is-targeted myth"},
  {"id":"fw-1098","cat":"myths-busted","type":"strike-rewrite","hook":"\"Groomers are obvious creeps, so a normal, friendly person is fine.\"","myth":{"un":"Groomers are obviously creepy, so a kind, normal person is safe.","re":"Most start out warm and ordinary; that's the disguise, so watch behaviour, not vibes.","why":"Seeming nice is the tactic, not the proof."},"relearn":"Groomers often seem kind and normal; watch actions, not vibes.","persona":"any","source":"appearance myth"},
  {"id":"fw-1099","cat":"myths-busted","type":"strike-rewrite","hook":"\"Only kids on dodgy apps get groomed; mainstream apps are safe.\"","myth":{"un":"Grooming only happens on shady apps, not the ones everyone uses.","re":"It happens on popular games and apps too; the pattern matters more than the platform.","why":"Abusers go where teens already are."},"relearn":"Grooming happens on mainstream apps too; know the pattern.","persona":"any","source":"platform myth"},
  {"id":"fw-1100","cat":"myths-busted","type":"strike-rewrite","hook":"\"If I never share photos, I've got nothing to worry about online.\"","myth":{"un":"As long as I never send photos, I'm completely safe online.","re":"Photos are one risk; grooming, fake friends and shared private info are real too, so stay alert.","why":"Safety is a whole habit, not a single rule."},"relearn":"Not sharing photos helps, but staying alert covers more risks.","persona":"any","source":"false-safety myth"},
  {"id":"fw-1101","cat":"myths-busted","type":"strike-rewrite","hook":"\"A 'modelling scout' DMing me is a real opportunity, not a trick.\"","myth":{"un":"A modelling scout DM'd me; this is a genuine big break.","re":"Fake 'casting' that asks for private photos or money is a known scam; a real agency never works that way.","why":"Flattery plus a photo or fee request is the tell."},"relearn":"A DM 'scout' asking for private photos or money is a scam.","persona":"Riya","source":"casting-scam myth"},
  {"id":"fw-1102","cat":"myths-busted","type":"strike-rewrite","hook":"\"Keeping a secret online relationship safe means handling it alone.\"","myth":{"un":"To protect my secret online relationship, I must handle problems alone.","re":"Secrecy is what an abuser wants; you can still tell a trusted adult if it turns scary.","why":"Being alone with a problem is what makes it dangerous."},"relearn":"You can keep a relationship private and still get help if it turns scary.","persona":"Riya","source":"secrecy myth"},
  {"id":"fw-1103","cat":"myths-busted","type":"sort","hook":"Sort each line: an online myth to bust, or a safe truth?","items":[{"id":"a","text":"\"A blue tick means they're safe\""},{"id":"b","text":"\"Behaviour, not badges, shows who's safe\""},{"id":"c","text":"\"Paying once makes it stop\""},{"id":"d","text":"\"Don't pay, save proof, get help\""},{"id":"e","text":"\"Being tricked is your fault\""},{"id":"f","text":"\"The manipulator is to blame\""}],"bins":[{"id":"myth","label":"Myth to bust","valence":"neg"},{"id":"truth","label":"Safe truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"Ticks and 'paying works' are myths; truth is help exists and it's not your fault.","persona":"any","source":"myths"},
  {"id":"fw-1104","cat":"myths-busted","type":"sort","hook":"Sort: a comforting lie a blackmailer wants you to believe, or the truth?","items":[{"id":"a","text":"\"Tell anyone and it gets worse\""},{"id":"b","text":"\"A trusted adult is your way out\""},{"id":"c","text":"\"Send one more and I'll stop\""},{"id":"d","text":"\"Sending more never ends it\""},{"id":"e","text":"\"You'll be in trouble too\""},{"id":"f","text":"\"You're a protected victim\""}],"bins":[{"id":"lie","label":"The abuser's lie","valence":"neg"},{"id":"truth","label":"The truth","valence":"pos"}],"key":{"a":"lie","b":"truth","c":"lie","d":"truth","e":"lie","f":"truth"},"relearn":"'Telling makes it worse / send one more / you'll be in trouble' are the abuser's lies.","persona":"any","source":"no blame"},
  {"id":"fw-1105","cat":"myths-busted","type":"sort","hook":"Sort: a sign someone's faking it, or a sign they're genuinely safe?","items":[{"id":"a","text":"Brand-new account, no real history"},{"id":"b","text":"Known to you in real life"},{"id":"c","text":"Refuses any live video, ever"},{"id":"d","text":"Fine with you telling your parents"},{"id":"e","text":"Rushes a 'special bond' in a day"},{"id":"f","text":"Gets to know you slowly, in the open"}],"bins":[{"id":"fake","label":"Likely faking","valence":"neg"},{"id":"safe","label":"More likely safe","valence":"pos"}],"key":{"a":"fake","b":"safe","c":"fake","d":"safe","e":"fake","f":"safe"},"relearn":"New accounts, no-video and rushed bonds are fake tells; open and known is safer.","persona":"any","source":"fake vs real"},
  {"id":"fw-1106","cat":"myths-busted","type":"sort","hook":"Sort: keeps you unsafe (a myth), or keeps you safe (a truth)?","items":[{"id":"a","text":"\"Cropping my face makes a pic safe\""},{"id":"b","text":"\"Backgrounds still identify me\""},{"id":"c","text":"\"Vanishing chats can't be saved\""},{"id":"d","text":"\"Screenshots beat vanishing\""},{"id":"e","text":"\"Private means no one can reshare\""},{"id":"f","text":"\"Followers can still pass it on\""}],"bins":[{"id":"myth","label":"Unsafe myth","valence":"neg"},{"id":"truth","label":"Safe truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"Cropping, vanishing and 'private' aren't guarantees; assume things can be saved and reshared.","persona":"any","source":"footprint myths"},
  {"id":"fw-1107","cat":"myths-busted","type":"sort","hook":"Sort each belief: a myth that traps you, or a truth that frees you?","items":[{"id":"a","text":"\"Only careless people get caught out\""},{"id":"b","text":"\"Careful people are targeted too\""},{"id":"c","text":"\"Boys don't get sextorted\""},{"id":"d","text":"\"Everyone can be targeted\""},{"id":"e","text":"\"If it happened, my life is over\""},{"id":"f","text":"\"There's a clear way through\""}],"bins":[{"id":"myth","label":"Traps you","valence":"neg"},{"id":"truth","label":"Frees you","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"'Only careless / boys are safe / life is over' trap you; the truths free you to get help.","persona":"any","source":"myths"},
  {"id":"fw-1108","cat":"myths-busted","type":"sort","hook":"Sort: a real opportunity, or a dressed-up trick?","items":[{"id":"a","text":"A scout DM asking for private photos"},{"id":"b","text":"A school-run audition with your parents"},{"id":"c","text":"\"Pay a fee to unlock your big break\""},{"id":"d","text":"An offer you can check with an adult"},{"id":"e","text":"\"Keep this casting just between us\""},{"id":"f","text":"A public, verifiable agency process"}],"bins":[{"id":"trick","label":"A trick","valence":"neg"},{"id":"real","label":"Could be real","valence":"pos"}],"key":{"a":"trick","b":"real","c":"trick","d":"real","e":"trick","f":"real"},"relearn":"Private-photo, pay-a-fee and 'keep it secret' offers are tricks, not opportunities.","persona":"Riya","source":"scam myths"},
  {"id":"fw-1109","cat":"myths-busted","type":"sort","hook":"Sort: something a groomer says, or something a real friend says?","items":[{"id":"a","text":"\"Don't tell your parents about me\""},{"id":"b","text":"\"You can tell your parents about me\""},{"id":"c","text":"\"Prove you trust me, send a pic\""},{"id":"d","text":"\"No worries if you'd rather not\""},{"id":"e","text":"\"Let's move to a secret app\""},{"id":"f","text":"\"Happy to chat right here\""}],"bins":[{"id":"groomer","label":"A groomer","valence":"neg"},{"id":"friend","label":"A real friend","valence":"pos"}],"key":{"a":"groomer","b":"friend","c":"groomer","d":"friend","e":"groomer","f":"friend"},"relearn":"Secrecy, 'prove it with a pic' and 'move to a secret app' are groomer lines.","persona":"any","source":"grooming vs friendship"},
  {"id":"fw-1110","cat":"myths-busted","type":"sort","hook":"Sort: handles a threat the right way, or falls for the myth?","items":[{"id":"a","text":"Pay quickly so it ends"},{"id":"b","text":"Don't pay; save the proof"},{"id":"c","text":"Delete everything in a panic"},{"id":"d","text":"Block, but keep the evidence"},{"id":"e","text":"Handle it alone in secret"},{"id":"f","text":"Tell a trusted adult"}],"bins":[{"id":"myth","label":"Falls for the myth","valence":"neg"},{"id":"plan","label":"The right move","valence":"pos"}],"key":{"a":"myth","b":"plan","c":"myth","d":"plan","e":"myth","f":"plan"},"relearn":"Pay / delete / go-it-alone are myths; don't pay, keep proof, tell an adult.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1111","cat":"myths-busted","type":"sort","hook":"Sort: a myth that keeps teens silent, or a truth that helps them speak?","items":[{"id":"a","text":"\"It's too small to bother anyone\""},{"id":"b","text":"\"When unsure, tell someone anyway\""},{"id":"c","text":"\"They'll think less of me\""},{"id":"d","text":"\"You won't be judged for asking\""},{"id":"e","text":"\"I must fix this myself\""},{"id":"f","text":"\"You needn't handle it alone\""}],"bins":[{"id":"silent","label":"Keeps you silent","valence":"neg"},{"id":"speak","label":"Helps you speak","valence":"pos"}],"key":{"a":"silent","b":"speak","c":"silent","d":"speak","e":"silent","f":"speak"},"relearn":"'Too small / they'll judge / fix it alone' keep you silent; the truths help you speak.","persona":"any","source":"silence myths"},
  {"id":"fw-1112","cat":"myths-busted","type":"sort","hook":"Sort: a myth about who gets targeted, or the real picture?","items":[{"id":"a","text":"\"Only naive younger kids get groomed\""},{"id":"b","text":"\"Teens are targeted a lot\""},{"id":"c","text":"\"Popular, confident teens are immune\""},{"id":"d","text":"\"Anyone can be a target\""},{"id":"e","text":"\"It can't happen to me\""},{"id":"f","text":"\"A plan keeps anyone safer\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"real","label":"The real picture","valence":"pos"}],"key":{"a":"myth","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"'Only younger kids / popular teens are immune / not me' are myths; anyone can be targeted.","persona":"any","source":"targeting myths"},
  {"id":"fw-1113","cat":"myths-busted","type":"reflect","hook":"Lensy: which busted myth surprised you the most?","prompt":"Pick one.","options":["Nice doesn't mean safe","Vanishing chats can be saved","Paying invites more"],"affirm":"Noticing what surprised you is how a myth loses its grip on you.","relearn":"Spotting the myth that fooled you is how you stop it fooling you again.","persona":"any","source":"reflection"},
  {"id":"fw-1114","cat":"myths-busted","type":"reflect","hook":"Lensy: which truth would you most want a younger cousin to hear?","prompt":"Pick one.","options":["It's never your fault","Don't pay, get help","Tell a trusted adult"],"affirm":"Passing on one clear truth like that can genuinely keep someone safer.","relearn":"Sharing a clear safety truth helps protect the people you care about.","persona":"any","source":"agency"},
  {"id":"fw-1115","cat":"myths-busted","type":"reflect","hook":"Lensy: 'I should've known better' is a story shame tells. Want to rewrite it?","prompt":"What do you think?","options":["Yes","A manipulator engineered this, not me","Rewriting it"],"affirm":"Naming the manipulation moves the weight off you and onto where it belongs.","relearn":"Seeing the tactic for what it was is what lets someone stop carrying the shame.","persona":"any","source":"no blame"},
  {"id":"fw-1116","cat":"myths-busted","type":"reflect","hook":"Lensy: now you know the playbook, do you feel harder to fool online?","prompt":"What do you think?","options":["Yes","Much harder","I see the tricks now"],"affirm":"Knowing the tricks is exactly what makes you hard to trick.","relearn":"Knowing the common myths and tactics makes you much harder to fool.","persona":"any","source":"empowerment"},
  {"id":"fw-1117","cat":"myths-busted","type":"reflect","hook":"Lensy: which myth do you most want banished from your group chat?","prompt":"Pick one.","options":["\"Everyone sexts\"","\"Paying makes it stop\"","\"Telling makes it worse\""],"affirm":"Calling out a myth where your friends can hear it protects all of you.","relearn":"Busting a myth out loud with friends keeps the whole group safer.","persona":"any","source":"agency"},
  {"id":"fw-1118","cat":"myths-busted","type":"reflect","hook":"Lensy: if a friend believed 'I'd never fall for a fake', what would you gently say?","prompt":"Pick what feels right.","options":["\"Anyone can be fooled\"","\"Let's stay private anyway\"","\"It's not weak to be careful\""],"affirm":"Any of those gently lowers the over-confidence that fakes rely on.","relearn":"Reminding a friend that anyone can be fooled keeps them careful.","persona":"any","source":"peer support"},
  {"id":"fw-1119","cat":"myths-busted","type":"reflect","hook":"Lensy: which 'truth' feels most worth remembering when things go wrong?","prompt":"Pick your anchor.","options":["Don't panic, there's a plan","It's not my fault","I'm not alone"],"affirm":"Holding one calm truth is often what makes the next step possible.","relearn":"One calm truth to hold onto is what makes the next safe step possible.","persona":"any","source":"consolidation"},
  {"id":"fw-1120","cat":"myths-busted","type":"reflect","hook":"Lensy: a blackmailer's whole power is in lies. Which lie do you most want to refuse?","prompt":"Pick one.","options":["\"No one can help you\"","\"It's your fault\"","\"Paying ends it\""],"affirm":"Refusing the lie is the moment their power over you starts to fade.","relearn":"Refusing a blackmailer's lie is where their power over you breaks.","persona":"any","source":"no blame"},
  {"id":"fw-1121","cat":"myths-busted","type":"reflect","hook":"Lensy: which myth used to feel true to you, but doesn't anymore?","prompt":"Think of one.","options":["\"Nice means safe\"","\"Deleting makes it gone\"","\"I'm too smart to be tricked\""],"affirm":"Watching a belief change is proof you're seeing more clearly now.","relearn":"Noticing a belief you've outgrown is a sign you're seeing clearly.","persona":"any","source":"reflection"},
  {"id":"fw-1122","cat":"myths-busted","type":"reflect","hook":"Lensy: 'reporting does nothing' stops a lot of people. Where do you land now?","prompt":"What do you think?","options":["Reporting helps","It's worth doing","It stops them hurting others"],"affirm":"Believing reporting matters is part of what makes it work.","relearn":"Trusting that reporting helps is part of what makes speaking up worth it.","persona":"Counsellor","source":"reporting"},
  {"id":"fw-1123","cat":"myths-busted","type":"reflect","hook":"Lensy: which truth would make you brave enough to tell an adult fast?","prompt":"Pick one.","options":["\"I won't be in trouble\"","\"It's not my fault\"","\"They're here to help\""],"affirm":"Holding that truth close is what shrinks the fear of telling.","relearn":"The truth that you won't be in trouble is what makes telling feel possible.","persona":"any","source":"finding help"},
  {"id":"fw-1124","cat":"myths-busted","type":"reflect","hook":"Lensy: of all the busted myths, which is your top 'spread this' message?","prompt":"Pick your motto.","options":["Nice isn't proof of safe","Don't pay, get help","Being tricked isn't your fault"],"affirm":"That's a message worth saying out loud, it could reach someone who needs it.","relearn":"Choosing one truth to spread is how a busted myth protects others too.","persona":"any","source":"consolidation"},
  {"id":"fw-1125","cat":"myths-busted","type":"reflect","hook":"Lensy: does knowing these myths make the internet feel scarier, or more manageable?","prompt":"What do you think?","options":["More manageable","I feel in control","Alert, not scared"],"affirm":"That's the goal, knowing the tricks should leave you steady, not frightened.","relearn":"Knowing the myths is meant to leave you alert and in control, not scared.","persona":"any","source":"empowerment"},
  {"id":"fw-1126","cat":"myths-busted","type":"reflect","hook":"Lensy: which busted myth would you put on a poster for your school?","prompt":"Pick one.","options":["\"Being tricked isn't your fault\"","\"You're a protected victim\"","\"There's always a way through\""],"affirm":"That message on a wall could be the thing that reaches a quiet kid.","relearn":"A clear, kind safety message in the open can reach someone who's silent.","persona":"any","source":"agency"},
  {"id":"fw-1127","cat":"myths-busted","type":"role-play","hook":"A friend insists, \"Everyone sends nudes, you're being dramatic.\"","setup":"Bust the myth, calmly. Say:","yourLine":[{"text":"\"Actually loads of us don't, and saying no isn't dramatic, it's just allowed.\"","best":true},{"text":"\"Yeah... I guess I'm overreacting.\""}],"relearn":"'Everyone does it' is pressure, not a fact; no is always allowed.","persona":"Riya","source":"pressure voice"},
  {"id":"fw-1128","cat":"myths-busted","type":"role-play","hook":"A friend says, \"If you just pay the guy, he'll delete it and stop.\"","setup":"Correct the myth and point to the plan. Say:","yourLine":[{"text":"\"Paying usually brings more demands. Don't pay, save the proof, and tell an adult.\"","best":true},{"text":"\"Maybe you're right, just pay and hope.\""}],"relearn":"Don't pay; paying invites more, the plan is save proof and tell an adult.","persona":"Veer","source":"sextortion voice"},
  {"id":"fw-1129","cat":"myths-busted","type":"role-play","hook":"A mate jokes, \"Boys can't get sextorted, that's a girl thing.\"","setup":"Set it straight, no drama. Say:","yourLine":[{"text":"\"Boys get targeted a lot, especially for money. We all need the same plan.\"","best":true},{"text":"\"Haha yeah, we're fine.\""}],"relearn":"Boys are heavily targeted; everyone needs the same calm plan.","persona":"Veer","source":"myth voice"},
  {"id":"fw-1130","cat":"myths-busted","type":"role-play","hook":"A friend blames themselves: \"I was so stupid to get catfished.\"","setup":"Lift the self-blame. Say:","yourLine":[{"text":"\"You weren't stupid, you were fooled by someone good at it. That's on them.\"","best":true},{"text":"\"Yeah, you really should've spotted that.\""}],"relearn":"Being catfished isn't stupidity; the deceiver is the one at fault.","persona":"any","source":"no-blame voice"},
  {"id":"fw-1131","cat":"myths-busted","type":"role-play","hook":"A friend says, \"Reporting it is pointless, nothing ever happens.\"","setup":"Push back gently. Say:","yourLine":[{"text":"\"Reports are taken seriously and it's how these guys get stopped. Let's do it together.\"","best":true},{"text":"\"Yeah, probably not worth it.\""}],"relearn":"Reporting is taken seriously and is how these crimes get stopped.","persona":"Counsellor","source":"reporting voice"},
  {"id":"fw-1132","cat":"myths-busted","type":"role-play","hook":"A friend says, \"They're really kind, so they must be safe.\"","setup":"Name the tactic, kindly. Say:","yourLine":[{"text":"\"Kindness can be a tactic, not proof. Let's watch what they actually do.\"","best":true},{"text":"\"True, nice people are always safe.\""}],"relearn":"Kindness can be a tactic; judge by behaviour, not first impressions.","persona":"any","source":"grooming voice"},
  {"id":"fw-1133","cat":"myths-busted","type":"role-play","hook":"A friend insists, \"On that app it disappears, so it's totally safe to send.\"","setup":"Bust the vanishing myth. Say:","yourLine":[{"text":"\"They can screenshot before it vanishes. Nothing you send is ever really gone.\"","best":true},{"text":"\"Oh okay, then it's fine.\""}],"relearn":"Disappearing messages can be screenshotted; nothing sent is truly gone.","persona":"any","source":"footprint voice"},
  {"id":"fw-1134","cat":"myths-busted","type":"role-play","hook":"A scared friend says, \"If I tell my mum, she'll just take my phone.\"","setup":"Reframe telling as the way out. Say:","yourLine":[{"text":"\"She'd want to help you, not punish you. You're the one being protected here.\"","best":true},{"text":"\"Yeah, better to keep quiet then.\""}],"relearn":"A trusted adult is there to protect you, not to punish you.","persona":"any","source":"telling voice"},
  {"id":"fw-1135","cat":"myths-busted","type":"match","hook":"Match each myth to the truth that busts it.","pairs":[{"left":"\"Nice means safe\"","right":"Kindness can be a tactic"},{"left":"\"Paying ends it\"","right":"Paying invites more"},{"left":"\"Deleting makes it gone\"","right":"Copies can survive"},{"left":"\"It's your fault\"","right":"The abuser is to blame"},{"left":"\"Telling makes it worse\"","right":"A trusted adult is the way out"}],"relearn":"Each common myth has a clear truth that busts it.","persona":"any","source":"myths"},
  {"id":"fw-1136","cat":"myths-busted","type":"match","hook":"Match the myth to why teens fall for it.","pairs":[{"left":"\"Everyone sexts\"","right":"Peer pressure as a 'fact'"},{"left":"\"I'd spot a fake\"","right":"Over-confidence"},{"left":"\"Vanishing chats are safe\"","right":"A false sense of security"},{"left":"\"My life is over\"","right":"Panic in the moment"},{"left":"\"Boys are immune\"","right":"Assuming it's not your problem"}],"relearn":"Myths stick because of pressure, over-confidence, panic and false safety.","persona":"any","source":"why myths stick"},
  {"id":"fw-1137","cat":"myths-busted","type":"match","hook":"Match a blackmailer's lie to the calm reply that beats it.","pairs":[{"left":"\"Pay or I post it\"","right":"Don't pay, save the proof"},{"left":"\"Send one more\"","right":"Sending more never ends it"},{"left":"\"No one will help you\"","right":"A trusted adult can help"},{"left":"\"You'll be in trouble\"","right":"You're a protected victim"},{"left":"\"Delete it all, hide\"","right":"Block, but keep the evidence"}],"relearn":"Every blackmail line has a calm, safe reply that beats it.","persona":"any","source":"sextortion replies"},
  {"id":"fw-1138","cat":"myths-busted","type":"match","hook":"Match the 'too good to be true' offer to its hidden trick.","pairs":[{"left":"\"You've won, just pay shipping\"","right":"A fee scam"},{"left":"\"Be our model, send photos\"","right":"A photo-harvesting scam"},{"left":"\"Free top-ups, keep it secret\"","right":"A grooming opener"},{"left":"\"I'm your age, trust me\"","right":"A faked-age claim"},{"left":"\"DM for a quick crypto profit\"","right":"A money scam"}],"relearn":"Flashy offers often hide a fee, a photo-grab, grooming or a money scam.","persona":"any","source":"scam tells"},
  {"id":"fw-1139","cat":"myths-busted","type":"match","hook":"Match the worry to the truth that answers it.","pairs":[{"left":"\"I should've known better\"","right":"Manipulators fool careful people"},{"left":"\"I'm completely alone\"","right":"A trusted adult can help"},{"left":"\"Nothing can be done\"","right":"It can be reported and stopped"},{"left":"\"This ruins my life\"","right":"There's a clear way through"},{"left":"\"I'll be in trouble\"","right":"You're the one being protected"}],"relearn":"Each fear has a true answer: not your fault, not alone, it can be stopped.","persona":"any","source":"no blame"},
  {"id":"fw-1140","cat":"myths-busted","type":"match","hook":"Match the safety habit to the myth it replaces.","pairs":[{"left":"Stay private with strangers","right":"\"I can always spot a fake\""},{"left":"Keep proof, don't delete","right":"\"Delete it to feel clean\""},{"left":"Tell a trusted adult","right":"\"Handle it alone\""},{"left":"Don't pay, get help","right":"\"Pay and it stops\""},{"left":"Watch actions, not vibes","right":"\"Nice means safe\""}],"relearn":"Good habits each replace a myth that used to feel safe.","persona":"any","source":"habits vs myths"},
  {"id":"fw-1141","cat":"myths-busted","type":"match","hook":"Match the myth to who most needs to hear it busted.","pairs":[{"left":"\"Boys don't get sextorted\"","right":"A boy who feels immune"},{"left":"\"Everyone sexts\"","right":"A teen facing photo pressure"},{"left":"\"Telling makes it worse\"","right":"A scared kid staying silent"},{"left":"\"Nice means safe\"","right":"Someone charmed by a stranger"},{"left":"\"My life is over\"","right":"A teen frozen in panic"}],"relearn":"Each busted myth lands hardest with the person it traps.","persona":"any","source":"who needs it"},
  {"id":"fw-1142","cat":"myths-busted","type":"match","hook":"Match the calm truth to the moment it's needed.","pairs":[{"left":"Just got threatened","right":"Don't panic, there's a plan"},{"left":"Blaming yourself","right":"It's not your fault"},{"left":"Feeling alone","right":"A trusted adult can help"},{"left":"Tempted to pay","right":"Don't pay, save the proof"},{"left":"Scared to report","right":"You won't be in trouble"}],"relearn":"For every scary moment there's a calm truth that fits it.","persona":"any","source":"truths in the moment"},
  {"id":"fw-1143","cat":"myths-busted","type":"branch","hook":"A group chat is repeating, \"Sexting's normal, everyone does it.\" You...","options":[{"text":"Say plenty of people don't, and 'no' is always fine","consequence":"You break the pressure and others feel free to opt out too.","outcome":"truth","best":true},{"text":"Stay quiet so you fit in","consequence":"Silence lets the myth stand; naming the truth frees everyone."}],"debrief":"'Everyone does it' is pressure, not a fact; naming that protects the group.","relearn":"Plenty of teens don't sext; 'no' is always a fine answer.","persona":"Riya","source":"pressure myth"},
  {"id":"fw-1144","cat":"myths-busted","type":"branch","hook":"You're sure you'd never fall for a fake, so you start sharing freely. Then...","options":[{"text":"Catch yourself and stay private anyway","consequence":"You stay safe even from a really convincing fake.","outcome":"humble","best":true},{"text":"Trust your gut and overshare","consequence":"Good fakes fool confident people; staying private is the safer bet."}],"debrief":"Feeling un-foolable is exactly what a skilled fake relies on.","relearn":"No one spots every fake; staying private beats feeling un-foolable.","persona":"any","source":"overconfidence myth"},
  {"id":"fw-1145","cat":"myths-busted","type":"branch","hook":"A friend says paying the blackmailer 'just a little' will end it. You...","options":[{"text":"Tell them not to pay and to save proof and get help","consequence":"They avoid a trap that usually grows worse.","outcome":"plan","best":true},{"text":"Agree it's worth a try","consequence":"Paying usually brings more demands; the plan is don't pay and get help."}],"debrief":"A payment tells a blackmailer pressure works; don't pay, get help.","relearn":"Paying rarely ends blackmail and often invites more; get help instead.","persona":"Veer","source":"sextortion myth"},
  {"id":"fw-1146","cat":"myths-busted","type":"branch","hook":"You believe deleting the chat will make the whole problem vanish. You...","options":[{"text":"Block them but keep the messages as evidence","consequence":"You stop contact and keep what an adult needs to act.","outcome":"evidence","best":true},{"text":"Delete everything to feel clean","consequence":"Deleting loses the proof; block, but keep the evidence."}],"debrief":"Block to stop contact, but the messages are proof, don't delete them.","relearn":"Block the contact but keep the messages, they're evidence.","persona":"any","source":"evidence myth"},
  {"id":"fw-1147","cat":"myths-busted","type":"branch","hook":"You think telling an adult will only make things worse, so you nearly stay silent. You...","options":[{"text":"Tell one trusted adult anyway","consequence":"You're no longer alone and the help can start.","outcome":"told","best":true},{"text":"Keep it secret and cope alone","consequence":"Silence is the trap; a trusted adult is the way out."}],"debrief":"Telling a trusted adult is the exit, not the thing that makes it worse.","relearn":"Telling a trusted adult is the way out; you won't be in trouble.","persona":"any","source":"telling myth"},
  {"id":"fw-1148","cat":"myths-busted","type":"branch","hook":"A 'casting scout' DMs an amazing offer if you send private photos. You...","options":[{"text":"Treat it as a scam and check with a trusted adult","consequence":"You dodge a photo-harvesting trick.","outcome":"safe","best":true},{"text":"Send the photos for your big break","consequence":"Real agencies don't work via private-photo DMs; it's a scam."}],"debrief":"A 'scout' asking for private photos is a scam, not an opportunity.","relearn":"A DM scout asking for private photos is a scam; check with an adult.","persona":"Riya","source":"casting-scam myth"},
  {"id":"fw-1149","cat":"myths-busted","type":"branch","hook":"You feel this situation is 'too small' to be worth telling anyone. You...","options":[{"text":"Tell a trusted adult anyway and let them help judge","consequence":"You're guided instead of guessing alone.","outcome":"safe","best":true},{"text":"Wait until it's 'serious enough'","consequence":"You don't have to judge it alone; tell a trusted adult anyway."}],"debrief":"You never have to decide alone whether something counts as serious.","relearn":"If unsure it's serious enough, tell a trusted adult anyway.","persona":"any","source":"silence myth"},
  {"id":"fw-1150","cat":"myths-busted","type":"branch","hook":"You assume sextortion 'can't happen to me', so you skip having a plan. You...","options":[{"text":"Learn the calm plan now, just in case","consequence":"If anything ever happens, you already know the safe steps.","outcome":"ready","best":true},{"text":"Decide it's not your problem","consequence":"Anyone can be targeted; knowing the plan early keeps you safer."}],"debrief":"'It won't happen to me' is exactly the gap abusers look for.","relearn":"Anyone can be targeted; knowing the plan in advance keeps you safer.","persona":"Veer","source":"it-won't-happen myth"},
  {"id":"fw-1151","cat":"myths-busted","type":"spot","hook":"A teen's online-safety beliefs. Spot the two myths.","scene":[{"id":"a","text":"\"A blue tick means an account is safe\"","trick":true},{"id":"b","text":"\"People can fake their age and photos\"","trick":false},{"id":"c","text":"\"If they're nice, they're definitely safe\"","trick":true},{"id":"d","text":"\"Pressure to send a pic is a red flag\"","trick":false},{"id":"e","text":"\"Staying private with strangers is smart\"","trick":false}],"why":"A blue tick isn't proof, and 'nice means safe' is the grooming disguise.","relearn":"Ticks and kindness aren't proof of safety; judge by behaviour.","persona":"any","source":"belief check"},
  {"id":"fw-1152","cat":"myths-busted","type":"spot","hook":"A friend lists their sextortion 'plan'. Spot the two dangerous myths.","scene":[{"id":"a","text":"\"Pay them once and they'll stop\"","trick":true},{"id":"b","text":"\"Don't send more, it never ends it\"","trick":false},{"id":"c","text":"\"Block them but keep the messages\"","trick":false},{"id":"d","text":"\"Delete it all so no one sees\"","trick":true},{"id":"e","text":"\"Tell a trusted adult and report\"","trick":false}],"why":"Paying invites more, and deleting destroys the evidence an adult needs.","relearn":"Don't pay and don't delete; keep proof and tell a trusted adult.","persona":"any","source":"plan check"},
  {"id":"fw-1153","cat":"myths-busted","type":"spot","hook":"Beliefs about blame. Spot the two myths that keep victims silent.","scene":[{"id":"a","text":"\"If you got tricked, it's your fault\"","trick":true},{"id":"b","text":"\"Manipulators fool careful people too\"","trick":false},{"id":"c","text":"\"You'll be in trouble if you tell\"","trick":true},{"id":"d","text":"\"You're the victim, not the wrongdoer\"","trick":false},{"id":"e","text":"\"A trusted adult is there to help\"","trick":false}],"why":"'Your fault' and 'you'll be in trouble' are myths that trap victims in silence.","relearn":"Being tricked isn't your fault, and you won't be in trouble for telling.","persona":"any","source":"blame check"},
  {"id":"fw-1154","cat":"myths-busted","type":"spot","hook":"Why a teen shares photos freely. Spot the two false beliefs.","scene":[{"id":"a","text":"\"Cropping my face makes it anonymous\"","trick":true},{"id":"b","text":"\"Backgrounds and tags can identify me\"","trick":false},{"id":"c","text":"\"On a vanishing app nothing is saved\"","trick":true},{"id":"d","text":"\"Anyone can screenshot before it goes\"","trick":false},{"id":"e","text":"\"Once sent, I can't take it back\"","trick":false}],"why":"Cropping isn't anonymous, and vanishing chats can be screenshotted first.","relearn":"Cropping and vanishing apps aren't safe; anything sent can be kept.","persona":"any","source":"footprint check"},
  {"id":"fw-1155","cat":"myths-busted","type":"spot","hook":"A boy lists reasons he thinks he's safe. Spot the two risky myths.","scene":[{"id":"a","text":"\"Sextortion only happens to girls\"","trick":true},{"id":"b","text":"\"Teen boys are targeted a lot too\"","trick":false},{"id":"c","text":"\"I'm too smart to ever get caught out\"","trick":true},{"id":"d","text":"\"Anyone can be fooled by a good fake\"","trick":false},{"id":"e","text":"\"Everyone needs the same calm plan\"","trick":false}],"why":"'Only girls' and 'too smart to be caught' are exactly the gaps abusers exploit.","relearn":"Boys are targeted too, and over-confidence is what fakes rely on.","persona":"Veer","source":"who-is-safe check"},
  {"id":"fw-1156","cat":"myths-busted","type":"spot","hook":"A teen describes a 'great new online friend'. Spot the two grooming tells they're missing.","scene":[{"id":"a","text":"\"They want our chats kept secret\"","trick":true},{"id":"b","text":"\"They like the same games as me\"","trick":false},{"id":"c","text":"\"They sent gifts within a day\"","trick":true},{"id":"d","text":"\"They asked about my favourite music\"","trick":false},{"id":"e","text":"\"We chat in the main app, openly\"","trick":false}],"why":"Demanding secrecy and fast gifts are grooming openers, not signs of a real friend.","relearn":"Secrecy and quick gifts from a new contact are grooming tells.","persona":"any","source":"grooming check"},
  {"id":"fw-1157","cat":"myths-busted","type":"spot","hook":"A teen lists what they'd do if threatened. Spot the two moves that fall for a myth.","scene":[{"id":"a","text":"\"Handle it alone so no one finds out\"","trick":true},{"id":"b","text":"\"Tell a trusted adult straight away\"","trick":false},{"id":"c","text":"\"Send one more pic to make it stop\"","trick":true},{"id":"d","text":"\"Save screenshots as evidence\"","trick":false},{"id":"e","text":"\"Report it at cybercrime.gov.in\"","trick":false}],"why":"Going it alone and 'send one more' both feed the threat instead of ending it.","relearn":"Don't go it alone and don't send more; tell an adult and save proof.","persona":"any","source":"response check"},
  {"id":"fw-1158","cat":"myths-busted","type":"spot","hook":"A 'too good to be true' DM arrives. Spot the two scam tells.","scene":[{"id":"a","text":"\"Send private photos for a modelling deal\"","trick":true},{"id":"b","text":"\"You can verify us with a parent\"","trick":false},{"id":"c","text":"\"Pay a small fee to claim your prize\"","trick":true},{"id":"d","text":"\"Our process is public and checkable\"","trick":false},{"id":"e","text":"\"No rush, take your time to decide\"","trick":false}],"why":"Asking for private photos or an upfront fee are classic scam tells, not real offers.","relearn":"Private-photo and pay-a-fee 'offers' are scams; check with an adult.","persona":"Riya","source":"scam check"},
  {"id":"fw-1159","cat":"myths-busted","type":"sort","hook":"Sort: a myth about what 'proves' who someone is, or the real test?","items":[{"id":"a","text":"\"A profile photo proves it's them\""},{"id":"b","text":"\"Known to you offline is real proof\""},{"id":"c","text":"\"A blue tick means it's genuine\""},{"id":"d","text":"\"Consistent behaviour over time shows it\""},{"id":"e","text":"\"A confident story proves identity\""},{"id":"f","text":"\"Vouched for by people you trust offline\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"real","label":"Real proof","valence":"pos"}],"key":{"a":"myth","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"Photos, ticks and a smooth story prove nothing; time and known-offline do.","persona":"any","source":"identity myths"},
  {"id":"fw-1160","cat":"myths-busted","type":"sort","hook":"Sort: a password myth, or a habit that protects you?","items":[{"id":"a","text":"\"Sharing it with my partner is trust\""},{"id":"b","text":"\"Keeping it to yourself is safest\""},{"id":"c","text":"\"One password for everything is fine\""},{"id":"d","text":"\"Two-factor adds a real extra lock\""},{"id":"e","text":"\"A birthday makes an easy password\""},{"id":"f","text":"\"A long, unique passcode is stronger\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"safe","label":"Protects you","valence":"pos"}],"key":{"a":"myth","b":"safe","c":"myth","d":"safe","e":"myth","f":"safe"},"relearn":"Sharing, reusing and birthday passwords are myths; long and two-factor protect you.","persona":"any","source":"password myths"},
  {"id":"fw-1161","cat":"myths-busted","type":"sort","hook":"Sort: a myth about reporting in India, or the truth?","items":[{"id":"a","text":"\"Reporting just goes into a void\""},{"id":"b","text":"\"Reports are routed for action\""},{"id":"c","text":"\"You must give your name to report\""},{"id":"d","text":"\"cybercrime.gov.in has an anonymous option\""},{"id":"e","text":"\"Under-18s get in trouble for reporting\""},{"id":"f","text":"\"A minor is a protected victim\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"truth","label":"The truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"Reporting is acted on, can be anonymous, and a minor is a protected victim.","persona":"Counsellor","source":"reporting myths"},
  {"id":"fw-1162","cat":"myths-busted","type":"sort","hook":"Sort: a myth about consent and pressure, or a boundary truth?","items":[{"id":"a","text":"\"If they ask twice, I owe them a yes\""},{"id":"b","text":"\"'No' is a complete answer\""},{"id":"c","text":"\"Saying no will make me look cold\""},{"id":"d","text":"\"Not wanting to is reason enough\""},{"id":"e","text":"\"Real love means proving it with pics\""},{"id":"f","text":"\"Real care respects your no\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"truth","label":"Boundary truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"You never owe a yes; 'no' is complete and real care respects it.","persona":"Riya","source":"consent myths"},
  {"id":"fw-1163","cat":"myths-busted","type":"sort","hook":"Sort: a myth about helping a friend, or the right move?","items":[{"id":"a","text":"\"Keep their secret no matter what\""},{"id":"b","text":"\"Help them tell a trusted adult\""},{"id":"c","text":"\"Tell them they should've known better\""},{"id":"d","text":"\"Remind them it's not their fault\""},{"id":"e","text":"\"Stay out of it, it's their problem\""},{"id":"f","text":"\"Offer to sit with them and report\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"right","label":"The right move","valence":"pos"}],"key":{"a":"myth","b":"right","c":"myth","d":"right","e":"myth","f":"right"},"relearn":"Don't keep a dangerous secret or blame them; help them tell an adult.","persona":"any","source":"helping myths"},
  {"id":"fw-1164","cat":"myths-busted","type":"sort","hook":"Sort: a myth about your digital footprint, or how it really works?","items":[{"id":"a","text":"\"Deleting a post erases it everywhere\""},{"id":"b","text":"\"Saved copies can outlast deletion\""},{"id":"c","text":"\"Old posts never resurface\""},{"id":"d","text":"\"Posts can come back years later\""},{"id":"e","text":"\"A finsta is totally untraceable\""},{"id":"f","text":"\"Even 'secret' accounts leave traces\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"real","label":"How it works","valence":"pos"}],"key":{"a":"myth","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"Deleting isn't erasing, old posts resurface, and 'secret' accounts still leave traces.","persona":"any","source":"footprint myths"},
  {"id":"fw-1165","cat":"myths-busted","type":"sort","hook":"Sort: a myth that fuels panic, or a calm truth to hold?","items":[{"id":"a","text":"\"My life is ruined forever\""},{"id":"b","text":"\"This is survivable with help\""},{"id":"c","text":"\"I have to fix it this second, alone\""},{"id":"d","text":"\"I can pause and get an adult\""},{"id":"e","text":"\"Everyone will find out instantly\""},{"id":"f","text":"\"There's a clear, calm plan\""}],"bins":[{"id":"panic","label":"Fuels panic","valence":"neg"},{"id":"calm","label":"A calm truth","valence":"pos"}],"key":{"a":"panic","b":"calm","c":"panic","d":"calm","e":"panic","f":"calm"},"relearn":"'Life is ruined / fix it alone now' fuel panic; you can pause and follow the plan.","persona":"any","source":"panic myths"},
  {"id":"fw-1166","cat":"myths-busted","type":"sort","hook":"Sort: a myth about who's safe online, or the real picture?","items":[{"id":"a","text":"\"My online 'best friend' can't be fake\""},{"id":"b","text":"\"Even a close online friend can be fake\""},{"id":"c","text":"\"Strangers in my game are harmless\""},{"id":"d","text":"\"Game chats can hide groomers too\""},{"id":"e","text":"\"A long chat history proves it's safe\""},{"id":"f","text":"\"Time chatting doesn't prove safety\""}],"bins":[{"id":"myth","label":"A myth","valence":"neg"},{"id":"real","label":"The real picture","valence":"pos"}],"key":{"a":"myth","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"Close online friends and long chats can still hide a fake; watch actions.","persona":"any","source":"who-is-safe myths"},
  {"id":"fw-1170","cat":"sextortion-plan","type":"branch","hook":"A stranger you flirted with online now demands money or they post your photo.","options":[{"text":"Don't pay. Save the chat, block, and tell a trusted adult.","consequence":"You take their power away and get help.","best":true},{"text":"Send the money to make it stop.","consequence":"Paying rarely stops it and often invites more."}],"debrief":"Paying feeds the threat; saving evidence and telling an adult ends it.","relearn":"Don't pay; save evidence and tell a trusted adult.","persona":"Veer","source":"sextortion response (verified)"},
  {"id":"fw-1171","cat":"sextortion-plan","type":"branch","hook":"The blackmailer says 'pay in crypto and I'll delete everything'.","options":[{"text":"Refuse to pay and report at cybercrime.gov.in or 1930.","consequence":"Reporting starts the real way out, not their fake promise.","best":true},{"text":"Buy the crypto and pay them quietly.","consequence":"A 'I'll delete it' promise from a blackmailer is never kept."}],"debrief":"No payment, crypto or otherwise, ends this; reporting does.","relearn":"A blackmailer's 'I'll delete it if you pay' is a lie; report instead.","persona":"any","source":"sextortion response (verified)"},
  {"id":"fw-1172","cat":"sextortion-plan","type":"branch","hook":"They threaten to send your photo to your school group unless you reply with more.","options":[{"text":"Don't send more. Screenshot it and tell an adult today.","consequence":"You keep proof and bring in help.","best":true},{"text":"Send another photo to spare your school group.","consequence":"More images never end it; they deepen the trap."}],"debrief":"Sending more never buys safety; saving proof and telling does.","relearn":"Sending more never ends it; save proof and tell an adult.","persona":"any","source":"sextortion response"},
  {"id":"fw-1173","cat":"sextortion-plan","type":"branch","hook":"A threat lands at 1 a.m. and your first thought is to delete the whole chat.","options":[{"text":"Block them but keep the messages, they're evidence.","consequence":"You stop contact while saving the proof.","best":true},{"text":"Delete the chat and the app so it's gone.","consequence":"Deleting wipes the proof a report needs."}],"debrief":"Block to stop contact, but never delete, the messages are evidence.","relearn":"Block, but don't delete, the messages are proof.","persona":"any","source":"sextortion / evidence (verified)"},
  {"id":"fw-1174","cat":"sextortion-plan","type":"branch","hook":"You froze for days. Now you wonder if it's too late to tell anyone.","options":[{"text":"Tell a trusted adult now, it's never too late.","consequence":"Help still works; telling sooner ends it faster.","best":true},{"text":"Stay quiet since you already waited.","consequence":"Waiting changes nothing about your right to help."}],"debrief":"There's no deadline on asking for help; telling now still ends it.","relearn":"It's never too late to tell a trusted adult.","persona":"Counsellor","source":"finding help"},
  {"id":"fw-1175","cat":"sextortion-plan","type":"branch","hook":"The person says 'tell anyone and I'll post it instantly'.","options":[{"text":"Tell a trusted adult anyway, that threat is how they keep you silent.","consequence":"Telling breaks their main weapon: your silence.","best":true},{"text":"Stay silent so they don't post it.","consequence":"Silence is exactly what traps a victim; telling is the way out."}],"debrief":"'Tell no one' is the blackmailer's trap; telling an adult ends it.","relearn":"'Tell no one or I post it' is a trap; tell a trusted adult.","persona":"any","source":"sextortion / India shame factor"},
  {"id":"fw-1176","cat":"sextortion-plan","type":"branch","hook":"You're a boy and think 'this sextortion stuff only happens to girls'.","options":[{"text":"Take the threat seriously, boys are targeted too.","consequence":"You get help instead of hiding.","best":true},{"text":"Brush it off as something harmless.","consequence":"Boys are most financial-sextortion targets; the danger is real."}],"debrief":"Sextortion hits boys hard too; everyone needs the plan.","relearn":"Boys are heavily targeted; take the threat seriously.","persona":"Veer","source":"sextortion targeting (verified)"},
  {"id":"fw-1177","cat":"sextortion-plan","type":"branch","hook":"A 'modelling agency' DM says send a private photo to 'verify' you, or lose the offer.","options":[{"text":"Don't send it; a real offer never demands a private photo.","consequence":"You dodge a classic trap.","best":true},{"text":"Send the photo to keep the offer.","consequence":"A 'verify with a private photo' demand is a setup."}],"debrief":"No genuine offer needs a private photo; that demand is the red flag.","relearn":"An offer demanding a private photo is a trap; refuse.","persona":"Riya","source":"sextortion grooming"},
  {"id":"fw-1178","cat":"sextortion-plan","type":"branch","hook":"After you paid once, they're now demanding double.","options":[{"text":"Stop paying immediately, save everything, and report at 1930.","consequence":"Cutting off payment and reporting is how it actually ends.","best":true},{"text":"Pay the bigger amount to finally be free.","consequence":"Paying again confirms you'll comply; demands only grow."}],"debrief":"Paying once invites more; stopping and reporting is the exit.","relearn":"Once you've paid, stop, paying more only grows the demands; report.","persona":"any","source":"sextortion response (verified)"},
  {"id":"fw-1179","cat":"sextortion-plan","type":"branch","hook":"Your account was hacked and now your own photos are being used to threaten you.","options":[{"text":"Report it at cybercrime.gov.in and tell an adult.","consequence":"The crime gets reported and you aren't alone.","best":true},{"text":"Try to hack the account back and tell no one.","consequence":"Going alone leaves you exposed; reporting brings help."}],"debrief":"A hack used to threaten you is a crime to report, not hide.","relearn":"If photos are stolen to threaten you, report it, you're the victim.","persona":"any","source":"cybercrime reporting (verified)"},
  {"id":"fw-1180","cat":"sextortion-plan","type":"branch","hook":"They claim 'I'll only stop if you video-call and prove it's you'.","options":[{"text":"Don't call. Block, save the threat, tell an adult.","consequence":"You refuse the bait and bring in help.","best":true},{"text":"Do the video call to make them go away.","consequence":"A 'prove it on call' demand is a fresh trap."}],"debrief":"A 'do this one thing and I'll stop' demand is always a new trap.","relearn":"A blackmailer's 'just do this and I'll stop' is a trap; don't comply.","persona":"any","source":"sextortion response"},
  {"id":"fw-1181","cat":"sextortion-plan","type":"branch","hook":"A junior at school says an older account is threatening to leak their photo.","options":[{"text":"Help them screenshot, block, and tell an adult now.","consequence":"They get protection fast, not alone.","best":true},{"text":"Tell them to handle it quietly themselves.","consequence":"A younger child facing this needs an adult's help."}],"debrief":"A younger kid in this danger needs you to help them reach an adult.","relearn":"Help a younger child screenshot, block, and tell an adult.","persona":"any","source":"safeguarding"},
  {"id":"fw-1182","cat":"sextortion-plan","type":"branch","hook":"The threat email says 'I have your contacts and I'll message them all'.","options":[{"text":"Don't reply. Save the email and report at cybercrime.gov.in.","consequence":"Reporting beats their scare tactic.","best":true},{"text":"Reply begging them not to message your contacts.","consequence":"Pleading just shows the threat is working."}],"debrief":"Scaring you with your contacts is pressure; report, don't reply.","relearn":"'I'll message your contacts' is a scare tactic; report, don't reply.","persona":"any","source":"sextortion response (verified)"},
  {"id":"fw-1183","cat":"sextortion-plan","type":"branch","hook":"You want to tell your elder sister but fear she'll be disappointed in you.","options":[{"text":"Tell her, that fear is exactly what traps victims.","consequence":"She becomes support; the secret stops weighing on you.","best":true},{"text":"Hide it to avoid letting her down.","consequence":"Fear of letting family down is the trap; telling ends it."}],"debrief":"Worrying about family's reaction keeps victims silent; tell anyway.","relearn":"Fear of disappointing family traps you; tell anyway.","persona":"Riya","source":"India shame factor"},
  {"id":"fw-1184","cat":"sextortion-plan","type":"branch","hook":"A gaming friend you've never met threatens to leak a chat unless you pay in game credits.","options":[{"text":"Stop, save the chat, block, and tell an adult.","consequence":"You treat it like a crime and get help.","best":true},{"text":"Send the game credits to keep it private.","consequence":"Paying in credits is still paying; it never ends it."}],"debrief":"Paying in any currency, money or credits, never ends it.","relearn":"Paying in game credits is still paying; don't, save and tell.","persona":"Veer","source":"sextortion response"},
  {"id":"fw-1185","cat":"sextortion-plan","type":"branch","hook":"Mid-threat, you start thinking your life is basically over.","options":[{"text":"Pause: there's a clear plan and people whose job is to help.","consequence":"You breathe, follow the steps, and reach real support.","best":true},{"text":"Spiral and decide nothing can be done.","consequence":"It feels huge, but there is a calm, clear way through this."}],"debrief":"It feels like the end, but there's a plan and people who help.","relearn":"Sextortion feels huge, but there's a clear plan and real help.","persona":"any","source":"reassurance / no-panic"},
  {"id":"fw-1186","cat":"sextortion-plan","type":"branch","hook":"The blackmailer keeps messaging from new accounts after you blocked one.","options":[{"text":"Keep blocking and save each new threat.","consequence":"Each saved threat strengthens your report.","best":true},{"text":"Reply to the new accounts to tell them to stop.","consequence":"Replying just confirms they reached you."}],"debrief":"New accounts are the same crime; block, save, report, don't engage.","relearn":"If they return on new accounts, keep blocking and saving, don't reply.","persona":"any","source":"sextortion response"},
  {"id":"fw-1187","cat":"sextortion-plan","type":"branch","hook":"You're scared the police will judge you for the photo that exists.","options":[{"text":"Report anyway, under the law a minor is a protected victim.","consequence":"You get protection, not blame.","best":true},{"text":"Avoid reporting so no one judges you.","consequence":"The law treats you as a victim, not in trouble."}],"debrief":"Reporting is safe; a minor here is a protected victim, never blamed.","relearn":"A minor in a sextortion case is a protected victim; reporting is safe.","persona":"Counsellor","source":"POCSO (verified)"},
  {"id":"fw-1188","cat":"sextortion-plan","type":"branch","hook":"A 'friend of a friend' says pay them or they show the photo to your crush.","options":[{"text":"Don't pay. Save it, block, and tell a trusted adult.","consequence":"You take away their leverage and get help.","best":true},{"text":"Pay so your crush never sees it.","consequence":"Paying to protect a reputation just hands them ongoing control."}],"debrief":"Paying to 'protect your image' only deepens the trap; don't.","relearn":"Don't pay to hide it from someone; save, block, and tell an adult.","persona":"Riya","source":"sextortion response"},
  {"id":"fw-1189","cat":"sextortion-plan","type":"branch","hook":"You have no private photos but they claim they 'edited' one of you.","options":[{"text":"Don't pay a fake; save the threat and report at 1930.","consequence":"You treat the bluff as the crime it is.","best":true},{"text":"Pay because the edit looks convincing.","consequence":"A faked or edited image is still extortion."}],"debrief":"Faked images are still extortion; don't pay, save and report.","relearn":"An edited or fake image threat is still extortion; don't pay, report.","persona":"any","source":"sextortion / deepfake (verified)"},
  {"id":"fw-1190","cat":"sextortion-plan","type":"branch","hook":"You want to start the plan but don't know the very first step.","options":[{"text":"Stop replying first, then save evidence, then tell an adult.","consequence":"You move calmly instead of freezing.","best":true},{"text":"Keep chatting with them while you decide.","consequence":"Staying in the chat keeps the pressure on."}],"debrief":"First stop replying, then save proof, then tell, that's the order.","relearn":"First step: stop replying. Then save evidence and tell an adult.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1191","cat":"sextortion-plan","type":"branch","hook":"A counsellor offers to sit with you while you report. You feel awkward accepting.","options":[{"text":"Accept the help, reporting with support is easier.","consequence":"You aren't alone for the hardest part.","best":true},{"text":"Decline and plan to report alone 'later'.","consequence":"Going alone often means it never happens."}],"debrief":"Help with reporting is for using; accepting it gets it done.","relearn":"Let a trusted adult help you report; support makes it doable.","persona":"Counsellor","source":"reporting / support"},
  {"id":"fw-1192","cat":"sextortion-plan","type":"branch","hook":"They say 'just keep this between us and it'll all be fine'.","options":[{"text":"Break the secret, tell a trusted adult, that's how it ends.","consequence":"Telling removes the secrecy the threat depends on.","best":true},{"text":"Keep it 'between us' as they ask.","consequence":"Secrecy is the blackmailer's tool; their 'fine' never comes."}],"debrief":"'Keep it between us' protects them, not you; tell an adult.","relearn":"'Keep it between us' is the blackmailer's trap; tell a trusted adult.","persona":"any","source":"sextortion / secrecy"},
  {"id":"fw-1193","cat":"sextortion-plan","type":"branch","hook":"Your friend already paid and is now too ashamed to tell anyone.","options":[{"text":"Reassure them it's not their fault and help them tell an adult.","consequence":"They feel safe enough to get help.","best":true},{"text":"Agree it's embarrassing and let them hide it.","consequence":"Letting shame win keeps them trapped."}],"debrief":"Shame keeps a paid victim stuck; no-blame support gets them help.","relearn":"If a friend paid and feels ashamed, reassure them and help them tell.","persona":"any","source":"no blame / support"},
  {"id":"fw-1194","cat":"sextortion-plan","type":"role-play","hook":"You're telling a teacher you trust that you're being blackmailed online.","setup":"Say it plainly:","yourLine":[{"text":"\"Someone's threatening to share my photo. I'm scared and I need your help.\"","best":true},{"text":"Say nothing and hope it passes."}],"relearn":"Telling a teacher plainly, 'I need your help', is a brave, safe start.","persona":"any","source":"finding help voice"},
  {"id":"fw-1195","cat":"sextortion-plan","type":"role-play","hook":"A blackmailer is pressuring you to reply fast. Set the boundary in your head and out loud.","setup":"Tell yourself the truth:","yourLine":[{"text":"\"I don't owe them a reply. I'm stopping, saving this, and telling an adult.\"","best":true},{"text":"\"Maybe if I just answer once they'll calm down.\""}],"relearn":"You owe a blackmailer nothing; stop, save, and tell, no reply needed.","persona":"any","source":"sextortion plan voice"},
  {"id":"fw-1196","cat":"sextortion-plan","type":"role-play","hook":"Coach a younger cousin who just got a pay-or-I-post threat.","setup":"Give the calm plan:","yourLine":[{"text":"\"Don't pay and don't reply. Screenshot it, block them, and we'll tell your mum.\"","best":true},{"text":"\"Just give them what they want so it stops.\""}],"relearn":"The calm coaching plan: don't pay, don't reply, screenshot, block, tell.","persona":"any","source":"sextortion plan voice"},
  {"id":"fw-1197","cat":"sextortion-plan","type":"role-play","hook":"Your friend keeps saying 'but I sent it, so it's my fault'.","setup":"Take the blame off them:","yourLine":[{"text":"\"You were tricked. The person threatening you is the criminal, not you.\"","best":true},{"text":"\"Yeah, you shouldn't have sent it.\""}],"relearn":"Tell a victim clearly: you were tricked, the blackmailer is the criminal.","persona":"any","source":"no blame voice"},
  {"id":"fw-1198","cat":"sextortion-plan","type":"role-play","hook":"Help a friend ask their parent for help without freezing up.","setup":"Make it sayable:","yourLine":[{"text":"\"Mum, I'm in trouble online and I'm scared. Can you help me, I trust you.\"","best":true},{"text":"\"It's nothing, forget I said anything.\""}],"relearn":"A simple 'I'm scared, can you help, I trust you' opens the door to help.","persona":"any","source":"finding help voice"},
  {"id":"fw-1199","cat":"sextortion-plan","type":"role-play","hook":"You're ready to report and want to say the plan out loud first.","setup":"Name the route:","yourLine":[{"text":"\"We'll report at cybercrime.gov.in or call 1930, and I won't be in trouble.\"","best":true},{"text":"\"I'll just deal with it on my own somehow.\""}],"relearn":"Say it: report at cybercrime.gov.in or 1930, and you won't be in trouble.","persona":"Counsellor","source":"reporting voice (verified)"},
  {"id":"fw-1200","cat":"sextortion-plan","type":"role-play","hook":"A boy friend is too embarrassed to admit he's being sextorted.","setup":"Normalise getting help:","yourLine":[{"text":"\"This happens to loads of guys, mate. It's not weak to get help, let's go.\"","best":true},{"text":"\"You're overreacting, just ignore it.\""}],"relearn":"Tell a boy it's common and not weak to get help; then go together.","persona":"Veer","source":"no blame / boys voice"},
  {"id":"fw-1201","cat":"sextortion-plan","type":"role-play","hook":"You need to refuse the blackmailer's 'one more photo' demand in words.","setup":"Refuse flatly:","yourLine":[{"text":"\"No. I'm not sending anything else. I'm done talking to you.\"","best":true},{"text":"\"Okay, fine, just this one last time.\""}],"relearn":"A flat 'No, I'm not sending anything else' is the right line; then stop.","persona":"any","source":"sextortion plan voice"},
  {"id":"fw-1202","cat":"sextortion-plan","type":"role-play","hook":"Reassure a friend who fears their family will disown them if they tell.","setup":"Hold them steady:","yourLine":[{"text":"\"You're the victim here. A trusted adult will protect you, not blame you.\"","best":true},{"text":"\"Yeah, maybe just keep it hidden then.\""}],"relearn":"Remind a scared friend: you're the victim, a trusted adult protects you.","persona":"any","source":"India shame / support voice"},
  {"id":"fw-1203","cat":"sextortion-plan","type":"role-play","hook":"Walk a panicking friend back to calm so they can act.","setup":"Slow it down:","yourLine":[{"text":"\"Breathe. There's a plan: don't pay, save it, tell an adult. We do it together.\"","best":true},{"text":"\"Yeah, this is a total disaster, I don't know.\""}],"relearn":"Bring a panicking friend to a plan: don't pay, save, tell, together.","persona":"any","source":"reassurance voice"},
  {"id":"fw-1204","cat":"sextortion-plan","type":"role-play","hook":"You're calling Childline to ask what to do about a threat.","setup":"Open simply:","yourLine":[{"text":"\"Hi, I'm under 18 and someone's blackmailing me online. I need help with what to do.\"","best":true},{"text":"Hang up because it feels too awkward."}],"relearn":"Opening with 'I'm under 18 and being blackmailed, I need help' is enough.","persona":"Counsellor","source":"helpline voice"},
  {"id":"fw-1205","cat":"sextortion-plan","type":"role-play","hook":"Tell your own parent the truth even though your voice is shaking.","setup":"Lead with trust:","yourLine":[{"text":"\"I have to tell you something hard, and I need you on my side. Please just help me.\"","best":true},{"text":"Change the subject and keep it inside."}],"relearn":"Leading with 'I need you on my side, please help me' makes telling easier.","persona":"any","source":"finding help voice"},
  {"id":"fw-1206","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"If you delete everything, the problem disappears.\"","myth":{"un":"If you delete everything, the problem disappears.","re":"Deleting destroys the evidence; block the person, but keep the messages.","why":"A report needs the proof, so block to stop contact but don't delete."},"relearn":"Don't delete sextortion messages; block, but keep them as evidence.","persona":"any","source":"sextortion / evidence (verified)"},
  {"id":"fw-1207","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"Boys don't get sextorted.\"","myth":{"un":"Boys don't really get sextorted.","re":"Boys are heavily targeted in financial sextortion; everyone needs the plan.","why":"Most financial-sextortion targets are boys, so the plan is for everyone."},"relearn":"Boys are heavily targeted by sextortion; everyone needs the plan.","persona":"Veer","source":"sextortion targeting (verified)"},
  {"id":"fw-1208","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"Reporting it does nothing anyway.\"","myth":{"un":"Reporting a blackmailer does nothing anyway.","re":"Reporting genuinely helps and is how these crimes get stopped.","why":"Reports let the right people act, which is how the crime ends."},"relearn":"Reporting genuinely helps; it's how these crimes get stopped.","persona":"any","source":"reporting (verified)"},
  {"id":"fw-1209","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"If it's a fake or edited photo, you can't do anything.\"","myth":{"un":"If the photo is fake or edited, nothing can be done.","re":"Threatening you with a fake image is still extortion you can report.","why":"Extortion is the crime whether the image is real or faked, so report it."},"relearn":"A fake or edited photo threat is still extortion; you can report it.","persona":"any","source":"sextortion / deepfake (verified)"},
  {"id":"fw-1210","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"Telling a parent will only make it worse.\"","myth":{"un":"Telling a parent will only make everything worse.","re":"A trusted adult is your way out; you won't be in trouble, you'll be helped.","why":"Adults can do what you can't alone, like report and protect you."},"relearn":"Telling a trusted adult is the way out; you'll be helped, not blamed.","persona":"any","source":"finding help (verified)"},
  {"id":"fw-1211","cat":"sextortion-plan","type":"strike-rewrite","hook":"\"Only careless people get sextorted.\"","myth":{"un":"Only careless people get sextorted.","re":"Smart, careful people are targeted too; being tricked is never a failing.","why":"Manipulators are skilled and target careful people, so it's never your fault."},"relearn":"Careful people get targeted too; being tricked is never your failing.","persona":"any","source":"no blame (verified)"},
  {"id":"fw-1212","cat":"sextortion-plan","type":"match","hook":"Match each panic-thought to the calmer plan-thought.","pairs":[{"left":"\"I have to pay them.\"","right":"\"Don't pay; it invites more.\""},{"left":"\"I should delete it all.\"","right":"\"Block, but keep the evidence.\""},{"left":"\"It's my fault.\"","right":"\"The blackmailer is the criminal.\""},{"left":"\"I must handle it alone.\"","right":"\"Tell a trusted adult.\""},{"left":"\"My life is over.\"","right":"\"There's a clear plan.\""}],"relearn":"Each panic-thought has a calmer plan-thought that keeps you safe.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1213","cat":"sextortion-plan","type":"match","hook":"Match each plan step to the right India route or person.","pairs":[{"left":"Report image abuse","right":"cybercrime.gov.in / 1930"},{"left":"Get help as an under-18","right":"Childline 1098"},{"left":"Right now, in person","right":"A trusted adult"},{"left":"Stop the contact","right":"Block the account"},{"left":"Keep the proof","right":"Save the screenshots"}],"relearn":"Each step of the plan maps to a clear route, person, or action.","persona":"Counsellor","source":"routing (verified)"},
  {"id":"fw-1214","cat":"sextortion-plan","type":"match","hook":"Match the blackmailer's lie to the truth that defeats it.","pairs":[{"left":"\"Pay and I'll delete it.\"","right":"Paying never gets it deleted"},{"left":"\"Send one more and I'll stop.\"","right":"More images never end it"},{"left":"\"Tell anyone and I post it.\"","right":"Telling is how it ends"},{"left":"\"It's your fault you sent it.\"","right":"Being tricked isn't your fault"},{"left":"\"No one can help you.\"","right":"A trusted adult always can"}],"relearn":"Every blackmailer's lie has a plain truth that takes its power away.","persona":"any","source":"sextortion myths"},
  {"id":"fw-1215","cat":"sextortion-plan","type":"match","hook":"Match each feeling to the safe action it shouldn't stop.","pairs":[{"left":"Scared of being judged","right":"Report anyway, you're protected"},{"left":"Ashamed it happened","right":"Tell, it's not your fault"},{"left":"Worried it's too late","right":"Ask for help now"},{"left":"Sure it's your fault","right":"Remember the criminal is them"},{"left":"Tempted to just pay","right":"Stop and get help instead"}],"relearn":"A hard feeling never has to stop the safe action; both can be true.","persona":"any","source":"reassurance"},
  {"id":"fw-1216","cat":"sextortion-plan","type":"match","hook":"Match who you'd reach out to with what they best help with.","pairs":[{"left":"Parent or guardian","right":"Right-now support at home"},{"left":"School counsellor","right":"Calm, no-blame guidance"},{"left":"Childline 1098","right":"Under-18 help any time"},{"left":"cybercrime.gov.in","right":"Reporting image abuse"},{"left":"Class teacher","right":"A trusted face at school"}],"relearn":"Different trusted people and routes each help in their own way.","persona":"Counsellor","source":"finding help (verified)"},
  {"id":"fw-1217","cat":"sextortion-plan","type":"match","hook":"Match each wrong move to the right move that replaces it.","pairs":[{"left":"Paying the demand","right":"Refusing and reporting"},{"left":"Deleting the chat","right":"Saving it as evidence"},{"left":"Replying to plead","right":"Blocking and staying quiet"},{"left":"Sending another photo","right":"Stopping all contact"},{"left":"Hiding it alone","right":"Telling a trusted adult"}],"relearn":"Every wrong move under threat has a safer move that replaces it.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1218","cat":"sextortion-plan","type":"match","hook":"Match the moment in the plan to its one-word reminder.","pairs":[{"left":"They demand money","right":"Don't-pay"},{"left":"You want to wipe the chat","right":"Save-it"},{"left":"They say stay silent","right":"Tell-someone"},{"left":"You start blaming yourself","right":"Not-your-fault"},{"left":"You feel frozen","right":"There's-a-plan"}],"relearn":"Each tense moment has a short reminder that points you back to the plan.","persona":"any","source":"consolidation"},
  {"id":"fw-1219","cat":"sextortion-plan","type":"reflect","hook":"Lensy: if a threat ever landed, what's the first calm thing you'd tell yourself?","prompt":"Pick one.","options":["\"I won't pay.\"","\"This isn't my fault.\"","\"I'll tell someone.\""],"affirm":"Any of these is a strong first thought, and all three are true at once.","relearn":"A calm first thought, don't pay, not my fault, tell, steadies you.","persona":"any","source":"reassurance"},
  {"id":"fw-1220","cat":"sextortion-plan","type":"reflect","hook":"Lensy: who's one person you'd actually go to if something went wrong online?","prompt":"Think of one.","options":["A parent","A teacher","An older sibling or cousin"],"affirm":"Naming even one trusted person means you'd never face it alone.","relearn":"Naming one trusted adult now means you won't be alone if it happens.","persona":"any","source":"finding help"},
  {"id":"fw-1221","cat":"sextortion-plan","type":"reflect","hook":"Lensy: which part of the plan feels easiest to remember?","prompt":"Choose one.","options":["Don't pay","Save the evidence","Tell an adult"],"affirm":"Whatever sticks for you, it'll pull the rest of the plan along with it.","relearn":"The plan step you remember best pulls the others along with it.","persona":"any","source":"consolidation"},
  {"id":"fw-1222","cat":"sextortion-plan","type":"reflect","hook":"Lensy: how does it feel to know the law puts you on the protected side?","prompt":"What comes up?","options":["Relieved","Safer","Less alone"],"affirm":"Knowing you're the protected victim, never in trouble, takes weight off.","relearn":"Knowing you're a protected victim, not in trouble, takes weight off.","persona":"Counsellor","source":"reassurance"},
  {"id":"fw-1223","cat":"sextortion-plan","type":"reflect","hook":"Lensy: if a friend told you they were being blackmailed, what would you lead with?","prompt":"Pick a line.","options":["\"It's not your fault.\"","\"Let's get help.\"","\"I'm here with you.\""],"affirm":"Any of these tells a scared friend the most important thing: you're with them.","relearn":"Leading with 'not your fault' or 'I'm here' is what a scared friend needs.","persona":"any","source":"support"},
  {"id":"fw-1224","cat":"sextortion-plan","type":"reflect","hook":"Lensy: how do you want to feel about online life, knowing the plan?","prompt":"What fits?","options":["Ready, not scared","In control","Calm"],"affirm":"Ready, not scared, is the whole point: alert, in control, still enjoying it.","relearn":"The goal isn't fear, it's ready, in control, and still enjoying online life.","persona":"any","source":"reassurance / ready-not-scared"},
  {"id":"fw-1225","cat":"sextortion-plan","type":"sort","hook":"Sort each move under a threat: safe step or unsafe step?","items":[{"id":"i1","text":"Save the screenshots"},{"id":"i2","text":"Block the account"},{"id":"i3","text":"Tell a trusted adult"},{"id":"i4","text":"Pay the demand"},{"id":"i5","text":"Send another photo"},{"id":"i6","text":"Delete the evidence"}],"bins":[{"id":"safe","label":"Safe step","valence":"pos"},{"id":"unsafe","label":"Unsafe step","valence":"neg"}],"key":{"i1":"safe","i2":"safe","i3":"safe","i4":"unsafe","i5":"unsafe","i6":"unsafe"},"relearn":"Saving, blocking, telling are safe; paying, sending, deleting are unsafe.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1226","cat":"sextortion-plan","type":"sort","hook":"Sort each line: a blackmailer's lie, or a truth that helps you?","items":[{"id":"i1","text":"\"Pay and it's over.\""},{"id":"i2","text":"\"Tell no one or I post it.\""},{"id":"i3","text":"\"It's your fault.\""},{"id":"i4","text":"\"Don't pay; get help.\""},{"id":"i5","text":"\"Telling an adult ends it.\""},{"id":"i6","text":"\"You're the victim, not in trouble.\""}],"bins":[{"id":"lie","label":"Blackmailer's lie","valence":"neg"},{"id":"truth","label":"Truth that helps","valence":"pos"}],"key":{"i1":"lie","i2":"lie","i3":"lie","i4":"truth","i5":"truth","i6":"truth"},"relearn":"The threats are lies; the plan's lines are the truths that free you.","persona":"any","source":"sextortion myths"},
  {"id":"fw-1227","cat":"sextortion-plan","type":"sort","hook":"Sort each thing: real evidence to keep, or noise to ignore?","items":[{"id":"i1","text":"The threat messages"},{"id":"i2","text":"Their account name"},{"id":"i3","text":"Screenshots of the demand"},{"id":"i4","text":"Their 'pay or else' deadline"},{"id":"i5","text":"Their promise to 'delete it'"},{"id":"i6","text":"Their order to stay silent"}],"bins":[{"id":"keep","label":"Keep as evidence","valence":"pos"},{"id":"ignore","label":"Ignore / don't act on","valence":"neg"}],"key":{"i1":"keep","i2":"keep","i3":"keep","i4":"ignore","i5":"ignore","i6":"ignore"},"relearn":"Save the proof; ignore their deadlines, promises, and 'stay silent' orders.","persona":"any","source":"sextortion / evidence"},
  {"id":"fw-1228","cat":"sextortion-plan","type":"sort","hook":"Sort each route by who or what it's for.","items":[{"id":"i1","text":"Childline 1098"},{"id":"i2","text":"A child-safety helpline call"},{"id":"i3","text":"cybercrime.gov.in"},{"id":"i4","text":"Helpline 1930"},{"id":"i5","text":"A parent at home"},{"id":"i6","text":"Your school counsellor"}],"bins":[{"id":"under18","label":"For under-18 help","valence":"neutral"},{"id":"imageabuse","label":"For image abuse","valence":"neutral"},{"id":"rightnow","label":"For right now, in person","valence":"neutral"}],"key":{"i1":"under18","i2":"under18","i3":"imageabuse","i4":"imageabuse","i5":"rightnow","i6":"rightnow"},"relearn":"Match the worry to its route: under-18, image abuse, or right-now help.","persona":"Counsellor","source":"routing (verified)"},
  {"id":"fw-1229","cat":"sextortion-plan","type":"sort","hook":"Sort each feeling-thought: a trap that keeps you stuck, or a truth that frees you?","items":[{"id":"i1","text":"\"I must keep this secret.\""},{"id":"i2","text":"\"My family will disown me.\""},{"id":"i3","text":"\"It's too late to tell.\""},{"id":"i4","text":"\"A trusted adult will help me.\""},{"id":"i5","text":"\"It's never too late to ask.\""},{"id":"i6","text":"\"I'm the victim here.\""}],"bins":[{"id":"trap","label":"Trap thought","valence":"neg"},{"id":"free","label":"Freeing truth","valence":"pos"}],"key":{"i1":"trap","i2":"trap","i3":"trap","i4":"free","i5":"free","i6":"free"},"relearn":"Secrecy and shame thoughts trap you; the plan's truths set you free.","persona":"any","source":"India shame factor"},
  {"id":"fw-1230","cat":"sextortion-plan","type":"sort","hook":"Sort each statement about who gets sextorted: myth or fact?","items":[{"id":"i1","text":"\"Only girls get sextorted.\""},{"id":"i2","text":"\"Only careless people are targeted.\""},{"id":"i3","text":"\"Smart kids never fall for it.\""},{"id":"i4","text":"\"Boys are heavily targeted too.\""},{"id":"i5","text":"\"Careful people get targeted too.\""},{"id":"i6","text":"\"Anyone could face this.\""}],"bins":[{"id":"myth","label":"Myth","valence":"neg"},{"id":"fact","label":"Fact","valence":"pos"}],"key":{"i1":"myth","i2":"myth","i3":"myth","i4":"fact","i5":"fact","i6":"fact"},"relearn":"Anyone can be targeted, boys included; being tricked is never a failing.","persona":"Veer","source":"sextortion targeting"},
  {"id":"fw-1231","cat":"sextortion-plan","type":"sort","hook":"Sort what to do with a sextortion chat: do this, or never do this?","items":[{"id":"i1","text":"Screenshot the threats"},{"id":"i2","text":"Block the account"},{"id":"i3","text":"Show a trusted adult"},{"id":"i4","text":"Pay to make it stop"},{"id":"i5","text":"Delete the whole chat"},{"id":"i6","text":"Reply with another photo"}],"bins":[{"id":"do","label":"Do this","valence":"tell"},{"id":"never","label":"Never do this","valence":"uhoh"}],"key":{"i1":"do","i2":"do","i3":"do","i4":"never","i5":"never","i6":"never"},"relearn":"Do: screenshot, block, show an adult. Never: pay, delete, send more.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1232","cat":"sextortion-plan","type":"sort","hook":"Sort each reaction the moment a threat lands: calm-plan, or panic-move?","items":[{"id":"i1","text":"Stop replying"},{"id":"i2","text":"Save the message"},{"id":"i3","text":"Find a trusted adult"},{"id":"i4","text":"Pay instantly"},{"id":"i5","text":"Delete and pretend it's gone"},{"id":"i6","text":"Send what they ask"}],"bins":[{"id":"calm","label":"Calm-plan move","valence":"pos"},{"id":"panic","label":"Panic move","valence":"neg"}],"key":{"i1":"calm","i2":"calm","i3":"calm","i4":"panic","i5":"panic","i6":"panic"},"relearn":"Stop, save, tell is the calm plan; pay, delete, comply is panic.","persona":"any","source":"sextortion plan / no-panic"},
  {"id":"fw-1233","cat":"sextortion-plan","type":"spot","hook":"Spot the two lines a blackmailer uses to trap you, not the safe replies.","scene":[{"id":"a","text":"\"Pay me or I post your photo tonight.\"","trick":true},{"id":"b","text":"\"I'm telling a trusted adult about this.\"","trick":false},{"id":"c","text":"\"Send one more and I swear I'll stop.\"","trick":true},{"id":"d","text":"\"I'm blocking you and saving the messages.\"","trick":false},{"id":"e","text":"\"I won't pay you anything.\"","trick":false}],"why":"The caught lines are the threat and the 'one more' trap, pure pressure.","relearn":"The blackmailer's threat and 'one more' line are the traps.","persona":"any","source":"sextortion red flags"},
  {"id":"fw-1234","cat":"sextortion-plan","type":"spot","hook":"Spot the two unsafe moves a panicking victim might make.","scene":[{"id":"a","text":"Screenshot the threat","trick":false},{"id":"b","text":"Pay the demand quietly","trick":true},{"id":"c","text":"Block the account","trick":false},{"id":"d","text":"Delete the whole chat to hide it","trick":true},{"id":"e","text":"Tell a trusted adult","trick":false}],"why":"Paying and deleting the evidence are the unsafe panic moves to avoid.","relearn":"Paying and deleting the evidence are the panic moves.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1235","cat":"sextortion-plan","type":"spot","hook":"Spot the two myths in this chat, not the true reassurances.","scene":[{"id":"a","text":"\"If you pay once, they'll stop.\"","trick":true},{"id":"b","text":"\"Being tricked is never your fault.\"","trick":false},{"id":"c","text":"\"Telling an adult will make it worse.\"","trick":true},{"id":"d","text":"\"You're the victim, not in trouble.\"","trick":false},{"id":"e","text":"\"There's a clear plan for this.\"","trick":false}],"why":"The caught lines are the two myths: paying stops it, telling makes it worse.","relearn":"'Paying stops it' and 'telling makes it worse' are the myths.","persona":"any","source":"sextortion myths"},
  {"id":"fw-1236","cat":"sextortion-plan","type":"spot","hook":"Spot the two red-flag demands hiding among normal messages.","scene":[{"id":"a","text":"\"Send a private pic to verify your account.\"","trick":true},{"id":"b","text":"\"Want to play the match this weekend?\"","trick":false},{"id":"c","text":"\"Video-call now and prove it's really you.\"","trick":true},{"id":"d","text":"\"Did you finish the science project?\"","trick":false},{"id":"e","text":"\"Team's training at 5, you coming?\"","trick":false}],"why":"The caught lines demand a private pic and a 'prove it' call.","relearn":"The 'private pic' and 'prove it on call' demands are the traps.","persona":"any","source":"sextortion grooming"},
  {"id":"fw-1237","cat":"sextortion-plan","type":"spot","hook":"Spot the two lines that pressure silence, not the ones that lead to help.","scene":[{"id":"a","text":"\"Keep this between us or I'll post it.\"","trick":true},{"id":"b","text":"\"Let's tell your counsellor together.\"","trick":false},{"id":"c","text":"\"If you tell anyone, you'll be in trouble.\"","trick":true},{"id":"d","text":"\"We can report at cybercrime.gov.in.\"","trick":false},{"id":"e","text":"\"Childline 1098 can help any time.\"","trick":false}],"why":"The caught lines push secrecy and a false 'you'll be in trouble'.","relearn":"The 'keep it secret' and 'you'll be in trouble' lines are the trap.","persona":"Counsellor","source":"sextortion / secrecy"},
  {"id":"fw-1238","cat":"sextortion-plan","type":"spot","hook":"Spot the two false beliefs that keep a boy from getting help.","scene":[{"id":"a","text":"\"Boys don't really get sextorted.\"","trick":true},{"id":"b","text":"\"It's okay for a guy to ask for help.\"","trick":false},{"id":"c","text":"\"Asking for help means I'm weak.\"","trick":true},{"id":"d","text":"\"Loads of guys go through this.\"","trick":false},{"id":"e","text":"\"A counsellor won't judge me.\"","trick":false}],"why":"The caught lines, 'boys don't' and 'asking is weak', are the false beliefs.","relearn":"'Boys don't' and 'asking is weak' are the false beliefs.","persona":"Veer","source":"no blame / boys"},
  {"id":"fw-1239","cat":"sextortion-plan","type":"spot","hook":"Spot the two wrong 'plans', not the steps that keep you safe.","scene":[{"id":"a","text":"\"Just pay and it'll all go away.\"","trick":true},{"id":"b","text":"\"Block them but keep the messages.\"","trick":false},{"id":"c","text":"\"Delete everything so there's no trace.\"","trick":true},{"id":"d","text":"\"Save screenshots before blocking.\"","trick":false},{"id":"e","text":"\"Tell a trusted adult today.\"","trick":false}],"why":"The caught lines, pay it away and delete everything, are the wrong plans.","relearn":"'Pay it away' and 'delete everything' are the wrong plans.","persona":"any","source":"sextortion plan"},
  {"id":"fw-1240","cat":"sextortion-plan","type":"spot","hook":"Spot the two scare tactics in the threat, not the calm facts.","scene":[{"id":"a","text":"\"Your life is over if this gets out.\"","trick":true},{"id":"b","text":"\"You're a protected victim under the law.\"","trick":false},{"id":"c","text":"\"No one can ever help you now.\"","trick":true},{"id":"d","text":"\"People whose job is to help can stop this.\"","trick":false},{"id":"e","text":"\"Reporting genuinely helps.\"","trick":false}],"why":"The caught lines, 'life is over' and 'no one can help', are scare tactics.","relearn":"'Life is over' and 'no one can help' are pure scare tactics.","persona":"any","source":"reassurance / red flags"},
  {"id":"fw-1260","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'fan' DM.","scene":[{"id":"a","text":"A stranger says you're 'too mature for your age'","trick":true},{"id":"b","text":"They ask if you're free to chat now","trick":false},{"id":"c","text":"They want to add you on a disappearing-message app","trick":true},{"id":"d","text":"They follow a few of your friends too","trick":false},{"id":"e","text":"They reply to your story like anyone might","trick":false}],"why":"Flattering your 'maturity' and a vanishing-message app are classic openers.","relearn":"Big flattery and 'let's go private' are grooming flags.","cat":"spot-grooming"},
  {"id":"fw-1261","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags from this 'photographer'.","scene":[{"id":"a","text":"They offer you a 'modelling break' out of nowhere","trick":true},{"id":"b","text":"They have a public studio page with reviews","trick":false},{"id":"c","text":"They want a 'private test shot' just for them","trick":true},{"id":"d","text":"They mention a shoot date and a real address","trick":false},{"id":"e","text":"They say a parent can come along","trick":false}],"why":"Surprise 'modelling breaks' and a 'private test shot' are fake-casting traps.","relearn":"A surprise modelling offer plus a private photo is a trap.","cat":"spot-grooming"},
  {"id":"fw-1262","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the two red flags in this gaming-clan invite.","scene":[{"id":"a","text":"An older 'captain' DMs you free in-game credits","trick":true},{"id":"b","text":"The clan has open practice times","trick":false},{"id":"c","text":"He says 'keep our chats off the group, just us'","trick":true},{"id":"d","text":"He asks which days you can play","trick":false},{"id":"e","text":"Other members chat normally in the group","trick":false}],"why":"Free credits to hook you plus 'keep it just between us' is grooming, not generosity.","relearn":"Stranger gifts plus 'keep it secret' are grooming flags.","cat":"spot-grooming"},
  {"id":"fw-1263","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'study buddy' chat.","scene":[{"id":"a","text":"They ask for your full home address 'to send notes'","trick":true},{"id":"b","text":"They share a chapter summary","trick":false},{"id":"c","text":"They DM you at 2 a.m. demanding a reply","trick":true},{"id":"d","text":"They ask which board exam you're sitting","trick":false},{"id":"e","text":"They suggest a daytime call to revise","trick":false}],"why":"Fishing for your exact address and 2 a.m. pressure for replies are warning signs.","relearn":"Asking your address early and late pressure are warnings.","cat":"spot-grooming"},
  {"id":"fw-1264","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two lies in this 'I'm your age' profile.","scene":[{"id":"a","text":"'I'm 14 too, promise' with no photo ever","trick":true},{"id":"b","text":"The account was made last week, no real friends","trick":true},{"id":"c","text":"They like a band you also like","trick":false},{"id":"d","text":"They post about school holidays","trick":false},{"id":"e","text":"They reply within normal hours","trick":false}],"why":"'I'm your age, promise' with no proof, on a brand-new empty account, is a known lie.","relearn":"'I'm your age too' with a new, friendless account is a grooming lie.","cat":"spot-grooming"},
  {"id":"fw-1265","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags as this 'friend' speeds up.","scene":[{"id":"a","text":"After one day they call you their 'soulmate'","trick":true},{"id":"b","text":"They remember your pet's name","trick":false},{"id":"c","text":"They say 'nobody gets you like I do, don't tell anyone'","trick":true},{"id":"d","text":"They ask about your favourite movie","trick":false},{"id":"e","text":"They wish you luck for a test","trick":false}],"why":"A one-day 'soulmate' bond plus 'don't tell anyone' is how a groomer builds a trap fast.","relearn":"A rushed 'special bond' plus secrecy is a grooming red flag.","cat":"spot-grooming"},
  {"id":"fw-1266","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'caring' boyfriend chat.","scene":[{"id":"a","text":"He says 'if you trusted me you'd send a pic'","trick":true},{"id":"b","text":"He asks how your day went","trick":false},{"id":"c","text":"He says 'keep us secret or it's over'","trick":true},{"id":"d","text":"He sends a song he thinks you'll like","trick":false},{"id":"e","text":"He waits while you finish dinner","trick":false}],"why":"Turning a 'no' into proof of love and threatening secrecy are coercion, not caring.","relearn":"'Prove it with a pic' plus 'keep us secret' is coercion, a serious red flag.","cat":"spot-grooming"},
  {"id":"fw-1267","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this DM from a 'talent scout'.","scene":[{"id":"a","text":"They guarantee you'll go viral if you 'cooperate'","trick":true},{"id":"b","text":"They link a public agency site","trick":false},{"id":"c","text":"They want you to install an app only they use","trick":true},{"id":"d","text":"They mention an office you could visit","trick":false},{"id":"e","text":"They say think it over with family","trick":false}],"why":"Guaranteed fame for 'cooperation' and a private app only they use are control tactics.","relearn":"Guaranteed fame plus a private-only app are red flags.","cat":"spot-grooming"},
  {"id":"fw-1268","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two catfish tells in this profile.","scene":[{"id":"a","text":"Their photos look like a perfect stock model","trick":true},{"id":"b","text":"They refuse a live video call, every single time","trick":true},{"id":"c","text":"They sometimes take a while to reply","trick":false},{"id":"d","text":"They post a few blurry everyday pics","trick":false},{"id":"e","text":"They mention a real, checkable school fest","trick":false}],"why":"Model-perfect photos plus never doing a live call are classic catfish tells.","relearn":"Stock-perfect photos and 'never video call' often mean a fake profile.","cat":"spot-grooming"},
  {"id":"fw-1269","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'mentor' DM.","scene":[{"id":"a","text":"He slowly tells you your real friends are 'fake'","trick":true},{"id":"b","text":"He shares a genuine workout tip","trick":false},{"id":"c","text":"He tests you: 'would you ever send a risky pic?'","trick":true},{"id":"d","text":"He asks how your match went","trick":false},{"id":"e","text":"He says well done on a goal","trick":false}],"why":"Isolating you from friends and 'testing' you toward risky pics are grooming, even from a 'mentor'.","relearn":"Isolation from friends plus boundary-testing are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1270","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this comment-then-DM move.","scene":[{"id":"a","text":"They reply to every post, then beg to move to DMs","trick":true},{"id":"b","text":"They like one photo and move on","trick":false},{"id":"c","text":"In DMs they ask you to hide the chat from family","trick":true},{"id":"d","text":"They ask which city you're in (you keep it vague)","trick":false},{"id":"e","text":"They share a public meme","trick":false}],"why":"Flooding your posts to push you into hidden DMs, then hiding it, is grooming.","relearn":"Pushing you into hidden DMs is a grooming red flag.","cat":"spot-grooming"},
  {"id":"fw-1271","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'giveaway' message.","scene":[{"id":"a","text":"'You won! Just video-call me privately to claim'","trick":true},{"id":"b","text":"A brand runs a public, posted contest","trick":false},{"id":"c","text":"'Don't tell anyone you won, it's our secret'","trick":true},{"id":"d","text":"A friend tags you in the contest post","trick":false},{"id":"e","text":"The contest has clear public rules","trick":false}],"why":"A 'prize' you must claim by private video call, kept secret, is a lure, not a giveaway.","relearn":"A 'private call to claim' a secret prize is a grooming lure.","cat":"spot-grooming"},
  {"id":"fw-1272","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'older cousin's friend' chat.","scene":[{"id":"a","text":"'Since we're basically family, send me a selfie pic'","trick":true},{"id":"b","text":"They ask about your cousin's wedding","trick":false},{"id":"c","text":"They say 'this stays between us, okay?'","trick":true},{"id":"d","text":"They share a festival photo","trick":false},{"id":"e","text":"They wish your family well","trick":false}],"why":"Using a family link to lower your guard, plus secrecy, is grooming by a 'known' contact.","relearn":"A 'we're family, send a pic' plus secrecy is a red flag.","cat":"spot-grooming"},
  {"id":"fw-1273","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this late-night chat.","scene":[{"id":"a","text":"They only ever message you between 1 and 4 a.m.","trick":true},{"id":"b","text":"They ask about your weekend plans","trick":false},{"id":"c","text":"They get angry if you don't reply instantly","trick":true},{"id":"d","text":"They send a daytime 'good morning'","trick":false},{"id":"e","text":"They mention a show you both watch","trick":false}],"why":"Only ever messaging at odd hours and rage when you're slow are control red flags.","relearn":"Odd-hours-only contact and anger at slow replies are warning signs.","cat":"spot-grooming"},
  {"id":"fw-1274","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'fan account' DM.","scene":[{"id":"a","text":"'You're my favourite, here's a UPI gift, our secret'","trick":true},{"id":"b","text":"They comment 'nice edit' on a reel","trick":false},{"id":"c","text":"'Send me a private clip just for me'","trick":true},{"id":"d","text":"They share your post to their story","trick":false},{"id":"e","text":"They ask when your next reel drops","trick":false}],"why":"A secret 'gift' plus 'a private clip just for me' is grooming, not real fandom.","relearn":"A secret money gift plus a 'just-for-me' private clip are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1275","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'crypto coach' DM.","scene":[{"id":"a","text":"'I'll double your money, just keep it from your parents'","trick":true},{"id":"b","text":"He shares a free public article","trick":false},{"id":"c","text":"'Verify yourself by sending a face video to me'","trick":true},{"id":"d","text":"He answers a basic question","trick":false},{"id":"e","text":"He says don't invest what you can't lose","trick":false}],"why":"'Hide it from your parents' and a private face-video 'verification' are flags.","relearn":"'Keep it from parents' plus a private face video are flags.","cat":"spot-grooming"},
  {"id":"fw-1276","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this DM after a public fight.","scene":[{"id":"a","text":"'I saw they were mean to you, you can trust only me'","trick":true},{"id":"b","text":"They send a supportive emoji","trick":false},{"id":"c","text":"'Let's talk where no one can see us'","trick":true},{"id":"d","text":"They suggest blocking the bully","trick":false},{"id":"e","text":"They say tell a teacher about it","trick":false}],"why":"'Trust only me' after a fight, plus 'where no one can see us', is isolation grooming.","relearn":"'You can trust only me' plus a hidden chat are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1277","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'audition' chat.","scene":[{"id":"a","text":"'Real actors aren't shy, send a private clip to prove it'","trick":true},{"id":"b","text":"They mention a public casting call","trick":false},{"id":"c","text":"'Don't loop in your parents, they'll just say no'","trick":true},{"id":"d","text":"They ask your age range for a role","trick":false},{"id":"e","text":"They say bring a guardian to the audition","trick":false}],"why":"Shaming you into a private clip and cutting out parents are pressure tactics.","relearn":"Shaming you into a private clip is a red flag.","cat":"spot-grooming"},
  {"id":"fw-1278","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'best friend' move online.","scene":[{"id":"a","text":"They guilt-trip you: 'a real bestie would share everything'","trick":true},{"id":"b","text":"They remember your birthday","trick":false},{"id":"c","text":"They want passwords 'to prove we have no secrets'","trick":true},{"id":"d","text":"They send a study link","trick":false},{"id":"e","text":"They cheer you up after a bad day","trick":false}],"why":"Guilt over 'sharing everything' and asking for passwords are control, not friendship.","relearn":"Guilt-tripping you and asking for passwords are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1279","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this DM that seems harmless.","scene":[{"id":"a","text":"'What time are you home alone after school?'","trick":true},{"id":"b","text":"They ask your favourite subject","trick":false},{"id":"c","text":"'Send your live location so I can surprise you'","trick":true},{"id":"d","text":"They share a class meme","trick":false},{"id":"e","text":"They ask if you finished the homework","trick":false}],"why":"Fishing for when you're home alone and your live location are serious safety red flags.","relearn":"'When are you home alone?' and 'send your live location' are red flags.","cat":"spot-grooming"},
  {"id":"fw-1280","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'sponsor' offer.","scene":[{"id":"a","text":"'Free gaming gear, just video-chat me privately first'","trick":true},{"id":"b","text":"A real brand posts a public sign-up form","trick":false},{"id":"c","text":"'Tell no one, they'll get jealous of your deal'","trick":true},{"id":"d","text":"They list other public sponsored players","trick":false},{"id":"e","text":"They say a parent can read the contract","trick":false}],"why":"Free gear for a private video chat, kept secret, is a lure, not a sponsorship.","relearn":"Free gear for a secret 'private video first' is a lure.","cat":"spot-grooming"},
  {"id":"fw-1281","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags as a stranger 'levels up' fast.","scene":[{"id":"a","text":"Within hours they ask for a photo 'to see the real you'","trick":true},{"id":"b","text":"They ask what music you're into","trick":false},{"id":"c","text":"'If you say no, I'll think you don't like me'","trick":true},{"id":"d","text":"They share their favourite game","trick":false},{"id":"e","text":"They send a thumbs-up to your reply","trick":false}],"why":"A fast photo ask plus 'no means you don't like me' is pressure, not closeness.","relearn":"A rushed photo ask plus guilt for saying no are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1282","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'verify you're real' DM.","scene":[{"id":"a","text":"'Prove you're not a bot, send a quick face video to me'","trick":true},{"id":"b","text":"A real app verifies you inside its own settings","trick":false},{"id":"c","text":"'Keep this verification just between us two'","trick":true},{"id":"d","text":"They link the app's public help page","trick":false},{"id":"e","text":"They say no rush, do it whenever","trick":false}],"why":"A private 'face video to verify' kept secret isn't how real apps work.","relearn":"A secret 'face video to verify' is a grooming lure.","cat":"spot-grooming"},
  {"id":"fw-1283","type":"spot","persona":"Riya","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'helpful senior' chat.","scene":[{"id":"a","text":"'I'll fix your grade if you keep our chats secret'","trick":true},{"id":"b","text":"They share class notes openly","trick":false},{"id":"c","text":"'Send a pic so I know it's really you'","trick":true},{"id":"d","text":"They explain a tough sum","trick":false},{"id":"e","text":"They suggest asking the teacher too","trick":false}],"why":"Trading favours for secret chats and a 'prove-it' pic is grooming by someone you 'know'.","relearn":"A secret favour plus a 'prove-it' photo are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1284","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'long-time online friend' chat.","scene":[{"id":"a","text":"After months, they suddenly push for a private photo","trick":true},{"id":"b","text":"You've chatted openly for ages","trick":false},{"id":"c","text":"They say 'after all this time, don't you trust me?'","trick":true},{"id":"d","text":"They share a meme like always","trick":false},{"id":"e","text":"They remember your exam dates","trick":false}],"why":"Time chatting doesn't earn a photo; 'don't you trust me?' is the pressure tell.","relearn":"A sudden photo push plus 'don't you trust me?' are flags.","cat":"spot-grooming"},
  {"id":"fw-1285","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this group-chat 'admin' DM.","scene":[{"id":"a","text":"'As admin I need a selfie of you to keep you in the group'","trick":true},{"id":"b","text":"The group has clear public rules","trick":false},{"id":"c","text":"'Don't mention this DM to the others'","trick":true},{"id":"d","text":"They post normal announcements","trick":false},{"id":"e","text":"They welcome new members openly","trick":false}],"why":"An 'admin' demanding a private selfie and silence about the DM is grooming, not moderation.","relearn":"An 'admin' demanding a secret selfie is a red flag.","cat":"spot-grooming"},
  {"id":"fw-1286","type":"spot","persona":"Veer","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'be a man' DM.","scene":[{"id":"a","text":"'A real man would send proof, don't be a coward'","trick":true},{"id":"b","text":"He talks about a match score","trick":false},{"id":"c","text":"'Our chats stay secret or you're out'","trick":true},{"id":"d","text":"He shares a gym reel","trick":false},{"id":"e","text":"He says nice play on a clip","trick":false}],"why":"Shaming your manhood into 'proof' and threats of secrecy are coercion, not a challenge.","relearn":"Shaming you into 'proof' plus secrecy threats are grooming red flags.","cat":"spot-grooming"},
  {"id":"fw-1287","type":"spot","persona":"any","source":"grooming pattern (verified)","hook":"Spot the two red flags in this 'just being friendly' chat.","scene":[{"id":"a","text":"They keep steering every chat toward your body","trick":true},{"id":"b","text":"They ask about your weekend","trick":false},{"id":"c","text":"They send 'oops wrong chat' private pics as 'a joke'","trick":true},{"id":"d","text":"They share a funny clip","trick":false},{"id":"e","text":"They say bye when you log off","trick":false}],"why":"Always steering to your body and 'accidental' private pics are deliberate boundary-pushing.","relearn":"Steering chat to your body and 'accidental' pics are flags.","cat":"spot-grooming"},
  {"id":"fw-1288","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a grooming red flag, or ordinary online life?","items":[{"id":"a","text":"A stranger gifts you to win you over"},{"id":"b","text":"A classmate shares the timetable"},{"id":"c","text":"'Move to my private app, just us'"},{"id":"d","text":"A friend tags you in a meme"},{"id":"e","text":"'Keep our chats a secret from family'"},{"id":"f","text":"A group reminds you of practice"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"ok","label":"Ordinary","valence":"pos"}],"key":{"a":"flag","b":"ok","c":"flag","d":"ok","e":"flag","f":"ok"},"relearn":"Stranger gifts, secret private apps and 'don't tell family' are flags; normal friend stuff isn't.","cat":"spot-grooming"},
  {"id":"fw-1289","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: builds a trap, or builds real friendship?","items":[{"id":"a","text":"Rushing you to feel 'special' in a day"},{"id":"b","text":"Getting to know you slowly, in the open"},{"id":"c","text":"Cutting you off from other friends"},{"id":"d","text":"Respecting it when you log off"},{"id":"e","text":"'Nobody else understands you like I do'"},{"id":"f","text":"Being fine with your family knowing them"}],"bins":[{"id":"trap","label":"A trap","valence":"neg"},{"id":"real","label":"Real friendship","valence":"pos"}],"key":{"a":"trap","b":"real","c":"trap","d":"real","e":"trap","f":"real"},"relearn":"Rushing, isolating and 'only I get you' build a trap; slow, open and respectful is real.","cat":"spot-grooming"},
  {"id":"fw-1290","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a safe move with a new contact, or risky?","items":[{"id":"a","text":"Keeping your school and address private"},{"id":"b","text":"Sending a pic to 'prove you trust them'"},{"id":"c","text":"Telling a trusted adult about an odd request"},{"id":"d","text":"Switching to a secret app at their push"},{"id":"e","text":"Saying no to a live-location share"},{"id":"f","text":"Doing a 'private verification' video for them"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Guard your info, say no, tell an adult; don't 'prove trust' with pics.","cat":"spot-grooming"},
  {"id":"fw-1291","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a catfish tell, or a normal sign it's real?","items":[{"id":"a","text":"Photos that look like a stock model"},{"id":"b","text":"They'll happily do a live video call"},{"id":"c","text":"They refuse video calls every time"},{"id":"d","text":"They post everyday, slightly blurry pics"},{"id":"e","text":"Their account is new with no real friends"},{"id":"f","text":"They mention a checkable school event"}],"bins":[{"id":"fake","label":"Catfish tell","valence":"neg"},{"id":"real","label":"Probably real","valence":"pos"}],"key":{"a":"fake","b":"real","c":"fake","d":"real","e":"fake","f":"real"},"relearn":"Stock-perfect pics, 'never video call' and an empty account are catfish tells.","cat":"spot-grooming"},
  {"id":"fw-1292","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a grooming opener, or just being nice?","items":[{"id":"a","text":"Over-the-top flattery from a stranger"},{"id":"b","text":"A friend saying 'good luck' for your test"},{"id":"c","text":"Surprise gifts to win your trust"},{"id":"d","text":"A classmate sharing a useful link"},{"id":"e","text":"'You're so mature, not like other kids'"},{"id":"f","text":"A teammate praising your goal"}],"bins":[{"id":"groom","label":"Grooming opener","valence":"neg"},{"id":"nice","label":"Just nice","valence":"pos"}],"key":{"a":"groom","b":"nice","c":"groom","d":"nice","e":"groom","f":"nice"},"relearn":"Stranger flattery, surprise gifts and 'so mature' are openers; ordinary kindness isn't.","cat":"spot-grooming"},
  {"id":"fw-1293","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: speak up to a trusted adult, or handle alone?","items":[{"id":"a","text":"A stranger asked for a private photo"},{"id":"b","text":"A new contact keeps pushing a secret app"},{"id":"c","text":"Someone is fishing for your home address"},{"id":"d","text":"A friend sent a normal study reminder"},{"id":"e","text":"A classmate liked your post"},{"id":"f","text":"A 'mentor' is isolating you from friends"}],"bins":[{"id":"tell","label":"Tell an adult","valence":"tell"},{"id":"fine","label":"No worry","valence":"pos"}],"key":{"a":"tell","b":"tell","c":"tell","d":"fine","e":"fine","f":"tell"},"relearn":"Photo asks, secret apps, address-fishing and isolation: tell an adult.","cat":"spot-grooming"},
  {"id":"fw-1294","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a line a groomer uses, or a normal friend's line?","items":[{"id":"a","text":"'Don't tell anyone about us'"},{"id":"b","text":"'Want to study together this weekend?'"},{"id":"c","text":"'If you trusted me you'd send a pic'"},{"id":"d","text":"'Did you finish the homework?'"},{"id":"e","text":"'You're my soulmate' after one day"},{"id":"f","text":"'Good game today!'"}],"bins":[{"id":"groom","label":"Groomer's line","valence":"neg"},{"id":"friend","label":"Friend's line","valence":"pos"}],"key":{"a":"groom","b":"friend","c":"groom","d":"friend","e":"groom","f":"friend"},"relearn":"'Keep us secret', 'prove it with a pic' and instant 'soulmate' are groomer lines, not a friend's.","cat":"spot-grooming"},
  {"id":"fw-1295","type":"sort","persona":"Veer","source":"grooming pattern (verified)","hook":"Sort: a scam/grooming lure, or a real opportunity?","items":[{"id":"a","text":"'Free credits, just video-call me in private'"},{"id":"b","text":"A brand's public, posted sign-up form"},{"id":"c","text":"'Double your money, hide it from your parents'"},{"id":"d","text":"A clan with open practice times"},{"id":"e","text":"'Tell no one about your special deal'"},{"id":"f","text":"A sponsor letting a parent read the contract"}],"bins":[{"id":"lure","label":"A lure","valence":"neg"},{"id":"real","label":"Real chance","valence":"pos"}],"key":{"a":"lure","b":"real","c":"lure","d":"real","e":"lure","f":"real"},"relearn":"Private 'free' deals and 'hide it from parents' are lures, not real.","cat":"spot-grooming"},
  {"id":"fw-1296","type":"sort","persona":"Riya","source":"grooming pattern (verified)","hook":"Sort: pressure to resist, or a respectful chat?","items":[{"id":"a","text":"'A real bestie shares everything, send a pic'"},{"id":"b","text":"'How did your exam go?'"},{"id":"c","text":"'Keep us secret or it's over'"},{"id":"d","text":"'Take your time replying, no rush'"},{"id":"e","text":"'Give me your password to prove no secrets'"},{"id":"f","text":"'Want to revise on a call tomorrow?'"}],"bins":[{"id":"press","label":"Pressure","valence":"neg"},{"id":"respect","label":"Respectful","valence":"pos"}],"key":{"a":"press","b":"respect","c":"press","d":"respect","e":"press","f":"respect"},"relearn":"'Share everything', secrecy and password demands are pressure, not respect.","cat":"spot-grooming"},
  {"id":"fw-1297","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a careful online habit, or a risky one?","items":[{"id":"a","text":"Keeping your account private"},{"id":"b","text":"Posting your live location for fun"},{"id":"c","text":"Saying no to a 'prove-it' photo"},{"id":"d","text":"Installing a stranger's secret-only app"},{"id":"e","text":"Telling an adult about a creepy DM"},{"id":"f","text":"Sharing your exact daily route publicly"}],"bins":[{"id":"careful","label":"Careful","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"careful","b":"risky","c":"careful","d":"risky","e":"careful","f":"risky"},"relearn":"Private accounts, saying no and telling an adult are careful; live location and secret apps are risky.","cat":"spot-grooming"},
  {"id":"fw-1298","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a true thing about grooming, or a myth?","items":[{"id":"a","text":"Groomers follow a tell-tale pattern you can learn"},{"id":"b","text":"Only careless kids ever get groomed"},{"id":"c","text":"Being targeted is never your fault"},{"id":"d","text":"If someone's kind, they must be safe"},{"id":"e","text":"Groomers can be people you seem to 'know'"},{"id":"f","text":"Grooming only happens to little kids"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Grooming has a learnable pattern, isn't your fault, and 'known' contacts do it.","cat":"spot-grooming"},
  {"id":"fw-1299","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: a normal first chat, or worth a second look?","items":[{"id":"a","text":"'Hey, loved your art!' on a public post"},{"id":"b","text":"'You're too grown-up for your age'"},{"id":"c","text":"'What's your favourite subject?'"},{"id":"d","text":"'What time are you home alone?'"},{"id":"e","text":"'Nice to meet a fellow fan'"},{"id":"f","text":"'Move to my private app, don't tell anyone'"}],"bins":[{"id":"ok","label":"Normal","valence":"pos"},{"id":"watch","label":"Watch out","valence":"uhoh"}],"key":{"a":"ok","b":"watch","c":"ok","d":"watch","e":"ok","f":"watch"},"relearn":"'Too grown-up', 'when are you home alone?' and secret private apps are worth a second look.","cat":"spot-grooming"},
  {"id":"fw-1300","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: guard your info, or hand it over?","items":[{"id":"a","text":"Keep your school name off your profile"},{"id":"b","text":"Share your home address 'for a gift'"},{"id":"c","text":"Keep your live location off"},{"id":"d","text":"Send a face video to 'verify' for a stranger"},{"id":"e","text":"Stay vague about your daily routine"},{"id":"f","text":"Give a 'mentor' your account password"}],"bins":[{"id":"guard","label":"Guard it","valence":"pos"},{"id":"give","label":"Don't hand over","valence":"neg"}],"key":{"a":"guard","b":"give","c":"guard","d":"give","e":"guard","f":"give"},"relearn":"Keep school, address, location and passwords private from strangers.","cat":"spot-grooming"},
  {"id":"fw-1301","type":"sort","persona":"any","source":"grooming pattern (verified)","hook":"Sort: respects your 'no', or pushes past it?","items":[{"id":"a","text":"'Okay, no problem, we don't have to'"},{"id":"b","text":"'If you really liked me you'd do it'"},{"id":"c","text":"'Take your time, your call'"},{"id":"d","text":"'Everyone does it, don't be a baby'"},{"id":"e","text":"'Cool, let's just chat then'"},{"id":"f","text":"'I'll be upset if you say no again'"}],"bins":[{"id":"respect","label":"Respects no","valence":"pos"},{"id":"push","label":"Pushes past","valence":"neg"}],"key":{"a":"respect","b":"push","c":"respect","d":"push","e":"respect","f":"push"},"relearn":"Accepting your no is respect; guilt, 'everyone does it' and sulking are pushing past it.","cat":"spot-grooming"},
  {"id":"fw-1302","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"If a stranger online is kind to me, they're safe.\"","myth":{"un":"If a stranger online is kind to me, they must be safe.","re":"Kindness isn't proof, groomers often open with flattery and gifts on purpose.","why":"'Love-bombing' with praise and gifts is a deliberate grooming tactic."},"relearn":"Online kindness isn't proof of safety; watch the pattern, not the flattery.","cat":"spot-grooming"},
  {"id":"fw-1303","type":"strike-rewrite","persona":"Riya","source":"grooming pattern (verified)","hook":"\"A real friend would never keep secrets, so I should share everything.\"","myth":{"un":"If they're a real friend, I should share everything they ask.","re":"Real friends respect your 'no'; demanding 'share everything' is control, not closeness.","why":"Pressure to 'prove' a bond by sharing private things is a grooming red flag."},"relearn":"A real friend respects your no; 'share everything' is control, not friendship.","cat":"spot-grooming"},
  {"id":"fw-1304","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"Grooming only happens to little kids, not teens like me.\"","myth":{"un":"Grooming only happens to young children, not teens.","re":"Teens are heavily targeted; knowing the pattern is what keeps you safe.","why":"The teen years are among the highest-risk for online grooming and exploitation."},"relearn":"Teens are targeted too; learning the grooming pattern protects you.","cat":"spot-grooming"},
  {"id":"fw-1305","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"If I got tricked by a fake profile, that's on me.\"","myth":{"un":"If I get tricked by a fake profile, it's my own fault.","re":"Manipulators are skilled and trick careful people too; being deceived is never your fault.","why":"Groomers deliberately fake ages, photos and stories, the fault is always theirs."},"relearn":"Being tricked by a fake profile is never your fault; the deceiver is to blame.","cat":"spot-grooming"},
  {"id":"fw-1306","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"Someone messaging me late at night just means they like me.\"","myth":{"un":"If someone messages me intensely late at night, it just means they like me.","re":"Odd-hours intensity is a control tactic; real friends don't need you awake at 2 a.m.","why":"Late-night intensity and demands for instant replies are grooming warning signs."},"relearn":"Odd-hours intensity isn't affection; it's a warning sign to watch.","cat":"spot-grooming"},
  {"id":"fw-1307","type":"strike-rewrite","persona":"Veer","source":"grooming pattern (verified)","hook":"\"A guy can't really be groomed or catfished online.\"","myth":{"un":"Boys can't really be groomed or catfished online.","re":"Boys are very much targeted; everyone needs to know the pattern and the plan.","why":"Boys are heavily targeted by online manipulators, especially around money and images."},"relearn":"Boys get groomed and catfished too; everyone needs the pattern and the plan.","cat":"spot-grooming"},
  {"id":"fw-1308","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"A new online friend asking me to keep us secret just means we're close.\"","myth":{"un":"If a new friend asks to keep us secret, it just means we're close.","re":"'Keep it between us' is a control tactic that cuts off the adults who'd help you.","why":"Secrecy is how a groomer isolates a target from people who'd spot the danger."},"relearn":"'Keep us secret' isn't closeness; it's a grooming red flag.","cat":"spot-grooming"},
  {"id":"fw-1309","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"Only careless people fall for online tricks.\"","myth":{"un":"Only careless people fall for online tricks.","re":"Smart, careful people are targeted and tricked too; vigilance, not blame, is the answer.","why":"Manipulators rehearse their tactics and target careful people on purpose."},"relearn":"Careful people get tricked too; it's never proof you were careless.","cat":"spot-grooming"},
  {"id":"fw-1310","type":"strike-rewrite","persona":"Riya","source":"grooming pattern (verified)","hook":"\"If they say they're my age, I can trust them.\"","myth":{"un":"If they say they're my age, I can just trust them.","re":"Anyone can type 'I'm your age', especially on a new, empty account, so verify first.","why":"'I'm your age too' on a brand-new friendless account is a known grooming lie."},"relearn":"A typed 'I'm your age' isn't proof; verify before you trust.","cat":"spot-grooming"},
  {"id":"fw-1311","type":"strike-rewrite","persona":"any","source":"grooming pattern (verified)","hook":"\"Being watchful online means I have to trust no one.\"","myth":{"un":"Staying safe online means trusting no one at all.","re":"You don't need paranoia; learn the pattern and you can enjoy the internet safely.","why":"Knowing the grooming pattern builds proportionate vigilance, not fear of everyone."},"relearn":"Safety isn't 'trust no one'; it's knowing the pattern so you can relax and still be alert.","cat":"spot-grooming"},
  {"id":"fw-1312","type":"role-play","persona":"Riya","source":"grooming pattern (verified)","hook":"A new online 'friend' says: 'Send a pic to prove you trust me.'","setup":"A new online 'friend' says: 'Send a pic to prove you trust me.'","yourLine":[{"text":"Trust isn't a photo. No, and asking again is a red flag.","best":true},{"text":"Umm, maybe later, I'm not sure..."},{"text":"Okay fine, just this once."}],"relearn":"You don't owe anyone a photo; a clear 'no' is the strong move.","cat":"spot-grooming"},
  {"id":"fw-1313","type":"role-play","persona":"Veer","source":"grooming pattern (verified)","hook":"An older 'mentor' says: 'Keep our chats secret from your parents.'","setup":"An older 'mentor' says: 'Keep our chats secret from your parents.'","yourLine":[{"text":"No, I don't keep secret chats. I'll tell my dad about this.","best":true},{"text":"I guess, if you say so..."},{"text":"Fine, but just this one time."}],"relearn":"Refusing secrecy and looping in an adult is exactly the right move.","cat":"spot-grooming"},
  {"id":"fw-1314","type":"role-play","persona":"any","source":"grooming pattern (verified)","hook":"A stranger says: 'You're so mature, let's move to a private app.'","setup":"A stranger says: 'You're so mature, let's move to a private app.'","yourLine":[{"text":"I'm good staying here. Moving to a private app isn't happening.","best":true},{"text":"I dunno, maybe..."},{"text":"Okay, send me the link."}],"relearn":"Holding your ground and staying where adults can see is smart and safe.","cat":"spot-grooming"},
  {"id":"fw-1315","type":"role-play","persona":"any","source":"grooming pattern (verified)","hook":"Someone fishes: 'Which school do you go to, and where do you live?'","setup":"Someone fishes: 'Which school do you go to, and where do you live?'","yourLine":[{"text":"I keep that private with people I just met online.","best":true},{"text":"Uh, around the city centre I think..."},{"text":"Sure, it's near the big market."}],"relearn":"Keeping your school and home private with new contacts is the right call.","cat":"spot-grooming"},
  {"id":"fw-1316","type":"role-play","persona":"Riya","source":"grooming pattern (verified)","hook":"A boyfriend online says: 'If you really liked me you'd send one.'","setup":"A boyfriend online says: 'If you really liked me you'd send one.'","yourLine":[{"text":"Liking you doesn't mean sending pics. That's pressure, not love.","best":true},{"text":"That's not fair... but okay maybe."},{"text":"Fine, you win."}],"relearn":"Naming pressure for what it is, and saying no, is brave and right.","cat":"spot-grooming"},
  {"id":"fw-1317","type":"role-play","persona":"Veer","source":"grooming pattern (verified)","hook":"A 'sponsor' says: 'Free gear, just video-call me privately first.'","setup":"A 'sponsor' says: 'Free gear, just video-call me privately first.'","yourLine":[{"text":"No private call. A real sponsor wouldn't ask for that.","best":true},{"text":"Okay, give me a sec to set it up..."},{"text":"Sure, I really want that gear."}],"relearn":"Turning down a 'private call first' lure protects you from a trap.","cat":"spot-grooming"},
  {"id":"fw-1318","type":"role-play","persona":"any","source":"grooming pattern (verified)","hook":"A late-night chatter snaps: 'Why didn't you reply at 2 a.m.?'","setup":"A late-night chatter snaps: 'Why didn't you reply at 2 a.m.?'","yourLine":[{"text":"I don't owe anyone instant replies, and this feels off.","best":true},{"text":"Sorry, sorry, I was asleep..."},{"text":"I'll keep my phone on next time, promise."}],"relearn":"You never owe instant replies; spotting the pressure is the win.","cat":"spot-grooming"},
  {"id":"fw-1319","type":"role-play","persona":"any","source":"grooming pattern (verified)","hook":"A friend says: 'This older guy I met online wants my address. Should I?'","setup":"A friend says: 'This older guy I met online wants my address. Should I?'","yourLine":[{"text":"No, don't share it, and let's tell a trusted adult together.","best":true},{"text":"Maybe it's fine if he seems nice?"},{"text":"Up to you, I guess."}],"relearn":"Steering a friend away from sharing and toward an adult is real friendship.","cat":"spot-grooming"},
  {"id":"fw-1320","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: what's one small thing you'd check before trusting a new online contact?","prompt":"Lensy: what's one small thing you'd check before trusting a new online contact?","options":["Look for a real, checkable account","Notice if they rush a 'special bond'","See if they respect a 'no'","Just take my time"],"affirm":"Whatever you check, slowing down and watching the pattern is safe. 💛","relearn":"Slowing down and watching the pattern keeps you safe online.","cat":"spot-grooming"},
  {"id":"fw-1321","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: if a chat ever felt 'off' but you couldn't say why, what might you do?","prompt":"Lensy: if a chat ever felt 'off' but you couldn't say why, what might you do?","options":["Tell a trusted adult anyway","Step back and slow the chat","Save the messages","Talk it over with a friend"],"affirm":"That 'off' feeling is worth trusting, and there's no wrong way to act on it. 💛","relearn":"An 'off' feeling is worth trusting; you can always tell an adult.","cat":"spot-grooming"},
  {"id":"fw-1322","type":"reflect","persona":"Riya","source":"grooming pattern (verified)","hook":"Lensy: who's one trusted adult you could go to about a creepy message?","prompt":"Lensy: who's one trusted adult you could go to about a creepy message?","options":["A parent","A teacher","The school counsellor","An older cousin I trust"],"affirm":"Naming even one person means you're never handling it alone. 💛","relearn":"Naming one trusted adult means you never face it alone.","cat":"spot-grooming"},
  {"id":"fw-1323","type":"reflect","persona":"Veer","source":"grooming pattern (verified)","hook":"Lensy: how does it feel to know boys get targeted too and it's never their fault?","prompt":"Lensy: how does it feel to know boys get targeted too and it's never their fault?","options":["Kind of a relief","Less alone","More ready to tell someone","Still processing it"],"affirm":"However it lands, knowing it isn't your fault and you're not alone is what matters. 💛","relearn":"Boys are targeted too, and being tricked is never your fault.","cat":"spot-grooming"},
  {"id":"fw-1324","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: what would you tell a friend who got fooled by a fake profile?","prompt":"Lensy: what would you tell a friend who got fooled by a fake profile?","options":["'It's not your fault'","'Let's tell an adult'","'I've got your back'","'Could've happened to anyone'"],"affirm":"Any of these says the same kind thing: no blame, just support. 💛","relearn":"A friend fooled by a fake profile needs support, not blame.","cat":"spot-grooming"},
  {"id":"fw-1325","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: knowing the grooming pattern, do you feel more in control online?","prompt":"Lensy: knowing the grooming pattern, do you feel more in control online?","options":["Yes, more in control","A bit more ready","Calmer about it","I'll keep learning"],"affirm":"The goal is ready, not scared, and you're getting there. 💛","relearn":"Knowing the grooming pattern leaves you ready, not scared.","cat":"spot-grooming"},
  {"id":"fw-1326","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: what's a green flag that an online friend is actually safe?","prompt":"Lensy: what's a green flag that an online friend is actually safe?","options":["They respect your 'no'","They're fine with family knowing","They never rush you","They take real video calls"],"affirm":"Noticing the green flags too keeps the internet a good place to be. 💛","relearn":"Green flags, like respecting your 'no', mark a safe contact.","cat":"spot-grooming"},
  {"id":"fw-1327","type":"reflect","persona":"any","source":"grooming pattern (verified)","hook":"Lensy: if you say no and they get angry, what does that tell you?","prompt":"Lensy: if you say no and they get angry, what does that tell you?","options":["They didn't respect me","It's a red flag","I was right to say no","Time to step back"],"affirm":"Anger at your 'no' tells you plenty, and trusting that is exactly right. 💛","relearn":"Anger at your 'no' is a red flag worth trusting.","cat":"spot-grooming"},
  {"id":"fw-1328","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match each grooming line to the red flag it really is.","pairs":[{"left":"'Keep us secret'","right":"Cutting off the adults who'd help"},{"left":"'You're so mature'","right":"Flattery to lower your guard"},{"left":"'Move to my private app'","right":"Going where adults can't see"},{"left":"'Send a pic to prove trust'","right":"Boundary-testing pressure"},{"left":"'I'm your age, promise'","right":"A faked-age claim"}],"relearn":"Each line maps to a known grooming tactic, naming it makes it easy to spot.","cat":"spot-grooming"},
  {"id":"fw-1329","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match the worry to who can help.","pairs":[{"left":"A stranger asked for a photo","right":"Tell a trusted adult"},{"left":"Being blackmailed with an image","right":"cybercrime.gov.in / 1930"},{"left":"An under-18 in danger","right":"Childline 1098"},{"left":"A creepy account on the app","right":"Block and report it"},{"left":"Need someone right now","right":"A parent or teacher"}],"relearn":"Matching the worry to the right route means help is always one step away.","cat":"spot-grooming"},
  {"id":"fw-1330","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match the red flag to the safe response.","pairs":[{"left":"'Don't tell your parents'","right":"Tell a parent anyway"},{"left":"'Send your live location'","right":"Keep location off"},{"left":"'Install my secret app'","right":"Stay where adults can see"},{"left":"'Prove you trust me with a pic'","right":"Say a clear no"},{"left":"A brand-new empty account","right":"Verify before trusting"}],"relearn":"For every red-flag line there's a calm, safe response, and now you know them.","cat":"spot-grooming"},
  {"id":"fw-1331","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match the catfish tell to what it reveals.","pairs":[{"left":"Stock-model perfect photos","right":"Possibly a stolen identity"},{"left":"Never does a live call","right":"Avoiding being seen"},{"left":"Account made last week","right":"No real history"},{"left":"No genuine friends on it","right":"A fake profile"},{"left":"Story keeps changing","right":"Made-up details"}],"relearn":"Each tell points to the same thing: this profile may not be real.","cat":"spot-grooming"},
  {"id":"fw-1332","type":"match","persona":"Riya","source":"grooming pattern (verified)","hook":"Match the pressure line to why it's coercion, not love.","pairs":[{"left":"'If you liked me you'd send it'","right":"Twisting love into proof"},{"left":"'Everyone does it'","right":"A myth to push you"},{"left":"'Keep us secret or it's over'","right":"A threat, not closeness"},{"left":"'Don't be a baby'","right":"Shaming you past a 'no'"},{"left":"'I'll be upset if you refuse'","right":"Guilt as a weapon"}],"relearn":"Real care never needs guilt or threats, naming each one helps you hold your boundary.","cat":"spot-grooming"},
  {"id":"fw-1333","type":"match","persona":"Veer","source":"grooming pattern (verified)","hook":"Match the lure to the trap behind it.","pairs":[{"left":"'Free credits, video-call me first'","right":"A private-contact hook"},{"left":"'Double your money'","right":"A too-good scam"},{"left":"'Hide it from your parents'","right":"Cutting off help"},{"left":"'You're my favourite, our secret'","right":"Flattery plus secrecy"},{"left":"'Verify with a face video'","right":"Getting an image of you"}],"relearn":"Behind every 'free' lure is a trap, spotting the pattern keeps you out of it.","cat":"spot-grooming"},
  {"id":"fw-1334","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match real friendship to its opposite, the trap.","pairs":[{"left":"Gets to know you slowly","right":"Rushes a 'soulmate' bond"},{"left":"Open with your family","right":"Demands total secrecy"},{"left":"Respects your 'no'","right":"Pushes past your 'no'"},{"left":"Fine when you log off","right":"Angry if you don't reply"},{"left":"Likes your real friends","right":"Isolates you from them"}],"relearn":"Lining up the trap against real friendship makes the warning signs obvious.","cat":"spot-grooming"},
  {"id":"fw-1335","type":"match","persona":"any","source":"grooming pattern (verified)","hook":"Match the green flag to why it's reassuring.","pairs":[{"left":"Happy to video-call live","right":"Likely who they claim"},{"left":"Takes 'no' easily","right":"Respects your boundaries"},{"left":"Never rushes you","right":"No pressure tactics"},{"left":"Okay with adults knowing","right":"Nothing to hide"},{"left":"Has a real, checkable life","right":"A genuine person"}],"relearn":"Green flags are worth spotting too, they tell you when a contact is probably safe.","cat":"spot-grooming"},
  {"id":"fw-1336","type":"branch","persona":"any","source":"grooming pattern (verified)","hook":"A 'friend' says: 'Move to my private app, just us.'","debrief":"Secret apps hide danger; stay visible, tell an adult.","relearn":"Stay visible; secret apps hide danger.","options":[{"text":"Stay here and tell a trusted adult","consequence":"You stay visible and the move-it-private trick fails.","best":true},{"text":"Switch to the private app","consequence":"Now you're where no adult can see, which is what they wanted."},{"text":"Block them, tell no one","consequence":"Safer, but the adult who could help stays out of the loop."}],"cat":"spot-grooming"},
  {"id":"fw-1337","type":"branch","persona":"Riya","source":"grooming pattern (verified)","hook":"An online boyfriend keeps demanding a private photo.","debrief":"A clear no plus an adult is right; sending never ends it.","relearn":"A clear no beats sending; a pic never stops it.","options":[{"text":"Say a clear no, tell an adult it's pushy","consequence":"A firm no plus an adult ends it, no photo sent.","best":true},{"text":"Send one so he stops","consequence":"A sent photo can't be unsent, and the pressure usually grows."},{"text":"Stall and hope he drops it","consequence":"Stalling rarely works; the pressure keeps coming."}],"cat":"spot-grooming"},
  {"id":"fw-1338","type":"branch","persona":"Veer","source":"grooming pattern (verified)","hook":"A 'sponsor' offers free gear if you 'video-call privately first'.","debrief":"A real sponsor never needs a private call; decline, report.","relearn":"No real sponsor needs a private call; decline.","options":[{"text":"Decline and report the account","consequence":"You skip the lure and flag them.","best":true},{"text":"Do the private call for the gear","consequence":"A 'private call first' is the lure, not the deal, a known trap."},{"text":"Ask a friend to call instead","consequence":"You'd pull a friend into the same trap."}],"cat":"spot-grooming"},
  {"id":"fw-1339","type":"branch","persona":"any","source":"grooming pattern (verified)","hook":"A stranger you met yesterday calls you their 'soulmate'.","debrief":"A rushed 'special bond' is a classic grooming tactic.","relearn":"A rushed 'soulmate' is the warning; slow down.","options":[{"text":"Slow right down, watch for red flags","consequence":"Slowing down lets the rush tactic show itself.","best":true},{"text":"Pour your heart out","consequence":"A one-day 'soulmate' is a rush tactic; opening up now is risky."},{"text":"Send a selfie to seal it","consequence":"A photo to a near-stranger can't be unsent."}],"cat":"spot-grooming"},
  {"id":"fw-1340","type":"branch","persona":"any","source":"grooming pattern (verified)","hook":"A creepy account messages you intensely at 2 a.m.","debrief":"Block, report, tell an adult; you owe no 2 a.m. reply.","relearn":"Block, report, tell an adult; you owe no reply.","options":[{"text":"Block, report, then tell an adult","consequence":"Blocking cuts contact and the adult keeps you covered.","best":true},{"text":"Reply so they don't get angry","consequence":"Replying rewards the pressure and keeps the chat going."},{"text":"Just mute and ignore it","consequence":"Muting hides it; reporting and an adult stop it."}],"cat":"spot-grooming"},
  {"id":"fw-1341","type":"branch","persona":"any","source":"grooming pattern (verified)","hook":"Someone asks: 'What time are you home alone after school?'","debrief":"Never share when you're home alone; it's a red flag.","relearn":"Don't share home-alone times; it's a red flag.","options":[{"text":"Don't answer, stay vague, flag it","consequence":"Staying vague keeps your routine private.","best":true},{"text":"Tell them, they seem friendly","consequence":"Sharing when you're home alone hands a stranger a real risk."},{"text":"Joke and change the subject","consequence":"Better than answering, but still worth flagging."}],"cat":"spot-grooming"},
  {"id":"fw-1342","type":"branch","persona":"any","source":"grooming pattern (verified)","hook":"A friend says an older online 'mentor' wants their address.","debrief":"Steer a friend away from sharing and toward an adult.","relearn":"Steer a friend from sharing toward an adult.","options":[{"text":"Tell them no, find an adult together","consequence":"The address stays put and your friend isn't alone.","best":true},{"text":"Say it's their call, stay out","consequence":"Staying out leaves your friend at real risk."},{"text":"Say it's fine if he seems nice","consequence":"'Seems nice' is exactly how groomers get an address."}],"cat":"spot-grooming"},
  {"id":"fw-1343","type":"branch","persona":"Riya","source":"grooming pattern (verified)","hook":"A 'helpful senior' offers to fix your grade, kept secret.","debrief":"A favour needing secrecy is a red flag; tell a teacher.","relearn":"A favour needing secrecy is a red flag; tell a teacher.","options":[{"text":"Say no, mention it to a teacher","consequence":"You refuse it; a teacher can watch him.","best":true},{"text":"Take the deal, you need marks","consequence":"Trading secrecy for a 'favour' is how grooming starts."},{"text":"Agree, plan to back out later","consequence":"Going along briefly gives them a hold over you."}],"cat":"spot-grooming"},
  {"id":"fw-1350","cat":"think-before-share","type":"branch","hook":"A guy you met online says, 'Send a pic or I'll think you're shy.'","options":[{"text":"Say no; you don't owe a stranger a photo","consequence":"You keep control and watch how he reacts to a 'no'.","outcome":"boundary","best":true},{"text":"Send a 'safe' one so he stays interested","consequence":"A stranger pushing for pics is the red flag; 'no' is enough."}],"debrief":"You never owe anyone a photo, online or off.","relearn":"You don't owe a stranger a photo; pressure to send is the red flag.","persona":"any","source":"pressure / strangers"},
  {"id":"fw-1351","cat":"think-before-share","type":"branch","hook":"Your group is sharing a meme with a classmate's private screenshot in it.","options":[{"text":"Don't forward it; ask them to take it down","consequence":"You stop the spread instead of adding to it.","outcome":"protect","best":true},{"text":"Forward it; it's spreading anyway","consequence":"Each forward can be abuse; 'already spreading' isn't a reason."}],"debrief":"Not forwarding a private image protects them.","relearn":"Forwarding a private image can itself be abuse; you can refuse.","persona":"any","source":"never forward"},
  {"id":"fw-1352","cat":"think-before-share","type":"branch","hook":"A reel trend wants you to film your home street and daily timing.","options":[{"text":"Do the trend without the location details","consequence":"You join in without handing strangers your routine.","outcome":"private","best":true},{"text":"Post it all so the reel feels real","consequence":"Live location and routine in posts can reach the wrong people."}],"debrief":"A trend isn't worth broadcasting where to find you.","relearn":"Keep your live location and daily routine out of public posts.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1353","cat":"think-before-share","type":"branch","hook":"Your boyfriend says, 'If you trusted me you'd send one photo.'","options":[{"text":"Tell him trust isn't a photo; hold your no","consequence":"You see whether he respects you or wants leverage.","outcome":"respect","best":true},{"text":"Send it to show you trust him","consequence":"'Prove it with a photo' is coercion, not trust."}],"debrief":"Real trust never needs a photo as proof.","relearn":"'Prove you trust me' is coercion, not love; 'no' is always valid.","persona":"Riya","source":"consent / pressure"},
  {"id":"fw-1354","cat":"think-before-share","type":"branch","hook":"A crush asks for your live location 'so we can meet up sometime'.","options":[{"text":"Share a general area, not your live location","consequence":"You stay friendly without saying where you are now.","outcome":"safe","best":true},{"text":"Turn on live location so it feels real","consequence":"Live location lets anyone track you; a general area is plenty."}],"debrief":"You can be open without being trackable.","relearn":"You can stay friendly without sharing your exact live location.","persona":"any","source":"footprint / location"},
  {"id":"fw-1355","cat":"think-before-share","type":"branch","hook":"Someone DMs, 'Send a photo and I'll add you to the cool group chat.'","options":[{"text":"Pass; a photo as an entry fee is a red flag","consequence":"You spot the trade for what it is and stay out.","outcome":"boundary","best":true},{"text":"Send it; you really want in","consequence":"A group that charges photos to join is testing you."}],"debrief":"If belonging costs a private photo, skip it.","relearn":"A photo as the price to 'fit in' is boundary-testing, not friendship.","persona":"Veer","source":"peer pressure"},
  {"id":"fw-1356","cat":"think-before-share","type":"branch","hook":"You wrote an angry post about a teacher; your finger's over 'Post'.","options":[{"text":"Save it as a draft and reread tomorrow","consequence":"You give future-you a vote before it's public.","outcome":"wise","best":true},{"text":"Post it now while you're fired up","consequence":"Heated posts can resurface; a pause protects future-you."}],"debrief":"A pause can save you a post you can't unsend.","relearn":"Post with future-you in mind; a pause beats a post you'll regret.","persona":"any","source":"footprint"},
  {"id":"fw-1357","cat":"think-before-share","type":"branch","hook":"A 'modelling scout' DMs asking for full-body photos for your 'portfolio'.","options":[{"text":"Don't send; check it with an adult first","consequence":"You slow down a flattering, urgent request.","outcome":"verify","best":true},{"text":"Send them; this is your big break","consequence":"A stranger wanting body photos fast is a known trick."}],"debrief":"A real offer survives you checking it first.","relearn":"'Opportunities' wanting photos fast are a known trick; verify first.","persona":"any","source":"pressure / footprint"},
  {"id":"fw-1358","cat":"think-before-share","type":"branch","hook":"A close friend dares you to post your phone number 'for a laugh'.","options":[{"text":"Refuse; your number isn't a public dare","consequence":"You keep your contacts off the open internet.","outcome":"private","best":true},{"text":"Post it; it's just a joke","consequence":"A public number invites spam and strangers."}],"debrief":"You can sit out a dare that posts your details.","relearn":"You can opt out of dares that put your private details in public.","persona":"any","source":"peer pressure / footprint"},
  {"id":"fw-1359","cat":"think-before-share","type":"branch","hook":"Someone you've only chatted with online wants a photo in your school uniform.","options":[{"text":"Don't send; a uniform can reveal your school","consequence":"You keep where-you-study out of their hands.","outcome":"safe","best":true},{"text":"Send it; it's just your uniform","consequence":"A uniform shows your school and area; they don't need it."}],"debrief":"Photos can leak where you are without you meaning to.","relearn":"A uniform photo can reveal your school; you don't owe a stranger that.","persona":"any","source":"footprint / strangers"},
  {"id":"fw-1360","cat":"think-before-share","type":"branch","hook":"Your partner wants your account password 'because we share everything'.","options":[{"text":"Keep your password yours; closeness isn't a login","consequence":"You stay in control of your own account.","outcome":"private","best":true},{"text":"Hand it over to prove you've nothing to hide","consequence":"A password is yours alone; needing it is control."}],"debrief":"Sharing a password isn't proof of love.","relearn":"Your password is yours; being asked for it is control, not closeness.","persona":"any","source":"consent / privacy"},
  {"id":"fw-1361","cat":"think-before-share","type":"branch","hook":"A chat app offers to 'auto-back-up' your photos to a public album.","options":[{"text":"Turn it off and keep your album private","consequence":"You stop photos defaulting to where anyone sees.","outcome":"private","best":true},{"text":"Leave it on; the default is fine","consequence":"Defaults can make things public; check first."}],"debrief":"Check what an app shares before it does.","relearn":"App defaults can make your photos public; check and keep them private.","persona":"any","source":"footprint / settings"},
  {"id":"fw-1362","cat":"think-before-share","type":"branch","hook":"You're about to tag your exact location at a party full of strangers.","options":[{"text":"Post it later, without the live tag","consequence":"You share the fun, not where you are now.","outcome":"safe","best":true},{"text":"Tag it live so everyone knows where it is","consequence":"A live tag tells strangers where you are tonight."}],"debrief":"You can post the memory without the map pin.","relearn":"Post after, without a live tag; don't broadcast where you are now.","persona":"any","source":"footprint / location"},
  {"id":"fw-1363","cat":"think-before-share","type":"branch","hook":"A senior offers to 'fix' a bad photo of you if you send three more first.","options":[{"text":"Decline; sending more photos isn't a fix","consequence":"You don't hand over more to undo one.","outcome":"boundary","best":true},{"text":"Send the three so they help you","consequence":"'Send more and I'll help' only grows what they hold."}],"debrief":"More photos never solve a photo problem.","relearn":"Sending more images never fixes things; it only grows the risk.","persona":"any","source":"pressure"},
  {"id":"fw-1364","cat":"think-before-share","type":"branch","hook":"Your story shows your house number; a follower asks where it is.","options":[{"text":"Delete the story; don't share the address","consequence":"You close a gap a stranger just tried.","outcome":"private","best":true},{"text":"Tell them; they seem friendly","consequence":"A friendly tone doesn't make your address safe to share."}],"debrief":"If a post leaks your address, take it down.","relearn":"Don't share your home address; a friendly ask isn't a safe ask.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1365","cat":"think-before-share","type":"branch","hook":"A new follower asks you to switch to a disappearing-photo app to 'send pics'.","options":[{"text":"Stay put; 'disappearing' photos can still be saved","consequence":"You don't trust a feature that can't protect you.","outcome":"safe","best":true},{"text":"Switch over; disappearing means safe","consequence":"Screenshots beat disappearing photos; the switch is the flag."}],"debrief":"'It disappears' is a promise an app can't keep.","relearn":"Disappearing photos can be screenshotted; the push to switch is the flag.","persona":"any","source":"permanence / strangers"},
  {"id":"fw-1366","cat":"think-before-share","type":"branch","hook":"Your cousin asks for your OTP 'just to log in to your account quickly'.","options":[{"text":"Never share an OTP; offer to help another way","consequence":"You keep the one code that protects you.","outcome":"private","best":true},{"text":"Send the OTP; it's only your cousin","consequence":"An OTP is never shared; that's how accounts get taken."}],"debrief":"An OTP is for you alone, no exceptions.","relearn":"Never share an OTP with anyone; it's the key to your account.","persona":"any","source":"settings / privacy"},
  {"id":"fw-1367","cat":"think-before-share","type":"branch","hook":"A 'fan account' wants your school photos for a 'tribute edit' of you.","options":[{"text":"Say no; you don't know who's behind it","consequence":"You keep your photos off an account you can't verify.","outcome":"verify","best":true},{"text":"Send them; a tribute sounds sweet","consequence":"An unverified 'fan account' is a soft way to collect photos."}],"debrief":"Flattery is an easy mask for collecting images.","relearn":"An unverifiable 'fan account' asking for your photos is a red flag.","persona":"any","source":"flattery / footprint"},
  {"id":"fw-1368","cat":"think-before-share","type":"branch","hook":"You could repost a friend's embarrassing private video for easy likes.","options":[{"text":"Don't repost; ask first or leave it","consequence":"You choose your friend over a spike of likes.","outcome":"protect","best":true},{"text":"Repost it; the likes will be huge","consequence":"Their private video isn't yours; likes aren't worth the harm."}],"debrief":"Someone's private clip isn't your content to post.","relearn":"A private clip isn't yours to repost; ask first or leave it.","persona":"any","source":"never forward"},
  {"id":"fw-1369","cat":"think-before-share","type":"branch","hook":"A gaming friend wants a selfie 'to prove you're a real girl' before adding you.","options":[{"text":"Refuse; you don't prove who you are with a photo","consequence":"You spot a 'proof' demand for the pressure it is.","outcome":"boundary","best":true},{"text":"Send a selfie so they add you","consequence":"'Prove it with a photo' is pressure, not a fair rule."}],"debrief":"You never verify yourself with a private photo.","relearn":"You don't owe anyone a photo to 'prove' who you are.","persona":"any","source":"pressure / strangers"},
  {"id":"fw-1370","cat":"think-before-share","type":"branch","hook":"Someone offers free game credits for a photo of you holding a sign with your name.","options":[{"text":"Skip it; a named photo is worth more than credits","consequence":"You don't trade an identifiable photo for a freebie.","outcome":"safe","best":true},{"text":"Send it; free credits are free","consequence":"A named photo is what scammers want; not worth it."}],"debrief":"A 'free' offer wanting your face and name isn't free.","relearn":"Don't trade an identifiable photo for freebies; that's what scams want.","persona":"Veer","source":"footprint / scam"},
  {"id":"fw-1371","cat":"think-before-share","type":"branch","hook":"You're tempted to post a rant with screenshots of a private friend chat.","options":[{"text":"Keep the chat private; talk it out offline","consequence":"You handle it without making it permanent.","outcome":"wise","best":true},{"text":"Post the screenshots so people see your side","consequence":"Public screenshots of a private chat can't be unsent."}],"debrief":"A private chat posted in anger can't be taken back.","relearn":"Don't post private chats in anger; it's permanent and can rebound.","persona":"any","source":"footprint"},
  {"id":"fw-1372","cat":"think-before-share","type":"branch","hook":"A match says everyone there 'sends one pic to be taken seriously'.","options":[{"text":"Don't; 'everyone does it' is pressure","consequence":"You see the 'everyone' line as the script it is.","outcome":"boundary","best":true},{"text":"Send one to be taken seriously","consequence":"'Everyone sends one' is a pressure script; 'no' is fine."}],"debrief":"'Everyone does it' is the oldest pressure line there is.","relearn":"'Everyone sends one' is pressure, not fact; 'no' is always okay.","persona":"any","source":"myth / pressure"},
  {"id":"fw-1373","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I crop my face out, the photo is safe to send.\"","myth":{"un":"If I crop my face out, the photo is safe to send.","re":"A cropped photo can still be traced to you and can't be unsent.","why":"Background and details still identify you; sending loses control."},"relearn":"Cropping your face out doesn't make a photo safe; sending still loses control.","persona":"any","source":"permanence"},
  {"id":"fw-1374","cat":"think-before-share","type":"strike-rewrite","hook":"\"It's private if I use a disappearing-message app.\"","myth":{"un":"It's private if I use a disappearing-message app.","re":"Disappearing photos can be screenshotted before they vanish.","why":"The app can't stop the other person saving it."},"relearn":"Disappearing-message apps aren't private; photos can be screenshotted.","persona":"any","source":"permanence"},
  {"id":"fw-1375","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I don't send a photo, my partner will leave me.\"","myth":{"un":"If I don't send a photo, my partner will leave me.","re":"A partner who'd leave over a photo 'no' wasn't respecting you.","why":"Real care never makes a photo the price of staying."},"relearn":"A partner who'd leave over a photo 'no' isn't respecting you.","persona":"Riya","source":"consent / pressure"},
  {"id":"fw-1376","cat":"think-before-share","type":"strike-rewrite","hook":"\"Posting my daily location is fine, my account is small.\"","myth":{"un":"Posting my daily location is fine; my account is small.","re":"A small account can still be seen, saved and shared by anyone.","why":"Posts travel beyond your followers, who can be strangers."},"relearn":"A small account isn't private; keep your live location off your posts.","persona":"any","source":"footprint"},
  {"id":"fw-1377","cat":"think-before-share","type":"strike-rewrite","hook":"\"Forwarding a leaked photo isn't a big deal, I didn't take it.\"","myth":{"un":"Forwarding a leaked photo isn't a big deal; I didn't take it.","re":"Forwarding a private image spreads harm and can itself be abuse.","why":"Each share widens it; not taking it doesn't make it okay."},"relearn":"Forwarding a leaked private image spreads harm and can itself be abuse.","persona":"any","source":"never forward"},
  {"id":"fw-1378","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I send mine first, they'll have to send one back.\"","myth":{"un":"If I send mine first, they'll have to send one back.","re":"Sending first just gives your photo away; no one owes you one.","why":"You can't control them, but your photo is out of your hands."},"relearn":"Sending first doesn't earn a photo back; it just gives yours away.","persona":"any","source":"permanence / pressure"},
  {"id":"fw-1379","cat":"think-before-share","type":"strike-rewrite","hook":"\"A photo I sent ages ago can't come back to bite me.\"","myth":{"un":"A photo I sent ages ago can't come back to bite me.","re":"Old photos can be saved and resurface years later.","why":"Whoever has a copy can repost it whenever they choose."},"relearn":"Old photos can resurface years later; time doesn't make them disappear.","persona":"any","source":"footprint"},
  {"id":"fw-1380","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I trust someone fully, sending a photo is no risk.\"","myth":{"un":"If I trust someone fully, sending a photo is no risk.","re":"Trusted people still get hacked, break up, or lose a phone.","why":"Once sent, the photo's safety isn't up to trust alone."},"relearn":"Even with full trust, a sent photo carries risk you can't control.","persona":"any","source":"permanence"},
  {"id":"fw-1381","cat":"think-before-share","type":"strike-rewrite","hook":"\"Saying 'no' to a photo makes me a difficult person.\"","myth":{"un":"Saying 'no' to a photo makes me difficult.","re":"Saying 'no' to a photo is a healthy boundary, not difficult.","why":"The person pushing past your 'no' is the problem."},"relearn":"Saying 'no' to a photo is a healthy boundary, not being difficult.","persona":"any","source":"consent"},
  {"id":"fw-1382","cat":"think-before-share","type":"strike-rewrite","hook":"\"Adding my school and class to my bio just helps people find me.\"","myth":{"un":"Adding my school and class to my bio just helps people find me.","re":"It also helps strangers know where you'll be each day.","why":"School plus timetable tells anyone where to wait for you."},"relearn":"Don't put your school and class in a public bio; it shows strangers where you are.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1383","cat":"think-before-share","type":"strike-rewrite","hook":"\"If I delete the chat, the photo I sent is gone too.\"","myth":{"un":"If I delete the chat, the photo I sent is gone too.","re":"Deleting your copy doesn't delete the one they saved.","why":"You can't delete what's on someone else's phone."},"relearn":"Deleting your chat doesn't delete the copy on the other person's phone.","persona":"any","source":"permanence"},
  {"id":"fw-1384","cat":"think-before-share","type":"sort","hook":"Sort: keeps your footprint safe, or grows your risk?","items":[{"id":"a","text":"Private account, friends you know"},{"id":"b","text":"Posting your live location at school"},{"id":"c","text":"Pausing before an angry post"},{"id":"d","text":"Sending a photo to 'prove' trust"},{"id":"e","text":"Turning off who can DM you"},{"id":"f","text":"Putting your number in your bio"}],"bins":[{"id":"safe","label":"Keeps you safe","valence":"pos"},{"id":"risk","label":"Grows your risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Private settings and a pause keep you safe; over-sharing grows risk.","persona":"any","source":"footprint"},
  {"id":"fw-1385","cat":"think-before-share","type":"sort","hook":"Sort: a valid reason to send, or pressure to resist?","items":[{"id":"a","text":"\"If you loved me you'd send it\""},{"id":"b","text":"You want to and feel safe (your call)"},{"id":"c","text":"\"Everyone in class has sent one\""},{"id":"d","text":"\"Send it or I'll spread rumours\""},{"id":"e","text":"You just don't feel like it"},{"id":"f","text":"\"It'll disappear, so it's safe\""}],"bins":[{"id":"valid","label":"Your valid choice","valence":"pos"},{"id":"resist","label":"Pressure to resist","valence":"neg"}],"key":{"a":"resist","b":"valid","c":"resist","d":"resist","e":"valid","f":"resist"},"relearn":"Your honest choice is valid; guilt, threats and 'it's safe' are pressure.","persona":"Riya","source":"consent / pressure"},
  {"id":"fw-1386","cat":"think-before-share","type":"sort","hook":"Sort: respects your boundary, or crosses it?","items":[{"id":"a","text":"A partner who hears 'no' and drops it"},{"id":"b","text":"Someone asking again after 'no'"},{"id":"c","text":"A friend who never pressures you"},{"id":"d","text":"Someone guilt-tripping you to send"},{"id":"e","text":"A crush who says 'no problem'"},{"id":"f","text":"Threatening to leave unless you send"}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"cross","label":"Crosses the line","valence":"neg"}],"key":{"a":"respect","b":"cross","c":"respect","d":"cross","e":"respect","f":"cross"},"relearn":"Respect means dropping it at 'no'; asking again, guilt and threats cross it.","persona":"any","source":"respect"},
  {"id":"fw-1387","cat":"think-before-share","type":"sort","hook":"Sort: safe to post publicly, or keep private?","items":[{"id":"a","text":"A sunset photo you liked"},{"id":"b","text":"Your live location right now"},{"id":"c","text":"A drawing you made"},{"id":"d","text":"Your home address"},{"id":"e","text":"Your favourite song"},{"id":"f","text":"Your daily school route"}],"bins":[{"id":"public","label":"Fine to post","valence":"pos"},{"id":"private","label":"Keep private","valence":"neg"}],"key":{"a":"public","b":"private","c":"public","d":"private","e":"public","f":"private"},"relearn":"Hobbies are fine to share; location, address and routine stay private.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1388","cat":"think-before-share","type":"sort","hook":"Sort: a green-flag share habit, or a red-flag one?","items":[{"id":"a","text":"Asking before posting a friend's photo"},{"id":"b","text":"Forwarding a private pic 'as a joke'"},{"id":"c","text":"Pausing before a heated post"},{"id":"d","text":"Spreading a private chat screenshot"},{"id":"e","text":"Keeping a friend's secret offline"},{"id":"f","text":"Tagging a friend's location uninvited"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Asking and pausing are green flags; forwarding and tagging without asking are red.","persona":"any","source":"share habits"},
  {"id":"fw-1389","cat":"think-before-share","type":"sort","hook":"Sort: who controls your photo after you tap send?","items":[{"id":"a","text":"They can screenshot it"},{"id":"b","text":"You can delete their copy"},{"id":"c","text":"They can forward it"},{"id":"d","text":"You decide who else sees it"},{"id":"e","text":"It can resurface years later"},{"id":"f","text":"You can guarantee it stays private"}],"bins":[{"id":"true","label":"True after sending","valence":"pos"},{"id":"false","label":"Not true","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"After sending you lose control; they can screenshot, forward and keep it.","persona":"any","source":"permanence"},
  {"id":"fw-1390","cat":"think-before-share","type":"sort","hook":"Sort: a real reason to keep a photo private, or a pressure line?","items":[{"id":"a","text":"\"Once it's out, I can't take it back\""},{"id":"b","text":"\"If you don't send it, you don't love me\""},{"id":"c","text":"\"I decide what's on my phone\""},{"id":"d","text":"\"Don't be boring, just send it\""},{"id":"e","text":"\"A screenshot is all it takes\""},{"id":"f","text":"\"Everyone's seen worse anyway\""}],"bins":[{"id":"reason","label":"Real reason","valence":"pos"},{"id":"line","label":"Pressure line","valence":"neg"}],"key":{"a":"reason","b":"line","c":"reason","d":"line","e":"reason","f":"line"},"relearn":"Permanence and your choice are real; guilt and 'don't be boring' are pressure.","persona":"any","source":"permanence / pressure"},
  {"id":"fw-1391","cat":"think-before-share","type":"sort","hook":"Sort: smart before you post, or risky?","items":[{"id":"a","text":"Checking who can see a post"},{"id":"b","text":"Posting your exam centre and time"},{"id":"c","text":"Asking 'would future-me be okay?'"},{"id":"d","text":"Live-streaming your bedroom layout"},{"id":"e","text":"Removing location data first"},{"id":"f","text":"Telling a stranger where you live"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risky","label":"Risky move","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"Checking who sees it and removing location are smart; broadcasting where you are is risky.","persona":"any","source":"footprint"},
  {"id":"fw-1392","cat":"think-before-share","type":"sort","hook":"Sort: respects 'not mine to share', or breaks it?","items":[{"id":"a","text":"Asking before reposting their photo"},{"id":"b","text":"Sharing a classmate's private pic"},{"id":"c","text":"Reporting a leaked image"},{"id":"d","text":"Passing a photo around a group"},{"id":"e","text":"Deleting a pic sent by mistake"},{"id":"f","text":"Posting a friend's DM to mock them"}],"bins":[{"id":"respect","label":"Respects it","valence":"pos"},{"id":"breaks","label":"Breaks it","valence":"neg"}],"key":{"a":"respect","b":"breaks","c":"respect","d":"breaks","e":"respect","f":"breaks"},"relearn":"Asking, reporting and deleting respect others' images; sharing and mocking break that.","persona":"any","source":"never forward"},
  {"id":"fw-1393","cat":"think-before-share","type":"sort","hook":"Sort: locks your account down, or opens it up?","items":[{"id":"a","text":"Strong password with two-factor on"},{"id":"b","text":"Sharing your login with a friend"},{"id":"c","text":"Setting who can tag and DM you"},{"id":"d","text":"Leaking your OTP by accident"},{"id":"e","text":"Reviewing old posts for location"},{"id":"f","text":"A public profile with your number"}],"bins":[{"id":"locked","label":"Locks it down","valence":"pos"},{"id":"open","label":"Opens it up","valence":"neg"}],"key":{"a":"locked","b":"open","c":"locked","d":"open","e":"locked","f":"open"},"relearn":"Strong passwords and controls lock you down; sharing logins and leaks open you up.","persona":"any","source":"settings / privacy"},
  {"id":"fw-1394","cat":"think-before-share","type":"sort","hook":"Sort: their problem, or not your fault?","items":[{"id":"a","text":"They kept pushing after your 'no'"},{"id":"b","text":"You were tricked into trusting them"},{"id":"c","text":"They forwarded your photo"},{"id":"d","text":"You felt flattered and replied"},{"id":"e","text":"They threatened you for a photo"},{"id":"f","text":"You sent one under heavy pressure"}],"bins":[{"id":"theirs","label":"Their problem","valence":"pos"},{"id":"notfault","label":"Not your fault","valence":"neutral"}],"key":{"a":"theirs","b":"notfault","c":"theirs","d":"notfault","e":"theirs","f":"notfault"},"relearn":"Pushing, forwarding and threatening are on them; being tricked or pressured is never your fault.","persona":"Counsellor","source":"no-blame"},
  {"id":"fw-1395","cat":"think-before-share","type":"role-play","hook":"A crush keeps asking for a photo after you already said no.","setup":"Hold your boundary. Say:","yourLine":[{"text":"\"I already said no. Asking again won't change it.\"","best":true},{"text":"\"Why do you keep asking...\""}],"relearn":"A repeated 'no' needs no new excuse; 'I already said no' is enough.","persona":"Riya","source":"boundary voice"},
  {"id":"fw-1396","cat":"think-before-share","type":"role-play","hook":"A friend wants you to post their ex's private photo to 'get back at them'.","setup":"Refuse it. Say:","yourLine":[{"text":"\"No. I'm not posting anyone's private photo, ever.\"","best":true},{"text":"\"Maybe just this once...\""}],"relearn":"Refusing to post a private photo protects them and you.","persona":"any","source":"never forward"},
  {"id":"fw-1397","cat":"think-before-share","type":"role-play","hook":"Someone you matched with says 'send a pic or this is going nowhere'.","setup":"Name the pressure. Say:","yourLine":[{"text":"\"If a photo's the price to talk to me, it's going nowhere.\"","best":true},{"text":"\"Okay, let me find one...\""}],"relearn":"You don't have to pay a photo to keep someone talking to you.","persona":"any","source":"boundary voice"},
  {"id":"fw-1398","cat":"think-before-share","type":"role-play","hook":"A group chat is daring everyone to drop their live location.","setup":"Opt out calmly. Say:","yourLine":[{"text":"\"I'm out on this, I keep my live location off.\"","best":true},{"text":"\"Fine, here's mine...\""}],"relearn":"You can opt out of a location dare in one calm line.","persona":"Veer","source":"boundary voice"},
  {"id":"fw-1399","cat":"think-before-share","type":"role-play","hook":"A partner says 'everyone in a relationship sends pics, what's your problem?'","setup":"Push back. Say:","yourLine":[{"text":"\"Not everyone does, and I don't want to. That's enough.\"","best":true},{"text":"\"I guess I'm just weird then...\""}],"relearn":"'Not everyone does, and I don't want to' is a complete answer.","persona":"Riya","source":"boundary voice"},
  {"id":"fw-1400","cat":"think-before-share","type":"role-play","hook":"A friend asks for your account password 'so we can post together'.","setup":"Keep it yours. Say:","yourLine":[{"text":"\"I don't share my password. Let's post from yours.\"","best":true},{"text":"\"Umm, okay, it's...\""}],"relearn":"'I don't share my password' is a clean, friendly boundary.","persona":"any","source":"boundary voice"},
  {"id":"fw-1401","cat":"think-before-share","type":"role-play","hook":"Someone online asks for your home address 'to send you a surprise gift'.","setup":"Decline. Say:","yourLine":[{"text":"\"Thanks, but I don't share my address online.\"","best":true},{"text":"\"Aw okay, it's near...\""}],"relearn":"You can decline an online gift without sharing your address.","persona":"any","source":"boundary voice"},
  {"id":"fw-1402","cat":"think-before-share","type":"role-play","hook":"A senior pressures you to forward a junior's embarrassing photo to the class group.","setup":"Refuse it. Say:","yourLine":[{"text":"\"No. Spreading that would hurt them, count me out.\"","best":true},{"text":"\"If everyone's seeing it anyway...\""}],"relearn":"Refusing to forward an embarrassing photo protects the person in it.","persona":"any","source":"boundary voice"},
  {"id":"fw-1403","cat":"think-before-share","type":"reflect","hook":"Before you post today, what's a good question to ask yourself?","prompt":"Pick a check that feels right:","options":["\"Would future-me be okay with this?\"","\"Does this show where I am right now?\"","\"Is this mine to share?\""],"affirm":"Any of these is a great pause to take before you share. 💛","relearn":"A quick pause before posting protects future-you.","persona":"any","source":"reflect"},
  {"id":"fw-1404","cat":"think-before-share","type":"reflect","hook":"When someone pressures you for a photo, what reminds you 'no' is enough?","prompt":"Choose what you'd hold onto:","options":["\"I don't owe anyone a photo.\"","\"Pressure is the red flag, not me.\"","\"'No' is a full answer.\""],"affirm":"Whatever you picked, your 'no' stands and needs no excuse. 💛","relearn":"Your 'no' to a photo is always enough on its own.","persona":"any","source":"reflect"},
  {"id":"fw-1405","cat":"think-before-share","type":"reflect","hook":"What helps you keep your footprint yours?","prompt":"Pick a habit to keep:","options":["Checking who can see a post","Keeping live location off","Pausing before posting upset"],"affirm":"Any of these protects future-you. Small habits keep your footprint yours.","relearn":"Small privacy habits keep your footprint yours.","persona":"any","source":"reflect"},
  {"id":"fw-1406","cat":"think-before-share","type":"reflect","hook":"A friend's private photo lands in your chat. What's the kind move?","prompt":"Pick what feels right:","options":["Don't forward it on","Tell them so they can act","Delete it from your chat"],"affirm":"Each of these protects your friend. Not spreading it is the kind move.","relearn":"Not spreading a friend's private photo protects them.","persona":"any","source":"reflect"},
  {"id":"fw-1407","cat":"think-before-share","type":"reflect","hook":"What's true about a photo once you've sent it?","prompt":"Choose what to remember:","options":["I can't fully take it back","A screenshot is all it takes","It's worth pausing first"],"affirm":"All true, and none of it is about blame, it's about thinking first. 💛","relearn":"Once sent, a photo is hard to take back; that's why you pause first.","persona":"any","source":"reflect"},
  {"id":"fw-1408","cat":"think-before-share","type":"reflect","hook":"How do you want to feel about your posts a year from now?","prompt":"Pick what matters:","options":["Glad I shared it","Sure it was mine to share","Okay with anyone seeing it"],"affirm":"Posting with future-you in mind makes that easier. You're thinking ahead.","relearn":"Posting with future-you in mind keeps you glad you shared.","persona":"any","source":"reflect"},
  {"id":"fw-1409","cat":"think-before-share","type":"reflect","hook":"When does sharing feel right to you?","prompt":"Choose what fits:","options":["When it's genuinely my choice","When no one's pressuring me","When I'm not giving away details"],"affirm":"Sharing on your own terms, with no pressure, is exactly the idea. 💛","relearn":"Sharing feels right when it's your choice, with no pressure.","persona":"any","source":"reflect"},
  {"id":"fw-1410","cat":"think-before-share","type":"reflect","hook":"What reminds you that being pressured isn't your fault?","prompt":"Pick what you'd hold onto:","options":["The pressure is on them, not me","I can say no anytime","Being tricked isn't carelessness"],"affirm":"Whatever you chose, the fault sits with whoever pushes, never you. 💛","relearn":"Being pressured or tricked is never your fault.","persona":"Counsellor","source":"reflect"},
  {"id":"fw-1411","cat":"think-before-share","type":"match","hook":"Match each share moment to the smart move.","pairs":[{"left":"A crush asks for a private photo","right":"Hold your 'no'; pressure is the flag"},{"left":"A trend wants your live location","right":"Join in without the tag"},{"left":"A friend's private pic in chat","right":"Don't forward; tell them"},{"left":"You're posting while angry","right":"Save a draft, reread tomorrow"},{"left":"An app offers to auto-share","right":"Turn it off; keep it private"}],"relearn":"Each share moment has a calm, footprint-safe move you can take.","persona":"any","source":"think-before-share"},
  {"id":"fw-1412","cat":"think-before-share","type":"match","hook":"Match each pressure line to why it doesn't hold.","pairs":[{"left":"\"If you loved me you'd send it\"","right":"Love never needs a photo as proof"},{"left":"\"Everyone sends one\"","right":"Not everyone does; 'no' is okay"},{"left":"\"It'll disappear, so it's safe\"","right":"It can be screenshotted"},{"left":"\"Send it or we're done\"","right":"A threat to leave is control"},{"left":"\"You sent one before\"","right":"You can say no every time"}],"relearn":"Every pressure line has a calm, true reason it doesn't hold.","persona":"any","source":"pressure"},
  {"id":"fw-1413","cat":"think-before-share","type":"match","hook":"Match each thing to where it belongs.","pairs":[{"left":"A photo of your art","right":"Fine to post publicly"},{"left":"Your exact live location","right":"Keep it private"},{"left":"Your favourite movie","right":"Safe to share"},{"left":"Your home address","right":"Never post it"},{"left":"Your daily school timing","right":"Off public posts"}],"relearn":"Hobbies are fine to share; location, address and routine stay private.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1414","cat":"think-before-share","type":"match","hook":"Match each fact about a sent photo to what it means.","pairs":[{"left":"They can screenshot it","right":"It may not stay private"},{"left":"They can forward it","right":"It can reach people you didn't choose"},{"left":"It can resurface later","right":"Time doesn't erase it"},{"left":"Deleting your copy","right":"Doesn't delete theirs"},{"left":"Cropping your face","right":"Details can still identify you"}],"relearn":"Once sent, a photo is out of your control; that's why you think first.","persona":"any","source":"permanence"},
  {"id":"fw-1415","cat":"think-before-share","type":"match","hook":"Match each privacy worry to the right first step.","pairs":[{"left":"Strangers can DM you freely","right":"Limit who can message you"},{"left":"Old posts show your location","right":"Review and remove them"},{"left":"Your profile is fully public","right":"Set the account to private"},{"left":"A creepy follower keeps at it","right":"Block and report them"},{"left":"A weak password","right":"Make it strong, add two-factor"}],"relearn":"Each privacy worry has a concrete first step you can take today.","persona":"any","source":"settings / privacy"},
  {"id":"fw-1416","cat":"think-before-share","type":"match","hook":"Match each green-flag habit to the risk it shrinks.","pairs":[{"left":"Asking before posting a friend","right":"Sharing what they didn't agree to"},{"left":"Pausing before an angry post","right":"A permanent post you'll regret"},{"left":"Keeping live location off","right":"Strangers tracking you"},{"left":"Not forwarding private images","right":"Adding to someone's harm"},{"left":"Checking who can see a post","right":"Reaching the wrong people"}],"relearn":"Each thoughtful habit quietly shrinks a real risk before it starts.","persona":"any","source":"share habits"},
  {"id":"fw-1417","cat":"think-before-share","type":"match","hook":"Match each 'no' to the situation it answers.","pairs":[{"left":"\"I don't share my password\"","right":"Someone wants your login"},{"left":"\"I keep my live location off\"","right":"A dare to drop your location"},{"left":"\"It's not mine to share\"","right":"Asked to forward a private pic"},{"left":"\"I already said no\"","right":"Asking again for a photo"},{"left":"\"I don't post my address\"","right":"A stranger wants where you live"}],"relearn":"A short, clear line answers each pressure without owing an explanation.","persona":"any","source":"boundary voice"},
  {"id":"fw-1418","cat":"think-before-share","type":"match","hook":"Match each myth to the calm truth that flips it.","pairs":[{"left":"\"Cropping my face makes it safe\"","right":"Details still identify you"},{"left":"\"Deleting it makes it gone\"","right":"Copies survive on other phones"},{"left":"\"Sending first earns one back\"","right":"No one owes you a photo"},{"left":"\"A small account is private\"","right":"Posts travel beyond followers"},{"left":"\"Saying no is being difficult\"","right":"It's a healthy boundary"}],"relearn":"Every 'it's fine' myth about sharing has a calm truth that flips it.","persona":"any","source":"myth"},
  {"id":"fw-1419","cat":"think-before-share","type":"spot","hook":"Spot the two lines pressuring you to send a photo (the red flags).","scene":[{"id":"a","text":"\"If you really liked me you'd send a pic\"","trick":true},{"id":"b","text":"\"No worries if you'd rather not\"","trick":false},{"id":"c","text":"\"Send one or I'll think you're hiding something\"","trick":true},{"id":"d","text":"\"We can just chat, no pressure\"","trick":false},{"id":"e","text":"\"Take your time, your call\"","trick":false}],"why":"'If you liked me' and 'or I'll think...' are guilt and threat, the lines to catch.","relearn":"Guilt-trips and 'or else' lines are pressure; a real friend takes 'no'.","persona":"any","source":"pressure"},
  {"id":"fw-1420","cat":"think-before-share","type":"spot","hook":"Spot the two details that give away where you are (the red flags).","scene":[{"id":"a","text":"A photo of your favourite snack","trick":false},{"id":"b","text":"Your school's name on your uniform","trick":true},{"id":"c","text":"A drawing you made today","trick":false},{"id":"d","text":"A live location tag on the post","trick":true},{"id":"e","text":"A song you've had on repeat","trick":false}],"why":"The uniform name and live location tag both tell a stranger where to find you.","relearn":"School names and live location tags reveal where you are; keep them off posts.","persona":"any","source":"footprint / privacy"},
  {"id":"fw-1421","cat":"think-before-share","type":"spot","hook":"Spot the two moves that lose control of your photo (the red flags).","scene":[{"id":"a","text":"Keeping the photo only on your phone","trick":false},{"id":"b","text":"Sending it 'to one person you trust'","trick":true},{"id":"c","text":"Not taking the photo at all","trick":false},{"id":"d","text":"Posting it where it can be saved","trick":true},{"id":"e","text":"Talking to a friend instead","trick":false}],"why":"Sending or posting is when you lose control; the photo can be saved and spread.","relearn":"You lose control once you send or post a photo; not sharing keeps it yours.","persona":"any","source":"permanence"},
  {"id":"fw-1422","cat":"think-before-share","type":"spot","hook":"Spot the two requests you should refuse (the red flags).","scene":[{"id":"a","text":"A friend asks what game you play","trick":false},{"id":"b","text":"A stranger asks for your home address","trick":true},{"id":"c","text":"A classmate asks to study together","trick":false},{"id":"d","text":"Someone online asks for your OTP","trick":true},{"id":"e","text":"A cousin asks how exams went","trick":false}],"why":"Your home address and your OTP are what you never hand over; both are the flags.","relearn":"Never share your home address or OTP; the rest are normal, friendly questions.","persona":"any","source":"settings / privacy"},
  {"id":"fw-1423","cat":"think-before-share","type":"spot","hook":"Spot the two things here that aren't okay to forward (the red flags).","scene":[{"id":"a","text":"A funny public meme","trick":false},{"id":"b","text":"A classmate's private photo, no okay given","trick":true},{"id":"c","text":"A school event notice","trick":false},{"id":"d","text":"A friend's private DM, to mock them","trick":true},{"id":"e","text":"A photo your friend asked you to share","trick":false}],"why":"The private photo and the private DM aren't yours to spread; forwarding them is harm.","relearn":"Don't forward someone's private photo or chat; public, agreed posts are fine.","persona":"any","source":"never forward"},
  {"id":"fw-1424","cat":"think-before-share","type":"spot","hook":"Spot the two 'kind' lines that are still pressure (the red flags).","scene":[{"id":"a","text":"\"Take all the time you need\"","trick":false},{"id":"b","text":"\"I'd never share it, just trust me\"","trick":true},{"id":"c","text":"\"It's totally your choice\"","trick":false},{"id":"d","text":"\"Everyone does it, don't overthink\"","trick":true},{"id":"e","text":"\"I'm okay either way\"","trick":false}],"why":"'Just trust me' and 'everyone does it' are soft pushes; gentle pressure is still pressure.","relearn":"'Trust me' and 'everyone does it' are pressure dressed up as kindness.","persona":"any","source":"pressure"},
  {"id":"fw-1425","cat":"think-before-share","type":"spot","hook":"Spot the two posts that would shrink your privacy (the red flags).","scene":[{"id":"a","text":"A photo with your number visible","trick":true},{"id":"b","text":"A blurred-background selfie","trick":false},{"id":"c","text":"A post mapping your daily route","trick":true},{"id":"d","text":"A picture of a book you're reading","trick":false},{"id":"e","text":"A photo of clouds you liked","trick":false}],"why":"A visible number and a mapped route both hand strangers a way to reach you.","relearn":"A visible number or a mapped routine shrinks your privacy; keep both off posts.","persona":"any","source":"footprint"},
  {"id":"fw-1426","cat":"think-before-share","type":"spot","hook":"Spot the two replies that give away too much (the red flags).","scene":[{"id":"a","text":"\"I love that show too!\"","trick":false},{"id":"b","text":"\"I'm home alone till 8pm daily\"","trick":true},{"id":"c","text":"\"Maybe, I'll think about it\"","trick":false},{"id":"d","text":"\"Here's my exact flat number\"","trick":true},{"id":"e","text":"\"That sounds fun, tell me more\"","trick":false}],"why":"'Home alone till 8' and your exact flat tell a stranger when and where to find you.","relearn":"Don't reveal when you're alone or your exact address; keep that out of chats.","persona":"any","source":"footprint / strangers"},
];

